          yield Uint8Array.from(second === undefined ? [first] : [first, second]);
          for (;;) { const chunk = await input.chunk(); if (!chunk) return; yield chunk; }
        }
        if (members && first === 0) {
          let garbage = second !== undefined && second !== 0;
          for (;;) {
            const chunk = await input.chunk();
            if (!chunk) break;
            if (chunk.some(value => value !== 0)) garbage = true;
          }
          if (garbage) warn();
          return;
        }
        if (second === undefined) throw new Error("unexpected end of file");
        if (!members) throw new Error("not in gzip format");
        warn();
        return;
      }
      await header(input, Uint8Array.of(first, second));
      let crc = 0xffffffff;
      let size = 0;
      for await (const chunk of inflate(input, signal)) {
        crc = updateCrc(crc, chunk);
        size = (size + chunk.length) >>> 0;
        yield chunk;
      }
      const footer = await input.exact(8);
      const view = new DataView(footer.buffer, footer.byteOffset, footer.byteLength);
      if (((crc ^ 0xffffffff) >>> 0) !== view.getUint32(0, true)) throw new Error("incorrect data check (CRC)");
      if (size !== view.getUint32(4, true)) throw new Error("incorrect length check");
      members++;
    }
  } finally { await input.close(); }
}

import { readBytes, writeBytes, type CommandDefinition } from "../../../contracts/index.js";
import { define, diagnostic, output } from "../../internal.js";
import { planOperands, unchangedSource, writeFileOperand } from "./files.js";
import { parseOptions } from "./options.js";
import { chunkBytes, transform } from "./stream.js";

export function createCompressionCommands(): readonly CommandDefinition[] {
  return ["gzip", "gunzip", "zcat"].map((name) => define(name, async (context) => {
    const options = parseOptions(name, context.args);
    if (options.help) {
      await output(context, `Usage: ${name} [OPTION]... [FILE]...\n-c, --stdout, --to-stdout\n-d, --decompress, --uncompress\n-k, --keep\n-f, --force\n-t, --test\n-1..-9, --fast, --best\n-n, --no-name (always enabled)\n-h, --help\nNo FILE or FILE '-' uses stdin; file output uses private VFS staging.\n`);
      return { exitCode: 0 };
    }
    const plans = await planOperands(context, options);
    let exitCode = 0;
    for (const plan of plans) {
      try {
        let warned: boolean;
        if (plan.destination) warned = await writeFileOperand(context, plan, options);
        else {
          await unchangedSource(context, plan);
          const source = plan.source === "-" ? context.stdin
            : (signal: AbortSignal) => context.fs.readStream!(plan.source, { signal, chunkSize: chunkBytes });
          warned = await transform(source, async (bytes, signal) => {
            for await (const chunk of readBytes(bytes, signal)) {
              if (!options.test) await writeBytes(context.stdout, chunk, signal);
            }
          }, { ...options, force: options.force && (options.stdout || options.test || plan.source === "-") }, context.signal);
        }
        if (warned) {
          await diagnostic(context, new Error(`${plan.source}: decompression OK, trailing garbage ignored`));
          if (exitCode === 0) exitCode = 2;
        }
      } catch (error) {
        context.signal.throwIfAborted();
        await diagnostic(context, error);
        exitCode = 1;
      }
    }
    return { exitCode };
  }));
}

import { UsageError } from "../../internal.js";

export interface CompressionOptions {
  decompress: boolean;
  stdout: boolean;
  keep: boolean;
  force: boolean;
  test: boolean;
  help: boolean;
  level: number;
  operands: string[];
}

const aliases: Readonly<Record<string, string>> = {
  stdout: "c", "to-stdout": "c", decompress: "d", uncompress: "d", keep: "k",
  force: "f", test: "t", fast: "1", best: "9", "no-name": "n", help: "h",
};

export function parseOptions(command: string, args: readonly string[]): CompressionOptions {
  const result: CompressionOptions = {
    decompress: command !== "gzip", stdout: command === "zcat", keep: false,
    force: false, test: false, help: false, level: 6, operands: [],
  };
  let ended = false;
  for (const argument of args) {
    if (ended || argument === "-" || !argument.startsWith("-")) {
      result.operands.push(argument);
      continue;
    }
    if (argument === "--") { ended = true; continue; }
    const flags = argument.startsWith("--") ? aliases[argument.slice(2)] : argument.slice(1);
    if (!flags) throw new UsageError(`unrecognized option '${argument}'`);
    for (const flag of flags) {
      switch (flag) {
        case "c": result.stdout = true; break;
        case "d": result.decompress = true; break;
        case "k": result.keep = true; break;
        case "f": result.force = true; break;
        case "t": result.test = true; result.decompress = true; break;
        case "h": result.help = true; break;
        case "n": break;
        default:
          if (/^[1-9]$/u.test(flag)) result.level = Number(flag);
          else throw new UsageError(`invalid option -- '${flag}'`);
      }
    }
  }
  if (!result.operands.length) result.operands.push("-");
  return result;
}

import { Readable, PassThrough } from "node:stream";
import { pipeline } from "node:stream/promises";
import { setImmediate } from "node:timers/promises";
import { createGzip } from "node:zlib";
import { FsError, readBytes, type ByteSource } from "../../../contracts/index.js";
import type { CompressionOptions } from "./options.js";
import { gunzipMembers } from "./gunzip.js";

export const chunkBytes = 64 * 1024;
export const stagingLimit = 256 * 1024 * 1024;

async function* split(source: ByteSource, signal: AbortSignal): ByteSource {
  let emptyChunks = 0;
  for await (const chunk of readBytes(source, signal)) {
    if (!chunk.byteLength) {
      if (++emptyChunks >= 64) { await setImmediate(undefined, { signal }); emptyChunks = 0; }
      continue;
    }
    emptyChunks = 0;
    for (let offset = 0; offset < chunk.byteLength; offset += chunkBytes) {
      signal.throwIfAborted();
      yield chunk.slice(offset, offset + chunkBytes);
    }
  }
}

export async function transform(
  source: ByteSource | ((signal: AbortSignal) => ByteSource),
  consume: (output: ByteSource, signal: AbortSignal) => Promise<void>,
  options: CompressionOptions,
  parentSignal: AbortSignal,
  maxOutput = Infinity,
): Promise<boolean> {
  const controller = new AbortController();
  const signal = AbortSignal.any([parentSignal, controller.signal]);
  let failure: unknown;
  const fail = (error: unknown): void => {
    if (!controller.signal.aborted) { failure = error; controller.abort(error); }
  };
  let prepared: ByteSource = split(typeof source === "function" ? source(signal) : source, signal);
  let warned = false;
  if (options.decompress) prepared = gunzipMembers(prepared, signal, options.force, () => { warned = true; });
  const readable = Readable.from((async function* (): ByteSource {
    try { yield* prepared; }
    catch (error) { fail(error); throw error; }
  })(), { objectMode: false, highWaterMark: chunkBytes });
  const zlibOptions = { level: options.level, chunkSize: chunkBytes, highWaterMark: chunkBytes };
  const codec = options.decompress ? new PassThrough({ highWaterMark: chunkBytes }) : createGzip(zlibOptions);
  codec.on("error", fail);
  let consuming: Promise<void> | undefined;
  try {
    await pipeline(readable, codec, async (output: AsyncIterable<Uint8Array>) => {
      let consumed = false;
      let size = 0;
      try {
        consuming = consume((async function* (): ByteSource {
          for await (const chunk of readBytes(output, signal)) {
            if (chunk.length > maxOutput - size) throw new FsError("EFBIG", { message: `staged output exceeds ${maxOutput} bytes` });
            let bytes = chunk;
            if (!options.decompress && size <= 9 && size + chunk.length > 9) {
              bytes = chunk.slice();
              bytes[9 - size] = 255;
            }
            size += chunk.length;
            yield bytes;
          }
          consumed = true;
        })(), signal);
        await consuming;
        if (!consumed) throw new FsError("EIO", { message: "output consumer did not consume the complete stream" });
      } catch (error) { fail(error); throw error; }
    }, { signal });
  } catch (error) {
    parentSignal.throwIfAborted();
    throw failure ?? error;
  } finally {
    controller.abort();
    readable.destroy();
    codec.destroy();
    await consuming?.catch(() => {});
  }
  return warned;
}

import type { CommandContext, CommandDefinition } from "../../../contracts/index.js";
import { define, integer, options, output, requireOperands } from "../../internal.js";
import { sources, validatedOption } from "./shared.js";

interface Alphabet {
  readonly symbols: string;
  readonly bits: number;
  readonly quantum: number;
  readonly lengths: readonly number[];
}

const alphabets: Record<"base64" | "base32", Alphabet> = {
  base64: { symbols: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", bits: 6, quantum: 4, lengths: [2, 3, 4] },
  base32: { symbols: "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567", bits: 5, quantum: 8, lengths: [2, 4, 5, 7, 8] },
};

async function encode(context: CommandContext, files: readonly string[], alphabet: Alphabet, wrap: number): Promise<void> {
  let carry = 0;
  let bits = 0;
  let symbols = 0;
  let column = 0;
  let pending = "";
  const emit = (character: string): void => {
    pending += character;
    symbols = (symbols + 1) % alphabet.quantum;
    if (wrap && ++column === wrap) { pending += "\n"; column = 0; }
  };
  for await (const chunk of sources(context, files)) {
    for (const byte of chunk) {
      carry = (carry << 8) | byte;
      bits += 8;
      while (bits >= alphabet.bits) {
        bits -= alphabet.bits;
        emit(alphabet.symbols[(carry >> bits) & ((1 << alphabet.bits) - 1)]!);
      }
      carry &= (1 << bits) - 1;
    }
    if (pending) { await output(context, pending); pending = ""; }
  }
  if (bits) emit(alphabet.symbols[carry << (alphabet.bits - bits)]!);
  while (symbols) emit("=");
  if (wrap && column) pending += "\n";
  if (pending) await output(context, pending);
}

function decodeQuantum(quantum: readonly number[], alphabet: Alphabet): { bytes: number[]; valid: boolean } {
  const decoded: number[] = [];
  if (alphabet.bits === 5 && quantum.length < alphabet.quantum) return { bytes: decoded, valid: false };
  let carry = 0;
  let bits = 0;
  let length = 0;
  while (length < quantum.length && quantum[length]! >= 0) {
    carry = (carry << alphabet.bits) | quantum[length++]!;
    bits += alphabet.bits;
    if (bits >= 8) { bits -= 8; decoded.push((carry >> bits) & 255); }
    carry &= (1 << bits) - 1;
  }
  return { bytes: decoded, valid: quantum.length === alphabet.quantum && alphabet.lengths.includes(length)
    && quantum.slice(length).every(number => number === -1) && carry === 0 };
}

async function decode(context: CommandContext, files: readonly string[], alphabet: Alphabet, ignore: boolean): Promise<void> {
  const lookup = new Int16Array(256).fill(-2);
  for (let index = 0; index < alphabet.symbols.length; index++) lookup[alphabet.symbols.charCodeAt(index)] = index;
  lookup[61] = -1;
  let quantum: number[] = [];
  let lastByte: number | undefined;
  for await (const chunk of sources(context, files)) {
    const pending: number[] = [];
    let invalid = false;
    for (const byte of chunk) {
      const symbol = lookup[byte]!;
      if (ignore && symbol === -2) continue;
      lastByte = byte;
      if (byte === 10) continue;
      quantum.push(symbol);
      if (quantum.length === alphabet.quantum) {
        const decoded = decodeQuantum(quantum, alphabet);
        pending.push(...decoded.bytes);
        if (!decoded.valid) { invalid = true; break; }
        quantum = [];
      }
    }
    if (pending.length) await output(context, Uint8Array.from(pending));
    if (invalid) throw new Error("invalid input");
  }
  if (quantum.length) {
    if (lastByte !== 61) while (quantum.length < alphabet.quantum) quantum.push(-1);
    const decoded = decodeQuantum(quantum, alphabet);
    if (decoded.bytes.length) await output(context, Uint8Array.from(decoded.bytes));
    if (!decoded.valid) throw new Error("invalid input");
  }
}

export function createBaseCommand(name: "base64" | "base32"): CommandDefinition {
  return define(name, async context => {
    const parsed = options(context.args, "diw:", { decode: "d", "ignore-garbage": "i", wrap: "w" });
    requireOperands(parsed.operands, 0, 1);
    const wrap = validatedOption(parsed, "w", integer, 76);
    if (parsed.flags.has("d")) await decode(context, parsed.operands, alphabets[name], parsed.flags.has("i"));
    else await encode(context, parsed.operands, alphabets[name], wrap);
    return { exitCode: 0 };
  });
}

import type { CommandDefinition } from "../../../contracts/index.js";
import { createBaseCommand } from "./base.js";
import { createOdCommand } from "./od.js";
import { createXxdCommand } from "./xxd.js";

export function createEncodingCommands(): readonly CommandDefinition[] {
  return [createBaseCommand("base64"), createBaseCommand("base32"), createXxdCommand(), createOdCommand()];
}

import type { CommandDefinition } from "../../../contracts/index.js";
import { define, options, output, UsageError } from "../../internal.js";
import { addOffset, numeric, range, rows, sources, validatedOption } from "./shared.js";

interface Format { readonly kind: string; readonly size: number }

function formats(text: string): Format[] {
  const result: Format[] = [];
  for (let offset = 0; offset < text.length;) {
    const match = /^(c|[doux](?:1|2|4|8))/u.exec(text.slice(offset));
    if (!match) throw new UsageError(`unsupported type '${text}': use c or d/o/u/x with size 1, 2, 4, or 8`);
    result.push({ kind: match[0][0]!, size: match[0] === "c" ? 1 : Number(match[0][1]) });
    offset += match[0].length;
    if (result.length > 16) throw new UsageError("at most 16 output types are supported");
  }
  if (!result.length) throw new UsageError("empty output type");
  return result;
}

function formatRow(row: Uint8Array, format: Format, bigEndian: boolean): string {
  let text = "";
  const escapes: Record<number, string> = { 0: "\\0", 7: "\\a", 8: "\\b", 9: "\\t", 10: "\\n", 11: "\\v", 12: "\\f", 13: "\\r" };
  for (let offset = 0; offset < row.length; offset += format.size) {
    if (format.kind === "c") {
      const byte = row[offset]!;
      const character = escapes[byte] ?? (byte >= 32 && byte <= 126 ? String.fromCharCode(byte) : byte.toString(8).padStart(3, "0"));
      text += ` ${character.padStart(3)}`;
      continue;
    }
    let number = 0n;
    for (let index = 0; index < format.size; index++) {
      const byte = row[offset + index] ?? 0;
      const shift = bigEndian ? format.size - index - 1 : index;
      number |= BigInt(byte) << BigInt(shift * 8);
    }
    const bits = format.size * 8;
    if (format.kind === "d" && number >= 1n << BigInt(bits - 1)) number -= 1n << BigInt(bits);
    const base = format.kind === "o" ? 8 : format.kind === "x" ? 16 : 10;
    const width = format.kind === "o" ? Math.ceil(bits / 3) : format.kind === "x" ? bits / 4
      : format.kind === "d" ? (1n << BigInt(bits - 1)).toString().length + 1 : ((1n << BigInt(bits)) - 1n).toString().length;
    text += ` ${number.toString(base).padStart(width, base === 10 ? " " : "0")}`;
  }
  return text;
}

export function createOdCommand(): CommandDefinition {
  return define("od", async context => {
    const aliases: Record<string, string> = { b: "o1", c: "c", d: "u2", o: "o2", s: "d2", x: "x2" };
    const rewritten: string[] = [];
    let ended = false;
    for (let index = 0; index < context.args.length; index++) {
      const argument = context.args[index]!;
      if (ended || argument === "-" || !argument.startsWith("-")) { rewritten.push(argument); continue; }
      if (argument === "--") { ended = true; rewritten.push(argument); continue; }
      if (argument.startsWith("--")) {
        rewritten.push(argument);
        if (!argument.includes("=") && ["--address-radix", "--skip-bytes", "--read-bytes", "--format", "--type", "--width", "--endian"].includes(argument)) {
          const parameter = context.args[++index];
          if (parameter === undefined) throw new UsageError(`option '${argument}' requires an argument`);
          rewritten.push(parameter);
        }
        continue;
      }
      for (let offset = 1; offset < argument.length; offset++) {
        const flag = argument[offset]!;
        if (flag === "e") throw new UsageError("use --endian=little or --endian=big; -e is unsupported");
        if (aliases[flag]) rewritten.push(`-t${aliases[flag]}`);
        else if ("AjNtw".includes(flag)) {
          const parameter = argument.slice(offset + 1) || context.args[++index];
          if (parameter === undefined) throw new UsageError(`option '-${flag}' requires an argument`);
          rewritten.push(`-${flag}`, parameter);
          break;
        } else rewritten.push(`-${flag}`);
      }
    }
    const parsed = options(rewritten, "vA:j:N:t:w:e:", { "address-radix": "A", "skip-bytes": "j", "read-bytes": "N", format: "t", type: "t", width: "w", endian: "e", "output-duplicates": "v" });
    const radix = validatedOption(parsed, "A", text => {
      if (!["d", "o", "x", "n"].includes(text)) throw new UsageError("address radix must be d, o, x, or n");
      return text;
    }, "o");
    const endian = validatedOption(parsed, "e", text => {
      if (text !== "little" && text !== "big") throw new UsageError("endian must be little or big");
      return text;
    }, "little");
    const selected = (parsed.values.get("t") ?? ["o2"]).flatMap(formats);
    if (selected.length > 16) throw new UsageError("at most 16 output types are supported");
    const width = validatedOption(parsed, "w", text => {
      const number = numeric(text);
      if (number < 1 || number > 4096 || selected.some(format => number % format.size !== 0)) throw new UsageError("width must be 1..4096 and a multiple of each output type size");
      return number;
    }, 16);
    const skip = validatedOption(parsed, "j", text => numeric(text, true), 0);
    const count = validatedOption(parsed, "N", text => numeric(text, true), Infinity);
    let offset = skip;
    let previous: Uint8Array | undefined;
    let suppressed = false;
    const address = (): string => radix === "n" ? "" : offset.toString(radix === "o" ? 8 : radix === "x" ? 16 : 10).padStart(7, "0");
    for await (const row of rows(range(sources(context, parsed.operands), skip, count), width)) {
      const same = previous?.length === row.length && row.every((byte, index) => previous![index] === byte);
      if (!parsed.flags.has("v") && same) {
        if (!suppressed) await output(context, "*\n");
        suppressed = true;
      } else {
        for (let index = 0; index < selected.length; index++) {
          const prefix = index === 0 ? address() : " ".repeat(address().length);
          await output(context, `${prefix}${formatRow(row, selected[index]!, endian === "big")}\n`);
        }
        previous = row;
        suppressed = false;
      }
      offset = addOffset(offset, row.length);
    }
    if (radix !== "n") await output(context, `${address()}\n`);
    return { exitCode: 0 };
  });
}

import { setImmediate } from "node:timers/promises";
import { FsError, readBytes, type ByteSource, type CommandContext } from "../../../contracts/index.js";
import { pathOf, UsageError, type ParsedOptions } from "../../internal.js";

export const blockSize = 8192;

export function validatedOption<Value>(parsed: ParsedOptions, key: string, parse: (text: string) => Value, fallback: Value): Value {
  let result = fallback;
  for (const text of parsed.values.get(key) ?? []) result = parse(text);
  return result;
}

export async function* sources(context: CommandContext, operands: readonly string[]): ByteSource {
  let usedStdin = false;
  let emptyChunks = 0;
  for (const operand of operands.length ? operands : ["-"]) {
    context.signal.throwIfAborted();
    let source: ByteSource;
    if (operand === "-") {
      if (usedStdin) continue;
      usedStdin = true;
      source = context.stdin;
    } else {
      const path = pathOf(context, operand);
      if (!context.fs.readStream) throw new FsError("ENOTSUP", { path, syscall: "readStream", message: "encoding commands require a streaming-read filesystem" });
      source = context.fs.readStream(path, { signal: context.signal, chunkSize: blockSize });
    }
    for await (const chunk of readBytes(source, context.signal)) {
      if (chunk.length === 0 && ++emptyChunks % 64 === 0) {
        await setImmediate();
        context.signal.throwIfAborted();
      }
      for (let offset = 0; offset < chunk.length; offset += blockSize) {
        await setImmediate();
        context.signal.throwIfAborted();
        yield chunk.subarray(offset, offset + blockSize);
      }
    }
  }
}

export async function* range(source: ByteSource, skip: number, count: number): ByteSource {
  if (!skip && !count) return;
  for await (const chunk of source) {
    const skipped = Math.min(skip, chunk.length);
    skip -= skipped;
    const length = Math.min(count, chunk.length - skipped);
    if (length) {
      yield chunk.subarray(skipped, skipped + length);
      count -= length;
    }
    if (!skip && !count) return;
  }
  if (skip) throw new Error("cannot skip past end of input");
}

export async function* rows(source: ByteSource, width: number): ByteSource {
  const row = new Uint8Array(width);
  let used = 0;
  for await (const chunk of source) {
    for (let offset = 0; offset < chunk.length;) {
      const length = Math.min(width - used, chunk.length - offset);
      row.set(chunk.subarray(offset, offset + length), used);
      offset += length;
      used += length;
      if (used === width) { yield row.slice(); used = 0; }
    }
  }
  if (used) yield row.slice(0, used);
}

export function numeric(text: string, suffixes = false): number {
  let numberText = text;
  let multiplier = 1;
  if (suffixes && !/^0[xX][0-9a-fA-F]+$/u.test(text)) {
    const match = /^(.*?)(KiB|MiB|GiB|KB|MB|GB|[bkmKMG])$/u.exec(text);
    if (match) {
      numberText = match[1] || "1";
      multiplier = ({ b: 512, k: 1024, K: 1024, KiB: 1024, m: 1048576, M: 1048576, MiB: 1048576, G: 1073741824, GiB: 1073741824, KB: 1000, MB: 1000000, GB: 1000000000 } as Record<string, number>)[match[2]!]!;
    }
  }
  let parsed: number;
  if (/^0[xX][0-9a-fA-F]+$/u.test(numberText)) parsed = Number.parseInt(numberText.slice(2), 16);
  else if (/^0[0-7]*$/u.test(numberText)) parsed = Number.parseInt(numberText, 8);
  else if (/^[1-9][0-9]*$/u.test(numberText)) parsed = Number(numberText);
  else throw new UsageError(`invalid number '${text}'`);
  parsed *= multiplier;
  if (!Number.isSafeInteger(parsed)) throw new UsageError(`number out of range '${text}'`);
  return parsed;
}

export function addOffset(offset: number, length: number): number {
  const result = offset + length;
  if (!Number.isSafeInteger(result)) throw new Error("input address exceeds safe integer range");
  return result;
}

import type { CommandContext, CommandDefinition } from "../../../contracts/index.js";
import { define, options, output, requireOperands, UsageError } from "../../internal.js";
import { addOffset, numeric, range, rows, sources, validatedOption } from "./shared.js";

function hexDigit(byte: number): number {
  if (byte >= 48 && byte <= 57) return byte - 48;
  if (byte >= 65 && byte <= 70) return byte - 55;
  if (byte >= 97 && byte <= 102) return byte - 87;
  return -1;
}

async function reversePlain(context: CommandContext, files: readonly string[]): Promise<void> {
  let high = -1;
  for await (const chunk of sources(context, files)) {
    const pending: number[] = [];
    let invalid = false;
    for (const byte of chunk) {
      if (byte === 32 || (byte >= 9 && byte <= 13)) continue;
      const digit = hexDigit(byte);
      if (digit < 0) { invalid = true; break; }
      if (high < 0) high = digit;
      else { pending.push((high << 4) | digit); high = -1; }
    }
    if (pending.length) await output(context, Uint8Array.from(pending));
    if (invalid) throw new Error("invalid input: expected hexadecimal digits or ASCII whitespace");
  }
  if (high >= 0) throw new Error("invalid input: unmatched hexadecimal digit");
}

async function reverseNormal(context: CommandContext, files: readonly string[], columns: number): Promise<void> {
  let line = "";
  let offset = 0;
  const emitLine = async (): Promise<void> => {
    if (!line.trim()) { line = ""; return; }
    const match = /^([0-9a-fA-F]{1,14}):[ \t]?(.*)$/u.exec(line.replace(/\r$/u, ""));
    if (!match) throw new Error("invalid input: expected hexadecimal address and colon");
    const address = Number.parseInt(match[1]!, 16);
    if (!Number.isSafeInteger(address) || address !== offset) throw new Error("invalid input: reverse requires contiguous addresses starting at zero");
    const field = match[2]!.split(/ {2,}|\t/u, 1)[0]!;
    if (!/^(?:[0-9a-fA-F]{2})+(?: (?:[0-9a-fA-F]{2})+)*$/u.test(field)) throw new Error("invalid input: malformed hexadecimal data field");
    const digits = field.replaceAll(" ", "");
    if (digits.length > columns * 2) throw new Error("invalid input: data exceeds configured columns");
    const bytes = new Uint8Array(digits.length / 2);
    for (let index = 0; index < bytes.length; index++) bytes[index] = Number.parseInt(digits.slice(index * 2, index * 2 + 2), 16);
    offset = addOffset(offset, bytes.length);
    await output(context, bytes);
    line = "";
  };
  for await (const chunk of sources(context, files)) {
    for (const byte of chunk) {
      if (byte === 10) await emitLine();
      else {
        if (line.length >= 4096) throw new Error("invalid input: reverse line exceeds 4096 bytes");
        line += String.fromCharCode(byte);
      }
    }
  }
  if (line) await emitLine();
}

export function createXxdCommand(): CommandDefinition {
  return define("xxd", async context => {
    const aliases: Record<string, string> = { "-ps": "-p", "-plain": "-p", "-postscript": "-p", "-revert": "-r", "-cols": "-c", "-groupsize": "-g", "-len": "-l" };
    let ended = false;
    const args = context.args.map(argument => {
      if (ended) return argument;
      if (argument === "--") ended = true;
      return aliases[argument] ?? argument;
    });
    const parsed = options(args, "prduc:g:l:s:o:");
    requireOperands(parsed.operands, 0, 2);
    if (parsed.operands[1] !== undefined && parsed.operands[1] !== "-") throw new UsageError("output-file operands are not supported; output is stdout only");
    const files = parsed.operands.slice(0, 1);
    const plain = parsed.flags.has("p");
    const reverse = parsed.flags.has("r");
    const columns = validatedOption(parsed, "c", text => {
      const number = numeric(text);
      if ((!plain && (number < 1 || number > 256)) || (plain && number > 4096)) throw new UsageError("columns must be 1..256 (plain: 0..4096)");
      return number;
    }, plain ? 30 : 16);
    const group = validatedOption(parsed, "g", text => {
      const number = numeric(text);
      if (number > 256) throw new UsageError("group size must be 0..256");
      return number;
    }, 2);
    const skip = validatedOption(parsed, "s", numeric, 0);
    const count = validatedOption(parsed, "l", numeric, Infinity);
    const displacement = validatedOption(parsed, "o", numeric, 0);
    if (reverse && ["s", "l", "o", "d"].some(flag => parsed.flags.has(flag))) throw new UsageError("reverse does not support seek, length, displacement, or decimal addresses");
    if (reverse) {
      if (plain) await reversePlain(context, files);
      else await reverseNormal(context, files, columns);
      return { exitCode: 0 };
    }
    let offset = addOffset(skip, displacement);
    const source = range(sources(context, files), skip, count);
    let any = false;
    for await (const row of rows(source, plain && !columns ? 4096 : columns)) {
      any = true;
      let data = "";
      let ascii = "";
      for (let index = 0; index < row.length; index++) {
        if (!plain && group && index && index % group === 0) data += " ";
        const byte = row[index]!;
        data += byte.toString(16).padStart(2, "0");
        ascii += byte >= 32 && byte <= 126 ? String.fromCharCode(byte) : ".";
      }
      if (parsed.flags.has("u")) data = data.toUpperCase();
      if (plain) await output(context, data + (columns ? "\n" : ""));
      else {
        const width = columns * 2 + (group ? Math.floor((columns - 1) / group) : 0);
        const address = offset.toString(parsed.flags.has("d") ? 10 : 16).padStart(8, "0");
        await output(context, `${address}: ${data.padEnd(width)}  ${ascii}\n`);
      }
      offset = addOffset(offset, row.length);
    }
    if (plain && !columns && any) await output(context, "\n");
    return { exitCode: 0 };
  });
}

