import { UsageError, type ParsedOptions } from "./internal.js";

export class EnvSplitError extends Error {}

class SplitWork {
  private bytes = 0;
  private arguments = 0;
  private expansions = 0;
  private work = 0;
  private nextYield = 4096;

  constructor(private readonly signal: AbortSignal) {}

  account(text: string): void {
    this.signal.throwIfAborted();
    if (text.length > 131072 - this.bytes) throw new EnvSplitError("split-string byte limit exceeded (131072)");
    this.bytes += Buffer.byteLength(text);
    if (this.bytes > 131072) throw new EnvSplitError("split-string byte limit exceeded (131072)");
    if (text.includes("\0")) throw new EnvSplitError("NUL is not supported in -S strings");
  }

  argument(): void {
    if (++this.arguments > 10000) throw new EnvSplitError("split-string argument limit exceeded (10000)");
  }

  expansion(): void {
    this.signal.throwIfAborted();
    if (++this.expansions > 32) throw new EnvSplitError("split-string expansion limit exceeded (32)");
    if (this.work > 1048576) throw new EnvSplitError("split-string work limit exceeded (1048576)");
  }

  tick(amount = 1): boolean {
    this.signal.throwIfAborted();
    this.work += amount;
    if (this.expansions && this.work > 1048576) throw new EnvSplitError("split-string work limit exceeded (1048576)");
    return this.work >= this.nextYield;
  }

  async pause(): Promise<void> {
    await new Promise<void>(resolve => setImmediate(resolve));
    this.signal.throwIfAborted();
    this.nextYield = this.work + 4096;
  }
}

async function splitString(source: string, environment: Readonly<Record<string, string>>, work: SplitWork): Promise<string[]> {
  work.expansion();
  work.account(source);
  const result: string[] = [];
  let parts: string[] = [];
  let active = false;
  let quote = "";
  const start = () => {
    if (!active) { work.argument(); active = true; }
  };
  const append = (text: string) => {
    work.account(text);
    start();
    parts.push(text);
  };
  const finish = () => {
    if (active) result.push(parts.join(""));
    parts = [];
    active = false;
  };
  for (let index = 0; index < source.length;) {
    if (work.tick()) await work.pause();
    const character = String.fromCodePoint(source.codePointAt(index)!);
    if ((character === "'" || character === '"') && (!quote || character === quote)) {
      start();
      quote = quote ? "" : character;
      index++;
      continue;
    }
    if (!quote && /[ \t\n\r\v\f]/u.test(character)) {
      finish();
      index++;
      continue;
    }
    if (character === "#" && !active) break;
    if (character === "\\" && (quote !== "'" || source[index + 1] === "\\" || source[index + 1] === "'")) {
      const escaped = source[index + 1];
      if (escaped === undefined) throw new EnvSplitError("invalid backslash at end of string in -S");
      index += 2;
      if (escaped === "c") {
        if (quote === '"') throw new EnvSplitError("'\\c' must not appear in double-quoted -S string");
        break;
      }
      if (escaped === "_") {
        if (quote === '"') append(" ");
        else finish();
        continue;
      }
      const controls: Readonly<Record<string, string>> = { f: "\f", n: "\n", r: "\r", t: "\t", v: "\v" };
      if (Object.hasOwn(controls, escaped)) append(controls[escaped]!);
      else if ('"#$\'\\'.includes(escaped)) append(escaped);
      else throw new EnvSplitError(`invalid sequence '\\${escaped}' in -S`);
      continue;
    }
    if (character === "$" && quote !== "'") {
      let end = index + 2;
      if (source[index + 1] !== "{" || !/^[A-Za-z_]$/u.test(source[end] ?? "")) {
        throw new EnvSplitError(`only \${VARNAME} expansion is supported, error at: ${source.slice(index)}`);
      }
      while (/^[A-Za-z_0-9]$/u.test(source[end] ?? "")) {
        if (work.tick()) await work.pause();
        end++;
      }
      if (source[end] !== "}") throw new EnvSplitError(`only \${VARNAME} expansion is supported, error at: ${source.slice(index)}`);
      const name = source.slice(index + 2, end);
      if (Object.hasOwn(environment, name)) {
        const text = environment[name]!;
        append(text);
        if (work.tick(text.length)) await work.pause();
      }
      index = end + 1;
      continue;
    }
    append(character);
    index += character.length;
  }
  if (quote) throw new EnvSplitError("no terminating quote in -S string");
  finish();
  return result;
}

export async function parseEnvOptions(
  args: readonly string[], environment: Readonly<Record<string, string>>, signal: AbortSignal,
): Promise<ParsedOptions> {
  const work = new SplitWork(signal);
  const frames: { args: readonly string[]; offset: number }[] = [{ args, offset: 0 }];
  const next = (): string | undefined => {
    while (frames.length) {
      const frame = frames.at(-1)!;
      if (frame.offset < frame.args.length) return frame.args[frame.offset++];
      frames.pop();
    }
    return undefined;
  };
  const flags = new Set<string>();
  const values = new Map<string, string[]>();
  const operands: string[] = [];
  const longOptions = new Map([
    ["ignore-environment", "i"], ["unset", "u"], ["null", "0"], ["chdir", "C"], ["split-string", "S"],
  ]);
  const accept = async (key: string, content?: string) => {
    if (key === "S") {
      const expanded = await splitString(content!, environment, work);
      frames.push({ args: expanded, offset: 0 });
    } else {
      flags.add(key);
      if (content !== undefined) {
        const entries = values.get(key) ?? [];
        entries.push(content);
        values.set(key, entries);
      }
    }
  };
  for (;;) {
    const argument = next();
    if (argument === undefined) break;
    if (work.tick(argument.length + 1)) await work.pause();
    if (argument === "--") break;
    if (argument === "-" || !argument.startsWith("-")) { operands.push(argument); break; }
    if (argument.startsWith("--")) {
      const equals = argument.indexOf("=");
      const name = argument.slice(2, equals < 0 ? undefined : equals);
      const key = longOptions.get(name);
      if (!key) throw new UsageError(`unrecognized option '${argument}'`);
      const required = key === "u" || key === "C" || key === "S";
      if (!required && equals >= 0) throw new UsageError(`option '--${name}' does not take an argument`);
      const content = required ? equals < 0 ? next() : argument.slice(equals + 1) : undefined;
      if (required && content === undefined) throw new UsageError(`option '--${name}' requires an argument`);
      await accept(key, content);
      continue;
    }
    for (let index = 1; index < argument.length; index++) {
      if (work.tick()) await work.pause();
      const key = argument[index]!;
      if (key !== "i" && key !== "u" && key !== "0" && key !== "C" && key !== "S") throw new UsageError(`invalid option -- '${key}'`);
      const required = key === "u" || key === "C" || key === "S";
      const content = required ? argument.slice(index + 1) || next() : undefined;
      if (required && content === undefined) throw new UsageError(`option requires an argument -- '${key}'`);
      await accept(key, content);
      if (required) break;
    }
  }
  for (;;) {
    const argument = next();
    if (argument === undefined) break;
    if (work.tick()) await work.pause();
    operands.push(argument);
  }
  if (operands[0] === "-") { flags.add("i"); operands.shift(); }
  signal.throwIfAborted();
  return { flags, values, operands };
}

import { Budget, ExprError, nextCharacter, requireByteCollation, utf8Profile } from "./internal.js";

export interface IntegerValue { readonly number: bigint; readonly text: string }
export type Value = Uint8Array | IntegerValue;
export type Matcher = (subject: Uint8Array, pattern: Uint8Array, unicode: boolean) => Promise<Value>;

export function smallInteger(value: number, budget: Budget): IntegerValue {
  const text = String(value);
  budget.check(text.length, budget.limits.maxNumericDigits, "numeric result digits");
  budget.charge(text.length);
  return { number: BigInt(value), text };
}

export const zeroValue: IntegerValue = { number: 0n, text: "0" };

export function bytes(value: Value, budget: Budget): Uint8Array {
  return value instanceof Uint8Array ? value : budget.encode(value.text);
}

export function truth(value: Value, budget: Budget): boolean {
  if (!(value instanceof Uint8Array)) return value.number !== 0n;
  budget.charge(value.length);
  if (!value.length) return false;
  const start = value[0] === 45 ? 1 : 0;
  if (start === value.length) return true;
  for (let offset = start; offset < value.length; offset++) if (value[offset] !== 48) return true;
  return false;
}

function numericShape(value: Value, budget: Budget): boolean {
  if (!(value instanceof Uint8Array)) return true;
  budget.charge(value.length);
  const start = value[0] === 45 ? 1 : 0;
  if (start === value.length) return false;
  for (let offset = start; offset < value.length; offset++) {
    if (value[offset]! < 48 || value[offset]! > 57) return false;
  }
  return true;
}

function numeric(value: Value, budget: Budget): bigint | undefined {
  if (!(value instanceof Uint8Array)) return value.number;
  if (!numericShape(value, budget)) return undefined;
  const start = value[0] === 45 ? 1 : 0;
  budget.check(value.length - start, budget.limits.maxNumericDigits, "numeric digits");
  budget.charge(value.length * value.length);
  budget.allocation(value.length);
  return BigInt(new TextDecoder().decode(value));
}

function integer(value: Value, budget: Budget): bigint {
  const result = numeric(value, budget);
  if (result === undefined) throw new ExprError("non-integer argument");
  return result;
}

function arithmetic(operator: string, left: Value, right: Value, budget: Budget): IntegerValue {
  const first = integer(left, budget), second = integer(right, budget);
  if ((operator === "/" || operator === "%") && second === 0n) throw new ExprError("division by zero");
  const firstDigits = left instanceof Uint8Array ? left.length : left.text.length;
  const secondDigits = right instanceof Uint8Array ? right.length : right.text.length;
  const upper = operator === "*" ? firstDigits + secondDigits : Math.max(firstDigits, secondDigits) + 1;
  budget.allocation(upper + 1);
  budget.charge(firstDigits * secondDigits);
  const result = operator === "+" ? first + second : operator === "-" ? first - second
    : operator === "*" ? first * second : operator === "/" ? first / second : first % second;
  const resultText = result.toString();
  budget.check(resultText.length - (result < 0n ? 1 : 0), budget.limits.maxNumericDigits, "arithmetic result digits");
  return { number: result, text: resultText };
}

function compare(left: Value, right: Value, budget: Budget): number {
  if (numericShape(left, budget) && numericShape(right, budget)) {
    const first = integer(left, budget), second = integer(right, budget);
    return first < second ? -1 : first > second ? 1 : 0;
  }
  requireByteCollation(budget.context);
  const firstBytes = bytes(left, budget), secondBytes = bytes(right, budget);
  budget.charge(Math.min(firstBytes.length, secondBytes.length));
  for (let offset = 0; offset < Math.min(firstBytes.length, secondBytes.length); offset++) {
    if (firstBytes[offset] !== secondBytes[offset]) return firstBytes[offset]! - secondBytes[offset]!;
  }
  return firstBytes.length - secondBytes.length;
}

export function characterCount(value: Uint8Array, budget: Budget, unicode: boolean): number {
  budget.charge(value.length);
  if (!unicode) return value.length;
  let count = 0;
  for (let offset = 0; offset < value.length; offset = nextCharacter(value, offset, true)) count++;
  return count;
}

export async function evaluateCall(operator: string, values: readonly Value[], budget: Budget, match: Matcher): Promise<Value> {
  const subject = bytes(values[0]!, budget);
  const unicode = utf8Profile(budget.context);
  if (operator === "match") return match(subject, bytes(values[1]!, budget), unicode);
  if (operator === "length") return smallInteger(characterCount(subject, budget, unicode), budget);
  if (operator === "index") {
    const accept = bytes(values[1]!, budget);
    let position = 0;
    for (let offset = 0; offset < subject.length;) {
      const end = nextCharacter(subject, offset, unicode);
      position++;
      for (let candidate = 0; candidate < accept.length;) {
        const candidateEnd = nextCharacter(accept, candidate, unicode);
        budget.charge(1 + end - offset);
        if (end - offset === candidateEnd - candidate) {
          let equal = true;
          for (let byte = 0; byte < end - offset; byte++) if (subject[offset + byte] !== accept[candidate + byte]) equal = false;
          if (equal) return smallInteger(position, budget);
        }
        candidate = candidateEnd;
        await budget.yield();
      }
      offset = end;
      await budget.yield();
    }
    return zeroValue;
  }
  const position = numeric(values[1]!, budget), length = numeric(values[2]!, budget);
  if (position === undefined || length === undefined || position <= 0n || length <= 0n || position > BigInt(subject.length)) return new Uint8Array();
  const startIndex = Number(position - 1n), wanted = Number(length > BigInt(subject.length) ? BigInt(subject.length) : length);
  let start = 0, end = 0, index = 0;
  budget.charge(subject.length);
  while (start < subject.length && index++ < startIndex) start = nextCharacter(subject, start, unicode);
  end = start;
  for (let count = 0; count < wanted && end < subject.length; count++) end = nextCharacter(subject, end, unicode);
  budget.allocation(end - start);
  return new Uint8Array(subject.subarray(start, end));
}

export async function evaluateBinary(operator: string, left: Value, right: Value, budget: Budget, match: Matcher): Promise<Value> {
  if (["<", "<=", "=", "==", "!=", ">=", ">"].includes(operator)) {
    const order = compare(left, right, budget);
    return smallInteger(Number(operator === "<" ? order < 0 : operator === "<=" ? order <= 0
      : operator === ">" ? order > 0 : operator === ">=" ? order >= 0 : operator === "!=" ? order !== 0 : order === 0), budget);
  }
  if (operator === ":") return match(bytes(left, budget), bytes(right, budget), utf8Profile(budget.context));
  return arithmetic(operator, left, right, budget);
}

import { writeBytes, type CommandDefinition, type VirtualShellPlugin } from "../../contracts/index.js";
import { RegexExecutor, RegexExecutionError, withRegexSession } from "../regex-execution/client.js";
import { ExprMatchError, exprMatchCeilings } from "../regex-execution/protocol.js";
import { bytes, characterCount, smallInteger, truth } from "./evaluate.js";
import { Budget, ExprError, screenMatch, settings, type ExprCommandsOptions } from "./internal.js";
import { evaluateExpression } from "./syntax.js";

export type { ExprCommandsOptions, ExprLimits } from "./internal.js";

const help = "Usage: expr EXPRESSION\nTokens: | & < <= = == != >= > + - * / % :\nPrefixes: + TOKEN, length STRING, index STRING CHARS, substr STRING POS LENGTH, match STRING REGEXP\nGroup with ( EXPRESSION ). Each token is a separate argument.\nMatching uses bounded worker-only BRE in C/POSIX byte or C.UTF-8 scalar profiles.\n";

export function createExprCommand(options: ExprCommandsOptions = {}): CommandDefinition {
  const limits = settings(options);
  const executor = new RegexExecutor(options.regex);
  return { name: "expr", description: "Evaluate bounded integer and string expressions", async execute(context) {
    return withRegexSession(context, executor, async session => {
      context.signal.throwIfAborted();
      const budget = new Budget(context, limits);
      let output: Uint8Array;
      let exitCode = 0;
      try {
        budget.arguments();
        if (context.args.length === 1 && ["--help", "--version"].includes(context.args[0]!)) {
          const text = context.args[0] === "--help" ? help : "expr (virtual-bash)\n";
          budget.check(Buffer.byteLength(text), limits.maxOutputBytes, "output bytes");
          output = budget.encode(text);
        } else {
          const value = await evaluateExpression(context.args, budget, async (subject, pattern, unicode) => {
            budget.charge();
            screenMatch(subject, pattern, budget);
            if (budget.remaining() < 1) throw new ExprError("evaluation work limit exceeded", 3);
            const result = await session.matchExpr({ kind: "expr-match", pattern, profile: unicode ? "utf8-scalar" : "byte", limits: {
              maxPatternBytes: limits.maxRegexPatternBytes,
              maxSubjectBytes: Math.min(limits.maxStringBytes, exprMatchCeilings.maxSubjectBytes),
              maxNodes: limits.maxRegexNodes, maxDepth: limits.maxRegexDepth,
              maxSteps: Math.min(budget.remaining(), exprMatchCeilings.maxSteps),
              maxStates: limits.maxRegexStates, maxAllocatedUnits: limits.maxRegexAllocatedUnits,
            } }, subject);
            budget.charge(result.steps);
            if (result.hasCapture) {
              const start = result.capture?.start ?? 0, end = result.capture?.end ?? 0;
              budget.allocation(end - start);
              return new Uint8Array(subject.subarray(start, end));
            }
            return smallInteger(characterCount(subject.subarray(0, result.overall?.end ?? 0), budget, unicode), budget);
          }, context.args[0] === "--" ? 1 : 0);
          exitCode = truth(value, budget) ? 0 : 1;
          const result = bytes(value, budget);
          budget.check(result.length + 1, limits.maxOutputBytes, "output bytes");
          budget.charge(result.length + 1);
          output = new Uint8Array(result.length + 1);
          output.set(result);
          output[result.length] = 10;
        }
        await budget.yield();
      } catch (error) {
        context.signal.throwIfAborted();
        const message = error instanceof ExprError || error instanceof ExprMatchError || error instanceof RegexExecutionError ? error.message : "execution or output failure";
        try {
          budget.check(message.length + 7, limits.maxOutputBytes, "output bytes");
          budget.check(Buffer.byteLength(message) + 7, limits.maxOutputBytes, "output bytes");
        } catch {
          await writeBytes(context.stderr, new TextEncoder().encode("expr: output bytes limit exceeded\n"), context.signal);
          return { exitCode: 3 };
        }
        await writeBytes(context.stderr, new TextEncoder().encode(`expr: ${message}\n`), context.signal);
        return { exitCode: error instanceof ExprError ? error.exitCode : error instanceof ExprMatchError && error.category !== "limit" ? 2 : 3 };
      }
      await writeBytes(context.stdout, output, context.signal);
      return { exitCode };
    });
  } };
}

export function createExprCommands(options: ExprCommandsOptions = {}): readonly CommandDefinition[] {
  return [createExprCommand(options)];
}

export function exprCommands(options: ExprCommandsOptions = {}): VirtualShellPlugin {
  const commands = createExprCommands(options);
  return { name: "expr-commands", setup(host) {
    if (!options.replace && host.commands.has("expr")) throw new Error("Command already registered: expr");
    for (const command of commands) host.commands.register(command, { replace: options.replace ?? false });
  } };
}

import type { CommandContext } from "../../contracts/index.js";
import type { RegexExecutionOptions } from "../regex-execution/client.js";
import { exprMatchCeilings } from "../regex-execution/protocol.js";

export interface ExprLimits {
  readonly maxArgumentBytes: number;
  readonly maxNumericDigits: number;
  readonly maxNodes: number;
  readonly maxDepth: number;
  readonly maxSteps: number;
  readonly maxStringBytes: number;
  readonly maxOutputBytes: number;
  readonly maxRegexPatternBytes: number;
  readonly maxRegexNodes: number;
  readonly maxRegexDepth: number;
  readonly maxRegexStates: number;
  readonly maxRegexAllocatedUnits: number;
}

export interface ExprCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<ExprLimits>;
  readonly regex?: RegexExecutionOptions;
}

export class ExprError extends Error {
  constructor(message: string, readonly exitCode: 2 | 3 = 2) { super(message); }
}

export function settings(options: ExprCommandsOptions): ExprLimits {
  const limits = {
    maxArgumentBytes: 65_536, maxNumericDigits: 1024, maxNodes: 4096,
    maxDepth: 128, maxSteps: 8_000_000, maxStringBytes: 65_536,
    maxOutputBytes: 65_537, maxRegexPatternBytes: 8192, maxRegexNodes: 4096,
    maxRegexDepth: 64, maxRegexStates: 16_384, maxRegexAllocatedUnits: 1_000_000, ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid expr limit: ${name}`);
  }
  if (limits.maxDepth > 256) throw new RangeError("expr maxDepth must not exceed 256");
  for (const [key, maximum] of [
    ["maxRegexPatternBytes", exprMatchCeilings.maxPatternBytes], ["maxRegexNodes", exprMatchCeilings.maxNodes],
    ["maxRegexDepth", exprMatchCeilings.maxDepth], ["maxRegexStates", exprMatchCeilings.maxStates],
    ["maxRegexAllocatedUnits", exprMatchCeilings.maxAllocatedUnits],
  ] as const) if (limits[key] > maximum) throw new RangeError(`expr ${key} exceeds worker ceiling ${maximum}`);
  return Object.freeze(limits);
}

export class Budget {
  private steps = 0;
  private checkpoint = 0;
  constructor(readonly context: CommandContext, readonly limits: ExprLimits) {}
  remaining(): number { return this.limits.maxSteps - this.steps; }
  check(size: number, maximum: number, label: string): void {
    if (!Number.isSafeInteger(size) || size > maximum) throw new ExprError(`${label} limit exceeded`, 3);
  }
  charge(size = 1): void {
    this.context.signal.throwIfAborted();
    this.steps += size;
    this.check(this.steps, this.limits.maxSteps, "evaluation work");
  }
  async yield(): Promise<void> {
    this.charge();
    if (this.steps - this.checkpoint >= 4096) {
      this.checkpoint = this.steps;
      await new Promise<void>(resolve => setImmediate(resolve));
      this.context.signal.throwIfAborted();
    }
  }
  allocation(size: number): void {
    this.check(size, this.limits.maxStringBytes, "string allocation");
    this.charge(size);
  }
  arguments(): void {
    this.check(this.context.args.length, this.limits.maxNodes * 4, "argument count");
    let total = 0;
    for (const argument of this.context.args) {
      this.charge();
      this.check(argument.length, this.limits.maxArgumentBytes - total, "aggregate argument bytes");
      total += Buffer.byteLength(argument);
      this.check(total, this.limits.maxArgumentBytes, "aggregate argument bytes");
      this.charge(argument.length);
      if (argument.includes("\0")) throw new ExprError("NUL is not supported in argv");
      for (let offset = 0; offset < argument.length; offset++) {
        const unit = argument.charCodeAt(offset);
        if (unit >= 0xd800 && unit <= 0xdbff) {
          const next = argument.charCodeAt(++offset);
          if (!(next >= 0xdc00 && next <= 0xdfff)) throw new ExprError("argv must contain well-formed Unicode");
        } else if (unit >= 0xdc00 && unit <= 0xdfff) throw new ExprError("argv must contain well-formed Unicode");
      }
    }
  }
  encode(text: string): Uint8Array {
    this.allocation(Buffer.byteLength(text));
    return new TextEncoder().encode(text);
  }
}

function effectiveLocale(context: CommandContext, category: "LC_CTYPE" | "LC_COLLATE"): string {
  return context.env.LC_ALL || context.env[category] || context.env.LANG || "C";
}

function baselineLocale(locale: string): boolean {
  return locale === "C" || locale === "POSIX" || locale === "C.UTF-8" || locale === "C.utf8";
}

export function utf8Profile(context: CommandContext): boolean {
  const locale = effectiveLocale(context, "LC_CTYPE");
  if (locale === "C" || locale === "POSIX") return false;
  if (locale === "C.UTF-8" || locale === "C.utf8" || locale === "en_US.UTF-8") return true;
  throw new ExprError("character operations require C/POSIX, C.UTF-8/C.utf8, or qualified en_US.UTF-8 encoding");
}

export function requireByteCollation(context: CommandContext): void {
  if (!baselineLocale(effectiveLocale(context, "LC_COLLATE"))) {
    throw new ExprError("string comparison requires C/POSIX or C.UTF-8/C.utf8 byte collation");
  }
}

export function screenMatch(subject: Uint8Array, pattern: Uint8Array, budget: Budget): void {
  budget.context.signal.throwIfAborted();
  if (pattern.length > budget.limits.maxRegexPatternBytes
    || subject.length > Math.min(budget.limits.maxStringBytes, exprMatchCeilings.maxSubjectBytes)) {
    throw new ExprError("regex input bytes limit exceeded", 3);
  }
  if (baselineLocale(effectiveLocale(budget.context, "LC_CTYPE"))
    && baselineLocale(effectiveLocale(budget.context, "LC_COLLATE"))) return;
  budget.charge(pattern.length);
  for (let offset = 0; offset < pattern.length; offset++) {
    if (pattern[offset] === 92) offset++;
    else if (pattern[offset] === 91) {
      throw new ExprError("unsupported BRE: bracket expressions require C/POSIX or C.UTF-8/C.utf8 LC_CTYPE and LC_COLLATE");
    }
  }
}

export function nextCharacter(bytes: Uint8Array, offset: number, unicode: boolean): number {
  const first = bytes[offset]!;
  if (!unicode || first < 0xc2 || first > 0xf4) return offset + 1;
  const width = first < 0xe0 ? 2 : first < 0xf0 ? 3 : 4;
  if (offset + width > bytes.length) return offset + 1;
  for (let index = 1; index < width; index++) {
    const byte = bytes[offset + index]!;
    if (byte < 0x80 || byte > 0xbf) return offset + 1;
  }
  const second = bytes[offset + 1]!;
  if (first === 0xe0 && second < 0xa0 || first === 0xed && second >= 0xa0
    || first === 0xf0 && second < 0x90 || first === 0xf4 && second >= 0x90) return offset + 1;
  return offset + width;
}

import { Budget, ExprError } from "./internal.js";
import { evaluateBinary, evaluateCall, truth, zeroValue, type Matcher, type Value } from "./evaluate.js";

type Operand =
  | { readonly active: true; readonly value: Value; readonly depth: number }
  | { readonly active: false; readonly depth: number };

const precedences = new Map([
  ["|", 1], ["&", 2], ["<", 3], ["<=", 3], ["=", 3], ["==", 3], ["!=", 3], [">=", 3], [">", 3],
  ["+", 4], ["-", 4], ["*", 5], ["/", 5], ["%", 5], [":", 6],
]);
const arities = new Map([["length", 1], ["index", 2], ["substr", 3], ["match", 2]]);

export async function evaluateExpression(args: readonly string[], budget: Budget, match: Matcher, start = 0): Promise<Value> {
  let position = start;
  let nodes = 0;
  function fail(message: string): never {
    const size = Buffer.byteLength(message) + 7;
    budget.check(size, budget.limits.maxOutputBytes, "output bytes");
    budget.charge(size);
    throw new ExprError(message);
  }
  function quote(text: string): string {
    const input = budget.encode(text);
    const fragments = ["'"];
    let size = 2;
    budget.check(size, budget.limits.maxStringBytes, "string allocation");
    for (const byte of input) {
      const escaped = byte === 39 ? "\\'" : byte === 92 ? "\\\\"
        : byte === 7 ? "\\a" : byte === 8 ? "\\b" : byte === 9 ? "\\t"
          : byte === 10 ? "\\n" : byte === 11 ? "\\v" : byte === 12 ? "\\f" : byte === 13 ? "\\r"
            : byte < 32 || byte >= 127 ? `\\${byte.toString(8).padStart(3, "0")}` : String.fromCharCode(byte);
      size += escaped.length;
      budget.check(size, budget.limits.maxStringBytes, "string allocation");
      budget.charge(escaped.length);
      fragments.push(escaped);
    }
    fragments.push("'");
    return fragments.join("");
  }
  async function node(depth: number): Promise<void> {
    budget.charge();
    budget.check(++nodes, budget.limits.maxNodes, "AST node");
    budget.check(depth, budget.limits.maxDepth, "AST depth");
    await budget.yield();
  }
  async function literal(text: string, active: boolean): Promise<Operand> {
    await node(1);
    return active ? { active, value: budget.encode(text), depth: 1 } : { active, depth: 1 };
  }
  async function prefix(depth: number, active: boolean): Promise<Operand> {
    budget.check(depth, budget.limits.maxDepth, "parser depth");
    if (position === args.length) fail(`syntax error: missing argument after ${quote(args[position - 1]!)}`);
    const token = args[position++]!;
    if (token === ")") fail("syntax error: unexpected ')'");
    if (token === "(") {
      const result = await expression(1, depth + 1, active);
      if (position === args.length) fail(`syntax error: expecting ')' after ${quote(args[position - 1]!)}`);
      if (args[position] !== ")") fail(`syntax error: expecting ')' instead of ${quote(args[position]!)}`);
      position++;
      return result;
    }
    if (token === "+") {
      const text = args[position++];
      if (text === undefined) fail("syntax error: missing argument after '+'");
      return literal(text, active);
    }
    const arity = arities.get(token);
    if (arity !== undefined) {
      const values: Value[] = [];
      let operandDepth = 0;
      for (let index = 0; index < arity; index++) {
        const operand = await prefix(depth + 1, active);
        operandDepth = Math.max(operandDepth, operand.depth);
        if (operand.active) values.push(operand.value);
      }
      const resultDepth = 1 + operandDepth;
      await node(resultDepth);
      return active ? { active, value: await evaluateCall(token, values, budget, match), depth: resultDepth }
        : { active, depth: resultDepth };
    }
    return literal(token, active);
  }
  async function expression(minimum: number, depth: number, active: boolean): Promise<Operand> {
    let left = await prefix(depth, active);
    while (position < args.length) {
      const operator = args[position]!;
      const precedence = precedences.get(operator);
      if (precedence === undefined || precedence < minimum) break;
      position++;
      const logical = operator === "|" || operator === "&";
      const leftTruth = left.active && logical ? truth(left.value, budget) : false;
      const enabled = operator === "|" ? !leftTruth : operator === "&" ? leftTruth : true;
      const right = await expression(precedence + 1, depth + 1, active && enabled);
      const resultDepth = 1 + Math.max(left.depth, right.depth);
      await node(resultDepth);
      if (!left.active) left = { active: false, depth: resultDepth };
      else if (logical) {
        const value = operator === "|" ? leftTruth ? left.value : right.active && truth(right.value, budget) ? right.value : zeroValue
          : leftTruth && right.active && truth(right.value, budget) ? left.value : zeroValue;
        left = { active: true, value, depth: resultDepth };
      } else if (right.active) {
        left = { active: true, value: await evaluateBinary(operator, left.value, right.value, budget, match), depth: resultDepth };
      }
    }
    return left;
  }
  if (position === args.length) fail("missing operand\nTry 'expr --help' for more information.");
  const result = await expression(1, 1, true);
  if (position !== args.length) fail(`syntax error: unexpected argument ${quote(args[position]!)}`);
  if (!result.active) throw new ExprError("inactive expression", 3);
  return result.value;
}

export interface Classification {
  readonly description: string;
  readonly mime: string;
  readonly encoding: string;
}

export const binary: Classification = { description: "data", mime: "application/octet-stream", encoding: "binary" };

function result(description: string, mime: string, encoding = "binary"): Classification {
  return { description, mime, encoding };
}

function matches(bytes: Uint8Array, signature: readonly number[], offset = 0): boolean {
  return bytes.length >= offset + signature.length && signature.every((value, index) => bytes[offset + index] === value);
}

function ascii(bytes: Uint8Array, start: number, length: number): string {
  return String.fromCharCode(...bytes.subarray(start, start + length));
}

function magic(bytes: Uint8Array): Classification | undefined {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (bytes.length >= 33 && matches(bytes, [137, 80, 78, 71, 13, 10, 26, 10]) && view.getUint32(8) === 13 && ascii(bytes, 12, 4) === "IHDR"
    && view.getUint32(16) > 0 && view.getUint32(20) > 0 && bytes[26] === 0 && bytes[27] === 0 && bytes[28]! <= 1) {
    const allowed: Record<number, readonly number[]> = { 0: [1, 2, 4, 8, 16], 2: [8, 16], 3: [1, 2, 4, 8], 4: [8, 16], 6: [8, 16] };
    if (allowed[bytes[25]!]?.includes(bytes[24]!)) return result("PNG image data", "image/png");
  }
  if (bytes.length >= 13 && ["GIF87a", "GIF89a"].includes(ascii(bytes, 0, 6)) && view.getUint16(6, true) > 0 && view.getUint16(8, true) > 0) return result("GIF image data", "image/gif");
  if (bytes.length >= 4 && matches(bytes, [255, 216, 255]) && bytes[3]! >= 192 && bytes[3]! <= 254) return result("JPEG image data", "image/jpeg");
  if (bytes.length >= 20 && ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 4) === "WEBP" && ["VP8 ", "VP8L", "VP8X"].includes(ascii(bytes, 12, 4)) && view.getUint32(4, true) >= 12) return result("WebP image data", "image/webp");
  if (bytes.length >= 8 && (matches(bytes, [73, 73, 42, 0]) || matches(bytes, [77, 77, 0, 42]))) return result("TIFF image data", "image/tiff");
  if (bytes.length >= 26 && ascii(bytes, 0, 2) === "BM" && [12, 40, 52, 56, 108, 124].includes(view.getUint32(14, true))) return result("PC bitmap image data", "image/bmp");
  if (bytes.length >= 22 && matches(bytes, [0, 0, 1, 0]) && view.getUint16(4, true) > 0) return result("MS Windows icon resource", "image/vnd.microsoft.icon");
  if (/^%PDF-[12]\.[0-9](?:\r|\n|\s)/u.test(ascii(bytes, 0, 16))) return result("PDF document", "application/pdf");
  if (bytes.length >= 10 && matches(bytes, [31, 139, 8]) && (bytes[3]! & 224) === 0) return result("gzip compressed data", "application/gzip");
  if (bytes.length >= 10 && ascii(bytes, 0, 3) === "BZh" && bytes[3]! >= 49 && bytes[3]! <= 57 && (ascii(bytes, 4, 6) === "1AY&SY" || matches(bytes, [23, 114, 69, 56, 80, 144], 4))) return result("bzip2 compressed data", "application/x-bzip2");
  if (bytes.length >= 12 && matches(bytes, [253, 55, 122, 88, 90, 0]) && bytes[6] === 0 && bytes[7]! <= 15) return result("XZ compressed data", "application/x-xz");
  if (bytes.length >= 6 && matches(bytes, [40, 181, 47, 253]) && (bytes[4]! & 24) === 0) return result("Zstandard compressed data", "application/zstd");
  if ((bytes.length >= 30 && matches(bytes, [80, 75, 3, 4])) || (bytes.length >= 22 && matches(bytes, [80, 75, 5, 6]))) return result("Zip archive data", "application/zip");
  if (bytes.length >= 32 && matches(bytes, [55, 122, 188, 175, 39, 28])) return result("7-zip archive data", "application/x-7z-compressed");
  if ((bytes.length >= 14 && matches(bytes, [82, 97, 114, 33, 26, 7, 0])) || (bytes.length >= 16 && matches(bytes, [82, 97, 114, 33, 26, 7, 1, 0]))) return result("RAR archive data", "application/x-rar");
  if (bytes.length >= 512 && ascii(bytes, 257, 5) === "ustar") {
    const checksum = ascii(bytes, 148, 8).replace(/\0.*$/u, "").trim();
    if (/^[0-7]+$/u.test(checksum)) {
      let total = 0;
      for (let index = 0; index < 512; index++) total += index >= 148 && index < 156 ? 32 : bytes[index]!;
      if (parseInt(checksum, 8) === total) return result("POSIX tar archive", "application/x-tar");
    }
  }
  if (bytes.length >= 52 && matches(bytes, [127, 69, 76, 70]) && [1, 2].includes(bytes[4]!) && [1, 2].includes(bytes[5]!) && bytes[6] === 1 && (bytes[4] === 1 || bytes.length >= 64)) {
    const type = view.getUint16(16, bytes[5] === 1);
    const mime = type === 1 ? "application/x-object" : type === 2 ? "application/x-executable" : type === 3 ? "application/x-sharedlib" : "application/octet-stream";
    return result(`ELF ${bytes[4] === 1 ? "32" : "64"}-bit ${type === 2 ? "executable" : type === 3 ? "shared object" : "object"}`, mime);
  }
  if (bytes.length >= 64 && ascii(bytes, 0, 2) === "MZ") {
    const offset = view.getUint32(60, true);
    if (offset >= 64 && offset <= bytes.length - 24 && matches(bytes, [80, 69, 0, 0], offset)) return result("PE executable", "application/vnd.microsoft.portable-executable");
    return result("DOS executable", "application/x-dosexec");
  }
  if (bytes.length >= 8 && matches(bytes, [0, 97, 115, 109, 1, 0, 0, 0])) return result("WebAssembly binary module", "application/wasm");
  if (bytes.length >= 100 && ascii(bytes, 0, 16) === "SQLite format 3\0") {
    const size = view.getUint16(16);
    if ((size === 1 || (size >= 512 && size <= 32768 && (size & (size - 1)) === 0)) && [1, 2].includes(bytes[18]!) && [1, 2].includes(bytes[19]!) && matches(bytes, [64, 32, 32], 21)) return result("SQLite 3.x database", "application/vnd.sqlite3");
  }
  if (bytes.length >= 512 && matches(bytes, [208, 207, 17, 224, 161, 177, 26, 225]) && matches(bytes, [254, 255], 28)) return result("OLE Compound Document", "application/x-ole-storage");
  return undefined;
}

export function classify(bytes: Uint8Array, complete: boolean): Classification {
  if (!bytes.length) return complete ? result("empty", "inode/x-empty") : binary;
  const recognized = magic(bytes);
  if (recognized) return recognized;
  if (matches(bytes, [255, 254, 0, 0]) || matches(bytes, [0, 0, 254, 255])) return binary;
  let encoding = "utf-8";
  let bom = 0;
  if (matches(bytes, [239, 187, 191])) bom = 3;
  else if (matches(bytes, [255, 254])) { encoding = "utf-16le"; bom = 2; }
  else if (matches(bytes, [254, 255])) { encoding = "utf-16be"; bom = 2; }
  let text: string;
  try { text = new TextDecoder(encoding, { fatal: true }).decode(bytes, { stream: !complete }); }
  catch { return binary; }
  if (!text.length && bytes.length > bom) return binary;
  for (const character of text) {
    const code = character.codePointAt(0)!;
    if ((code < 32 && ![8, 9, 10, 12, 13, 27].includes(code)) || (code >= 127 && code <= 159)) return binary;
  }
  if (!bom && encoding === "utf-8" && bytes.every(value => value < 128)) encoding = "us-ascii";
  if (complete && /^[\x20\t\r\n]*(?:\{|\[)/u.test(text)) {
    try { JSON.parse(text); return result("JSON text data", "application/json", encoding); } catch {}
  }
  const description = encoding === "us-ascii" ? "ASCII text" : encoding === "utf-8" ? "Unicode text, UTF-8" : `Unicode text, ${encoding === "utf-16le" ? "UTF-16, little-endian" : "UTF-16, big-endian"}`;
  return result(description, "text/plain", encoding);
}

import { writeBytes, type ByteSink, type CommandContext } from "../../contracts/index.js";

export interface FileLimits {
  readonly maxSniffBytes: number;
  readonly maxReadFileBytes: number;
  readonly maxInputBytes: number;
  readonly maxOutputBytes: number;
  readonly maxChunkBytes: number;
  readonly maxEntries: number;
  readonly maxSteps: number;
  readonly maxArgumentBytes: number;
  readonly maxDurationMs: number;
}

export interface FileCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<FileLimits>;
}

export function settings(options: FileCommandsOptions): FileLimits {
  const limits: FileLimits = {
    maxSniffBytes: 65536, maxReadFileBytes: 1024 * 1024, maxInputBytes: 8 * 1024 * 1024,
    maxOutputBytes: 1024 * 1024, maxChunkBytes: 1024 * 1024, maxEntries: 1024,
    maxSteps: 1024 * 1024, maxArgumentBytes: 65536, maxDurationMs: 10000, ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1 || (name === "maxDurationMs" && value > 2147483647)) {
      throw new RangeError(`Invalid file limit: ${name}`);
    }
  }
  return limits;
}

export class FileFailure extends Error {}
export class FileLimitError extends FileFailure {}

export class SharedBudget {
  private inputBytes = 0;
  private outputBytes = 0;
  private steps = 0;
  private failureUnits = 64;
  private untilYield = 128;
  private readonly controller = new AbortController();
  private readonly timer: ReturnType<typeof setTimeout>;
  private readonly deadline: number;
  readonly signal: AbortSignal;

  constructor(readonly context: CommandContext, readonly limits: FileLimits) {
    this.signal = AbortSignal.any([context.signal, this.controller.signal]);
    this.deadline = performance.now() + limits.maxDurationMs;
    this.timer = setTimeout(() => this.controller.abort(new FileLimitError("time limit exceeded")), limits.maxDurationMs);
  }

  dispose(): void { clearTimeout(this.timer); }
  get remainingInputBytes(): number { return this.limits.maxInputBytes - this.inputBytes; }

  check(size: number, maximum: number, label: string): void {
    if (size > maximum) throw new FileLimitError(`${label} limit exceeded`);
  }

  checkTime(): void {
    if (performance.now() >= this.deadline && !this.signal.aborted) this.controller.abort(new FileLimitError("time limit exceeded"));
    this.signal.throwIfAborted();
  }

  work(count: number): void {
    this.checkTime();
    this.check(count, this.limits.maxSteps - this.steps, "step");
    this.steps += count;
  }

  async step(count = 1): Promise<void> {
    this.work(count);
    if (--this.untilYield <= 0) {
      this.untilYield = 128;
      await new Promise<void>(resolve => setImmediate(resolve));
      this.checkTime();
    }
  }

  input(size: number): void {
    this.check(size, this.limits.maxChunkBytes, "chunk");
    this.check(size, this.remainingInputBytes, "input");
    this.inputBytes += size;
  }

  async escapeName(value: string, metadata = false, render = true): Promise<string> {
    this.checkTime();
    if (metadata) this.check(value.length, this.remainingInputBytes, "input");
    if (render) this.check(value.length, this.limits.maxOutputBytes - this.outputBytes, "output");
    this.work(value.length);
    const pieces: string[] = [];
    let outputBytes = 0;
    let untilYield = 4096;
    for (const character of value) {
      if (metadata) {
        const size = Buffer.byteLength(character);
        this.check(size, this.remainingInputBytes, "input");
        this.inputBytes += size;
      }
      if (render) {
        const piece = character === "\\" ? "\\\\" : /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u.test(character)
          ? `\\u{${character.codePointAt(0)!.toString(16)}}` : character;
        outputBytes += Buffer.byteLength(piece);
        this.check(outputBytes, this.limits.maxOutputBytes - this.outputBytes, "output");
        pieces.push(piece);
      }
      untilYield -= character.length;
      if (untilYield <= 0) {
        untilYield = 4096;
        await new Promise<void>(resolve => setImmediate(resolve));
        this.checkTime();
      }
    }
    this.checkTime();
    return pieces.join("");
  }

  async output(sink: ByteSink, text: string, signal = this.signal): Promise<void> {
    this.checkTime();
    this.check(text.length, this.limits.maxOutputBytes - this.outputBytes, "output");
    this.work(text.length);
    const size = Buffer.byteLength(text);
    this.check(size, this.limits.maxOutputBytes - this.outputBytes, "output");
    this.outputBytes += size;
    const bytes = new TextEncoder().encode(text);
    const width = Math.min(16384, this.limits.maxChunkBytes);
    for (let offset = 0; offset < bytes.length; offset += width) {
      await writeBytes(sink, bytes.slice(offset, offset + width), signal);
    }
  }

  async failure(text: string): Promise<void> {
    this.checkTime();
    const units = Math.min(this.failureUnits, this.limits.maxOutputBytes - this.outputBytes, text.length);
    this.failureUnits -= units;
    let end = units;
    if (end > 0 && end < text.length && text.charCodeAt(end - 1) >= 0xd800 && text.charCodeAt(end - 1) <= 0xdbff
      && text.charCodeAt(end) >= 0xdc00 && text.charCodeAt(end) <= 0xdfff) end--;
    let bounded = "";
    let size = 0;
    for (const character of text.slice(0, end)) {
      const width = Buffer.byteLength(character);
      if (width > this.limits.maxOutputBytes - this.outputBytes - size) break;
      size += width;
      bounded += character;
    }
    this.outputBytes += size;
    const bytes = new TextEncoder().encode(bounded);
    const width = Math.min(16384, this.limits.maxChunkBytes);
    for (let offset = 0; offset < bytes.length; offset += width) {
      await writeBytes(this.context.stderr, bytes.slice(offset, offset + width), this.signal);
    }
  }

  async host<Result>(operation: () => Promise<Result>): Promise<Result> {
    this.checkTime();
    return new Promise<Result>((resolve, reject) => {
      const onAbort = (): void => { this.signal.removeEventListener("abort", onAbort); reject(this.signal.reason); };
      this.signal.addEventListener("abort", onAbort, { once: true });
      try {
        Promise.resolve(operation()).then(result => {
          this.signal.removeEventListener("abort", onAbort);
          try { this.checkTime(); resolve(result); } catch (error) { reject(error); }
        }, error => { this.signal.removeEventListener("abort", onAbort); reject(error); });
      } catch (error) {
        this.signal.removeEventListener("abort", onAbort);
        reject(error);
      }
    });
  }
}

export function limitMessage(error: FileLimitError): string {
  const message = error.message;
  return message.length <= 32 && ["argument", "entry", "readFile", "input", "chunk", "output", "step", "time"]
    .some(label => message === `${label} limit exceeded`) ? message : "resource limit exceeded";
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { grepCommands } from "../grep.js";
import type { RegexExecutionOptions } from "../regex-execution/protocol.js";

export interface GrepAliasOptions {
  readonly regex?: RegexExecutionOptions;
  readonly replace?: boolean;
}

function alias(name: "egrep" | "fgrep", grep: CommandDefinition): CommandDefinition {
  return {
    name,
    execute: context => {
      const stdinIsDefault = context.stdinIsDefault;
      const invoke = context.invoke;
      const registerCleanup = context.registerCleanup;
      return grep.execute({
        ...context,
        command: name,
        args: [name === "egrep" ? "-E" : "-F", ...context.args],
        stdin: context.stdin,
        stdout: context.stdout,
        stderr: context.stderr,
        cwd: context.cwd,
        env: context.env,
        fs: context.fs,
        signal: context.signal,
        ...(stdinIsDefault === undefined ? {} : { stdinIsDefault }),
        ...(invoke === undefined ? {} : { invoke: invoke.bind(context) }),
        ...(registerCleanup === undefined ? {} : { registerCleanup: registerCleanup.bind(context) }),
      });
    },
  };
}

export function createGrepAliasCommands(options: GrepAliasOptions = {}): readonly CommandDefinition[] {
  const grep = grepCommands(options.regex)[0]!;
  return [alias("egrep", grep), alias("fgrep", grep)];
}

export function egrepCommand(options: GrepAliasOptions = {}): CommandDefinition {
  return alias("egrep", grepCommands(options.regex)[0]!);
}

export function fgrepCommand(options: GrepAliasOptions = {}): CommandDefinition {
  return alias("fgrep", grepCommands(options.regex)[0]!);
}

export function grepAliasCommands(options: GrepAliasOptions = {}): VirtualShellPlugin {
  return {
    name: "grep-alias-commands",
    setup(host) {
      const definitions = createGrepAliasCommands(options);
      if (!options.replace) for (const definition of definitions) {
        if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
      }
      for (const definition of definitions) host.commands.register(definition, { replace: options.replace ?? false });
    },
  };
}

import type { CommandDefinition } from "../contracts/index.js";
import { bufferLimit, collect, diagnostic, input, integer, lines, options as parseOptions, output, UsageError, value } from "./internal.js";
import { AvailableRecords, RegexExecutor, RegexExecutionError, withRegexSession, type RegexExecutionOptions } from "./regex-execution/client.js";
import type { GrepDescriptor } from "./regex-execution/protocol.js";

export function grepCommands(options: RegexExecutionOptions = {}): CommandDefinition[] {
  const executor = new RegexExecutor(options);
  return [{ name: "grep", execute: context => withRegexSession(context, executor, async session => {
    try {
      const parsed = parseOptions(context.args, "EFivnclLqhHowxae:f:m:sz", { "extended-regexp": "E", "fixed-strings": "F", "ignore-case": "i", "invert-match": "v", "line-number": "n", count: "c", "files-with-matches": "l", "files-without-match": "L", quiet: "q", silent: "q", "no-filename": "h", "with-filename": "H", "only-matching": "o", "word-regexp": "w", "line-regexp": "x", regexp: "e", file: "f", "max-count": "m", "no-messages": "s", text: "a", "null-data": "z" });
      const patterns: string[] = [];
      const addPatterns = (text: string, file: boolean) => {
        if (file && text === "") return;
        const parts = text.split("\n");
        if (parts.length > 1 && parts.at(-1) === "") parts.pop();
        patterns.push(...parts);
      };
      for (const pattern of parsed.values.get("e") ?? []) addPatterns(Buffer.from(pattern).toString("latin1"), false);
      for (const name of parsed.values.get("f") ?? []) addPatterns(Buffer.from(await collect(input(context, name), context.signal)).toString("latin1"), true);
      if (!parsed.flags.has("e") && !parsed.flags.has("f")) {
        if (!parsed.operands.length) throw new UsageError("missing pattern");
        addPatterns(Buffer.from(parsed.operands.shift()!).toString("latin1"), false);
      }
      if (parsed.flags.has("E") && parsed.flags.has("F")) throw new UsageError("conflicting matchers specified");
      const descriptor: GrepDescriptor = {
        kind: "grep", patterns, fixed: parsed.flags.has("F"), extended: parsed.flags.has("E"),
        insensitive: parsed.flags.has("i"), whole: parsed.flags.has("x"), word: parsed.flags.has("w"),
      };
      await session.run(descriptor, []);
      const names = parsed.operands.length ? parsed.operands : ["-"];
      const maxCount = value(parsed, "m") === undefined ? Infinity : integer(value(parsed, "m")!);
      const batchSize = Number.isFinite(maxCount) || parsed.flags.has("q") || parsed.flags.has("l") || parsed.flags.has("L") ? 1 : 128;
      const delimiter = parsed.flags.has("z") ? "\0" : "\n";
      let anySelected = false;
      let failed = false;
      for (const name of names) {
        let count = 0;
        let number = 0;
        const named = name === "-" ? "(standard input)" : name;
        const prefix = (lineNumber = false) => `${!parsed.flags.has("h") && (parsed.flags.has("H") || names.length > 1) ? `${named}:` : ""}${lineNumber && parsed.flags.has("n") ? `${number}:` : ""}`;
        try {
          const available = new AvailableRecords(parsed.flags.has("z") ? 0 : 10, bufferLimit);
          records: if (maxCount > 0) for await (const batch of available.batches(lines(available.source(input(context, name)), parsed.flags.has("z") ? 0 : 10), line => line.bytes.length, () => batchSize)) {
            const results = await session.run(descriptor, batch.map(line => ({ bytes: line.bytes, all: parsed.flags.has("o"), terminated: line.terminated })));
            for (let index = 0; index < batch.length; index++) {
              const line = batch[index]!;
              context.signal.throwIfAborted();
              number++;
              const found = results[index]!;
              if ((found.length > 0) === parsed.flags.has("v")) continue;
              count++;
              if (!parsed.flags.has("L")) anySelected = true;
              if (parsed.flags.has("q")) return { exitCode: 0 };
              if (parsed.flags.has("l") || parsed.flags.has("L")) break records;
              if (!parsed.flags.has("c")) {
                if (parsed.flags.has("o")) {
                  if (!parsed.flags.has("v")) {
                    let end = -1;
                    for (const match of found) {
                      if (match.start === match.end || match.start < end) continue;
                      await output(context, prefix(true));
                      await output(context, line.bytes.subarray(match.start, match.end));
                      await output(context, delimiter);
                      end = match.end;
                    }
                  }
                } else {
                  await output(context, prefix(true)); await output(context, line.bytes); await output(context, delimiter);
                }
              }
              if (count >= maxCount) break records;
            }
          }
          if (parsed.flags.has("l") && count > 0 || parsed.flags.has("L") && count === 0) {
            await output(context, named + delimiter); anySelected = true;
          } else if (parsed.flags.has("c") && !parsed.flags.has("l") && !parsed.flags.has("L")) await output(context, prefix() + count + delimiter);
        } catch (error) {
          context.signal.throwIfAborted();
          if (error instanceof RegexExecutionError) throw error;
          failed = true;
          if (!parsed.flags.has("s")) await diagnostic(context, error);
        }
      }
      return { exitCode: failed ? 2 : anySelected ? 0 : 1 };
    } catch (error) {
      context.signal.throwIfAborted();
      await diagnostic(context, error);
      return { exitCode: 2 };
    }
  }) }];
}

import { setImmediate as pause } from "node:timers/promises";
import { FsError, writeBytes, type CommandContext } from "../../contracts/index.js";
import type { HtmlToMarkdownLimits } from "./options.js";

export class Budget {
  input = 0;
  output = 0;
  tokens = 0;
  nodes = 0;
  cells = 0;
  private workUsed = 0;
  private sinceYield = 0;
  constructor(readonly context: CommandContext, readonly limits: HtmlToMarkdownLimits) {}

  check(amount: number, remaining: number, name: string): void {
    this.context.signal.throwIfAborted();
    if (!Number.isSafeInteger(amount) || amount < 0 || amount > remaining) {
      throw new FsError("EFBIG", { message: `html-to-markdown ${name} limit exceeded` });
    }
  }

  work(amount: number): void {
    this.check(amount, this.limits.maxWorkUnits - this.workUsed, "work");
    this.workUsed += amount;
    this.sinceYield += amount;
  }

  async checkpoint(): Promise<void> {
    this.context.signal.throwIfAborted();
    if (this.sinceYield >= 4096) {
      this.sinceYield = 0;
      try { await pause(undefined, { signal: this.context.signal }); }
      catch (error) { this.context.signal.throwIfAborted(); throw error; }
    }
    this.context.signal.throwIfAborted();
  }

  add(kind: "input" | "tokens" | "nodes" | "cells", amount = 1): void {
    const maximum = kind === "input" ? this.limits.maxInputBytes : kind === "tokens" ? this.limits.maxTokens
      : kind === "nodes" ? this.limits.maxNodes : this.limits.maxTableCells;
    this.check(amount, maximum - this[kind], kind);
    this[kind] += amount;
  }

  async emit(text: string): Promise<void> {
    this.check(text.length, this.limits.maxOutputBytes - this.output, "output");
    const bytes = Buffer.byteLength(text);
    this.check(bytes, this.limits.maxOutputBytes - this.output, "output");
    this.output += bytes;
    for (let offset = 0; offset < text.length;) {
      let end = Math.min(text.length, offset + 4096);
      if (end < text.length && /[\uD800-\uDBFF]/u.test(text[end - 1]!)) end--;
      this.work(end - offset);
      await writeBytes(this.context.stdout, Buffer.from(text.slice(offset, end)), this.context.signal);
      offset = end;
      await this.checkpoint();
    }
  }
}

export class Builder {
  private readonly pieces: string[] = [];
  private bytes = 0;
  private tail = "";
  constructor(readonly budget: Budget, readonly maximum = budget.limits.maxOutputBytes - budget.output) {}
  append(text: string): void {
    if (!text) return;
    this.budget.check(text.length, this.maximum - this.bytes, "rendered bytes");
    const size = Buffer.byteLength(text);
    this.budget.check(size, this.maximum - this.bytes, "rendered bytes");
    this.budget.work(text.length);
    this.bytes += size;
    this.pieces.push(text);
    this.tail = (this.tail + text.slice(-2)).slice(-2);
  }
  get empty(): boolean { return this.bytes === 0; }
  get trailingSpace(): boolean { return this.tail.endsWith(" "); }
  get blockBoundary(): boolean { return this.empty || this.tail.endsWith("\n"); }
  separate(): void {
    if (!this.empty) this.append(this.tail.endsWith("\n\n") ? "" : this.tail.endsWith("\n") ? "\n" : "\n\n");
  }
  finish(): string { this.budget.work(this.bytes); return this.pieces.join(""); }
}

import { Builder, type Budget } from "./budget.js";
import { htmlSpace } from "./text.js";

const named: Readonly<Record<string, string>> = Object.freeze({
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: "\u00a0",
  copy: "©", reg: "®", trade: "™", hellip: "…", ndash: "–", mdash: "—",
  lsquo: "‘", rsquo: "’", ldquo: "“", rdquo: "”", bull: "•", middot: "·",
  euro: "€", pound: "£", yen: "¥", cent: "¢", times: "×", divide: "÷",
  colon: ":", Tab: "\t", NewLine: "\n",
});

export async function entities(text: string, budget: Budget): Promise<string> {
  const result = new Builder(budget);
  for (let offset = 0; offset < text.length;) {
    budget.work(1);
    const candidateSize = text[offset] === "&" ? Math.min(34, text.length - offset) : 0;
    budget.work(candidateSize);
    const candidate = text.slice(offset, offset + candidateSize);
    const match = candidate && /^&(#(?:[xX][0-9a-fA-F]{1,8}|[0-9]{1,10})|[A-Za-z][A-Za-z0-9]{0,31});/u.exec(candidate);
    if (match) {
      const name = match[1]!;
      if (name[0] !== "#") result.append(Object.hasOwn(named, name) ? named[name]! : match[0]);
      else {
        const hexadecimal = name[1]?.toLowerCase() === "x";
        const value = Number.parseInt(name.slice(hexadecimal ? 2 : 1), hexadecimal ? 16 : 10);
        result.append(value === 0 || value > 0x10ffff || value >= 0xd800 && value <= 0xdfff ? "�" : String.fromCodePoint(value));
      }
      offset += match[0].length;
    } else {
      const character = String.fromCodePoint(text.codePointAt(offset)!);
      result.append(character); offset += character.length;
    }
    await budget.checkpoint();
  }
  return result.finish();
}

export async function escapeText(text: string, budget: Budget, maximum?: number, edges: readonly [boolean, boolean] = [false, false], precedingDigit = false): Promise<string> {
  const result = new Builder(budget, maximum);
  let offset = 0;
  for (const character of text) {
    budget.work(1);
    const scalar = character.codePointAt(0)!;
    if (scalar < 32 && character !== "\n" && character !== "\t" && character !== "\r" || scalar >= 0x7f && scalar <= 0x9f) result.append("�");
    else if ((edges[0] && offset === 0 || edges[1] && offset + character.length === text.length) && !htmlSpace(character)) result.append(`&#${scalar};`);
    else result.append("\\`*_{}[]<>!|#+-&~=".includes(character) || ".)".includes(character) && (offset === 0 ? precedingDigit : /[0-9]/u.test(text[offset - 1]!)) ? "\\" + character : character);
    offset += character.length;
    await budget.checkpoint();
  }
  return result.finish();
}

export async function destination(value: string | undefined, image: boolean, budget: Budget): Promise<string | undefined> {
  if (value === undefined) return undefined;
  let first = 0, last = value.length, reference: "none" | "start" | "numeric" | "named" = "none";
  for (let offset = 0; offset < value.length; offset++) {
    budget.work(1);
    const code = value.charCodeAt(offset), character = value[offset]!;
    if (code < 32 || code >= 0x7f && code <= 0x9f || character === "\\") return undefined;
    if (character === "%" && /^(?:0[0-9a-f]|1[0-9a-f]|7f)$/iu.test(value.slice(offset + 1, offset + 3))) return undefined;
    if (character === ";" && (reference === "numeric" || reference === "named")) return undefined;
    if (reference === "numeric") {
      if (/\s/u.test(character)) reference = "none";
    } else if (reference === "start" && character === "#") reference = "numeric";
    else if (reference === "start" && /[A-Za-z]/u.test(character)) reference = "named";
    else if (reference === "named" && /[A-Za-z0-9]/u.test(character)) {}
    else reference = character === "&" ? "start" : "none";
    await budget.checkpoint();
  }
  while (first < last && value[first] === " ") { budget.work(1); first++; await budget.checkpoint(); }
  while (last > first && value[last - 1] === " ") { budget.work(1); last--; await budget.checkpoint(); }
  budget.work(last - first);
  const text = value.slice(first, last);
  if (!text || text.startsWith("//")) return undefined;
  let boundary = 0;
  while (boundary < text.length && !"/?#".includes(text[boundary]!)) { budget.work(1); boundary++; await budget.checkpoint(); }
  budget.work(boundary);
  const prefix = text.slice(0, boundary);
  if (prefix.includes(":")) {
    const scheme = prefix.slice(0, prefix.indexOf(":")).toLowerCase();
    if (scheme !== "http" && scheme !== "https" && (image || scheme !== "mailto")) return undefined;
    if (scheme !== "mailto") {
      budget.work(text.length);
      try { const parsed = new URL(text); if (!parsed.hostname || !/^https?:\/\//iu.test(text)) return undefined; }
      catch { return undefined; }
    }
  }
  const result = new Builder(budget);
  for (const character of text) {
    budget.work(1);
    result.append(/[ <>"'`()\[\]{}|]/u.test(character) ? encodeURIComponent(character).replaceAll("'", "%27").replaceAll("(", "%28").replaceAll(")", "%29") : character);
    await budget.checkpoint();
  }
  return result.finish();
}

import { createOutputOperation, writeBytes, type CommandDefinition, type OutputOperation, type VirtualShellPlugin } from "../../contracts/index.js";
import { Budget } from "./budget.js";
import { Inputs } from "./input.js";
import { argumentsFor, HtmlUsageError, settings, type HtmlToMarkdownCommandsOptions } from "./options.js";
import { Renderer } from "./render.js";

export type { HtmlToMarkdownCommandsOptions, HtmlToMarkdownLimits } from "./options.js";

export function createHtmlToMarkdownCommand(options: HtmlToMarkdownCommandsOptions = {}): CommandDefinition {
  const limits = settings(options);
  return { name: "html-to-markdown", description: "Convert bounded VFS/stdin HTML to Markdown without fetching or executing", async execute(context) {
    context.signal.throwIfAborted();
    let operation: OutputOperation | undefined;
    let inputs: Inputs | undefined, failed = false;
    try {
      const parsed = argumentsFor(context.args, limits);
      operation = createOutputOperation(context, context.stdout);
      const work = { ...context, signal: operation.signal, stdout: operation.output, registerCleanup: operation.registerCleanup };
      const budget = new Budget(work, limits);
      if (parsed.info !== undefined) { await budget.emit(parsed.info); return { exitCode: 0 }; }
      inputs = new Inputs(work, budget);
      const renderer = new Renderer(budget);
      let written = false;
      for (const name of parsed.files) {
        const markdown = await renderer.document(await inputs.document(name));
        if (!markdown) continue;
        if (written) await budget.emit("\n");
        await budget.emit(markdown); written = true;
      }
      return { exitCode: 0 };
    } catch (error) {
      failed = true;
      inputs?.preservePrimaryFailure();
      context.signal.throwIfAborted();
      if (operation?.signal.aborted && error === operation.signal.reason) throw error;
      const message = error instanceof Error ? error.message : String(error);
      const text = `html-to-markdown: ${message.slice(0, limits.maxDiagnosticBytes)}\n`;
      let bytes = Buffer.from(text);
      if (bytes.length > limits.maxDiagnosticBytes) {
        let end = limits.maxDiagnosticBytes;
        while (end > 0 && (bytes[end]! & 0xc0) === 0x80) end--;
        bytes = bytes.subarray(0, end);
      }
      await writeBytes(context.stderr, bytes, context.signal);
      return { exitCode: error instanceof HtmlUsageError ? 2 : 1 };
    } finally {
      try {
        try { await inputs?.close(); }
        catch (error) { context.signal.throwIfAborted(); if (!failed) throw error; }
      } finally {
        try { await operation?.close(); }
        catch (error) { context.signal.throwIfAborted(); if (!failed) throw error; }
      }
      context.signal.throwIfAborted();
    }
  } };
}

export function createHtmlToMarkdownCommands(options: HtmlToMarkdownCommandsOptions = {}): readonly CommandDefinition[] {
  return [createHtmlToMarkdownCommand(options)];
}

export function htmlToMarkdownCommands(options: HtmlToMarkdownCommandsOptions = {}): VirtualShellPlugin {
  const commands = createHtmlToMarkdownCommands(options), replace = options.replace ?? false;
  return { name: "html-to-markdown-commands", setup(host) {
    if (!replace) for (const command of commands) if (host.commands.has(command.name)) throw new Error(`Command already registered: ${command.name}`);
    for (const command of commands) host.commands.register(command, { replace });
  } };
}

import { readBytes, type ByteSource, type CommandContext } from "../../contracts/index.js";
import { pathOf } from "../internal.js";
import type { Budget } from "./budget.js";
import { Parser, type HtmlNode } from "./parser.js";

class Cursor implements ByteSource {
  private iterator: AsyncIterator<Uint8Array> | undefined;
  private done = false;
  private closing: Promise<void> | undefined;
  constructor(readonly source: ByteSource, readonly signal: AbortSignal) {}
  [Symbol.asyncIterator](): AsyncIterator<Uint8Array> {
    return {
      next: async () => {
        if (this.done) return { done: true, value: undefined };
        this.signal.throwIfAborted();
        this.iterator ??= this.source[Symbol.asyncIterator]();
        const next = await this.iterator.next();
        this.signal.throwIfAborted();
        if (this.done || next.done) { this.done = true; return { done: true, value: undefined }; }
        return next;
      },
      return: async () => { await this.close(); return { done: true, value: undefined }; },
    };
  }
  close(): Promise<void> {
    if (!this.closing) {
      const iterator = this.done ? undefined : this.iterator;
      this.done = true;
      this.closing = Promise.resolve().then(async () => { await iterator?.return?.(); });
    }
    return this.closing;
  }
}

export class Inputs {
  private readonly cursors: Cursor[] = [];
  private stdin: Cursor | undefined;
  private closed = false;
  private primaryFailure = false;
  private completion: Promise<void> | undefined;
  constructor(readonly context: CommandContext, readonly budget: Budget) {
    context.registerCleanup?.(this.close);
  }

  preservePrimaryFailure(): void { this.primaryFailure = true; }

  private open(name: string): Cursor {
    this.context.signal.throwIfAborted();
    if (this.closed) throw new Error("html-to-markdown input is closed");
    if (name === "-" && this.stdin) return this.stdin;
    let source: ByteSource;
    if (name === "-") source = this.context.stdin;
    else {
      const context = this.context, budget = this.budget, path = pathOf(context, name);
      if (context.fs.readStream) source = context.fs.readStream(path, { signal: context.signal, chunkSize: 16_384 });
      else {
        let consumed = false;
        source = { [Symbol.asyncIterator]() { return {
          async next() {
            if (consumed) return { done: true, value: undefined };
            consumed = true;
            const value = await context.fs.readFile(path, { signal: context.signal, maxBytes: budget.limits.maxInputBytes - budget.input });
            context.signal.throwIfAborted();
            return { done: false, value };
          },
          async return() { consumed = true; return { done: true, value: undefined }; },
        }; } };
      }
    }
    const cursor = new Cursor(source, this.context.signal);
    this.cursors.push(cursor);
    if (name === "-") this.stdin = cursor;
    return cursor;
  }

  async document(name: string): Promise<HtmlNode> {
    const cursor = this.open(name), decoder = new TextDecoder("utf-8", { fatal: true });
    const parser = new Parser(this.budget);
    for await (const chunk of readBytes(cursor, this.context.signal)) {
      this.budget.add("input", chunk.byteLength);
      this.budget.work(Math.max(1, chunk.byteLength));
      const owned = new Uint8Array(chunk);
      for (let offset = 0; offset < owned.length; offset += 4096) {
        await parser.feed(decoder.decode(owned.subarray(offset, offset + 4096), { stream: true }));
        await this.budget.checkpoint();
      }
      await this.budget.checkpoint();
    }
    await parser.feed(decoder.decode());
    this.context.signal.throwIfAborted();
    return parser.finish();
  }

  readonly close = (): Promise<void> => {
    this.closed = true;
    this.completion ??= Promise.allSettled(this.cursors.map(cursor => cursor.close())).then(results => {
      const failure = results.find(result => result.status === "rejected");
      if (failure?.status === "rejected" && !this.primaryFailure) throw failure.reason;
    });
    return this.completion;
  };
}

export interface HtmlToMarkdownLimits {
  readonly maxInputBytes: number;
  readonly maxOutputBytes: number;
  readonly maxTokenBytes: number;
  readonly maxTokens: number;
  readonly maxNodes: number;
  readonly maxDepth: number;
  readonly maxAttributes: number;
  readonly maxTableCells: number;
  readonly maxTableCellBytes: number;
  readonly maxFiles: number;
  readonly maxArgumentBytes: number;
  readonly maxDiagnosticBytes: number;
  readonly maxWorkUnits: number;
}

export interface HtmlToMarkdownCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<HtmlToMarkdownLimits>;
}

export class HtmlUsageError extends Error {}

export function settings(options: HtmlToMarkdownCommandsOptions): HtmlToMarkdownLimits {
  const result: HtmlToMarkdownLimits = {
    maxInputBytes: 8 * 1024 * 1024, maxOutputBytes: 16 * 1024 * 1024,
    maxTokenBytes: 65_536, maxTokens: 200_000, maxNodes: 100_000, maxDepth: 128,
    maxAttributes: 64, maxTableCells: 10_000, maxTableCellBytes: 65_536,
    maxFiles: 64, maxArgumentBytes: 65_536, maxDiagnosticBytes: 8192,
    maxWorkUnits: 64 * 1024 * 1024, ...options.limits,
  };
  for (const [name, value] of Object.entries(result)) {
    if (!Number.isSafeInteger(value) || value < 1 || value > 64 * 1024 * 1024) {
      throw new RangeError(`Invalid html-to-markdown limit: ${name}`);
    }
  }
  if (result.maxDepth > 256 || result.maxTokenBytes > 1024 * 1024 || result.maxAttributes > 1024) {
    throw new RangeError("html-to-markdown depth/token/attribute ceiling exceeded");
  }
  return Object.freeze(result);
}

export function argumentsFor(args: readonly string[], limits: HtmlToMarkdownLimits): { files: readonly string[]; info?: string } {
  let bytes = 0, literal = false;
  const files: string[] = [];
  if (args.length > limits.maxArgumentBytes) throw new HtmlUsageError("argument count limit exceeded");
  for (const argument of args) {
    if (argument.length > limits.maxArgumentBytes - bytes) throw new HtmlUsageError("argument limit exceeded");
    bytes += Buffer.byteLength(argument);
    if (bytes > limits.maxArgumentBytes || argument.includes("\0")) throw new HtmlUsageError("invalid or oversized argument");
    if (!literal && argument === "--") { literal = true; continue; }
    if (!literal && argument === "--help") return { files: [], info: helpText };
    if (!literal && argument === "--version") return { files: [], info: "html-to-markdown (safe-bash bounded HTML profile)\n" };
    if (!literal && argument.startsWith("-") && argument !== "-") throw new HtmlUsageError(`unknown option: ${argument}`);
    if (!argument) throw new HtmlUsageError("empty file operand");
    if (files.length >= limits.maxFiles) throw new HtmlUsageError("file limit exceeded");
    files.push(argument);
  }
  return { files: files.length ? files : ["-"] };
}

export const helpText = `Usage: html-to-markdown [--] [FILE|-] ...
Read VFS files or shared stdin; write bounded Markdown to stdout.
Supports headings, paragraphs, emphasis, links/images, lists, quotes, code and tables.
Drops scripts/styles/comments; unknown elements retain text. No fetching or execution.
This documented HTML subset is a converter, not a sanitizer or browser HTML5 parser.
`;

import { Builder, type Budget } from "./budget.js";

export const htmlSpace = (character: string | undefined): boolean => character === " " || character === "\t" || character === "\r" || character === "\n" || character === "\f";

export async function trimText(text: string, budget: Budget): Promise<string> {
  let start = 0, end = text.length;
  while (start < end && htmlSpace(text[start])) {
    budget.work(1);
    if (++start % 4096 === 0) await budget.checkpoint();
  }
  while (end > start && htmlSpace(text[end - 1])) {
    budget.work(1);
    if (--end % 4096 === 0) await budget.checkpoint();
  }
  budget.work(2);
  if (start === 0 && end === text.length) return text;
  budget.work(end - start);
  return text.slice(start, end);
}

export async function normalizeText(text: string, budget: Budget, mode: "space" | "lines" | "inline", maximum?: number): Promise<string> {
  const result = new Builder(budget, maximum);
  let previousSpace = false;
  for (let offset = 0; offset < text.length;) {
    const character = String.fromCodePoint(text.codePointAt(offset)!);
    budget.work(character.length);
    offset += character.length;
    if (mode === "space" && htmlSpace(character)) {
      if (!previousSpace) result.append(" ");
      previousSpace = true;
    } else {
      previousSpace = false;
      if (mode === "lines" && character === "\r") {
        if (text[offset] === "\n") { budget.work(1); offset++; }
        result.append("\n");
      } else result.append(mode === "inline" && character === "\n" ? " " : character);
    }
    if (offset % 4096 <= 1) await budget.checkpoint();
  }
  await budget.checkpoint();
  return result.finish();
}

import { type CommandDefinition, type CommandHandler, type VirtualShellPlugin } from "../contracts/index.js";
import { basicCommands } from "./basic.js";
import { filesystemCommands } from "./filesystem.js";
import { streamCommands } from "./streams.js";
import { textCommands } from "./text.js";
import { grepCommands } from "./grep.js";
import { predicateCommands } from "./predicates.js";
import { directExecutor, executionCommands } from "./execution.js";
import { findCommands } from "./find.js";
import { diagnostic } from "./internal.js";
import type { RegexExecutionOptions } from "./regex-execution/protocol.js";

export interface StandardCommandsOptions {
  readonly execute?: CommandHandler;
  readonly replace?: boolean;
  readonly regex?: RegexExecutionOptions;
}

export function createStandardCommands(options: StandardCommandsOptions = {}): readonly CommandDefinition[] {
  const commands: CommandDefinition[] = [];
  const execute = directExecutor(options.execute ?? (async context => {
    const command = commands.find(definition => definition.name === context.command);
    if (command) return command.execute(context);
    await diagnostic(context, new Error("command not found"));
    return { exitCode: 127 };
  }));
  commands.push(...basicCommands(), ...filesystemCommands(), ...streamCommands(), ...textCommands(), ...grepCommands(options.regex), ...predicateCommands(), ...executionCommands(execute), ...findCommands(execute));
  return commands;
}

export function standardCommands(options: StandardCommandsOptions = {}): VirtualShellPlugin {
  return {
    name: "standard-commands",
    setup(host) {
      const commands = createStandardCommands({ ...options, execute: options.execute ?? (async context => {
        const command = host.commands.get(context.command);
        if (command) return command.execute(context);
        await diagnostic(context, new Error("command not found"));
        return { exitCode: 127 };
      }) });
      if (!options.replace) {
        for (const command of commands) {
          if (host.commands.has(command.name)) throw new Error(`Command already registered: ${command.name}`);
        }
      }
      for (const command of commands) host.commands.register(command, { replace: options.replace ?? false });
    },
  };
}

import { FsError, type FileStat } from "../../contracts/index.js";
import { codeOf, diagnostic, options, pathOf, requireOperands, UsageError, value } from "../internal.js";
import { MetadataBudget, metadataCommand, permissionString, settings, type MetadataCommandsOptions } from "./internal.js";

type ModeChange = (stat: FileStat) => number;

function modeChange(text: string, umask: number): ModeChange {
  const numeric = /^([+=-]?)([0-7]+)$/u.exec(text);
  if (numeric) {
    const bits = Number.parseInt(numeric[2]!, 8);
    if (bits > 0o7777) throw new UsageError(`invalid mode: '${text}'`);
    return stat => {
      const current = stat.mode & 0o7777;
      if (numeric[1] === "+") return current | bits;
      if (numeric[1] === "-") return current & ~bits;
      return bits | (stat.type === "directory" && !numeric[1] && numeric[2]!.length < 5 ? current & 0o6000 : 0);
    };
  }
  const clauses = text.split(",").map(clause => {
    const match = /^([ugoa]*)((?:[+=-](?:[rwxXst]*|[ugo]))+)$/u.exec(clause);
    if (!match) throw new UsageError(`invalid mode: '${text}'`);
    const who = match[1]!;
    const operations = [...match[2]!.matchAll(/([+=-])([^+=-]*)/gu)].map(operation => ({ operator: operation[1]!, permissions: operation[2]! }));
    return { who, operations };
  });
  return stat => {
    let current = stat.mode & 0o7777;
    for (const { who, operations } of clauses) {
      const all = !who || who.includes("a");
      const users = (all || who.includes("u") ? 0o4700 : 0) | (all || who.includes("g") ? 0o2070 : 0) | (all || who.includes("o") ? 0o1007 : 0);
      for (const { operator, permissions } of operations) {
        let bits = 0;
        if (/^[ugo]$/u.test(permissions)) {
          const shift = permissions === "u" ? 6 : permissions === "g" ? 3 : 0;
          const copied = current >> shift & 7;
          bits = copied << 6 | copied << 3 | copied;
        } else {
          if (permissions.includes("r")) bits |= 0o444;
          if (permissions.includes("w")) bits |= 0o222;
          if (permissions.includes("x") || permissions.includes("X") && (stat.type === "directory" || (current & 0o111) !== 0)) bits |= 0o111;
          if (permissions.includes("s")) bits |= 0o6000;
          if (permissions.includes("t")) bits |= 0o1000;
        }
        bits &= users;
        if (!who) bits &= ~umask;
        if (operator === "+") current |= bits;
        else if (operator === "-") current &= ~bits;
        else {
          const preserve = stat.type === "directory" && !permissions.includes("s") ? 0o6000 : 0;
          current = current & ~(users & ~preserve) | bits;
        }
      }
    }
    return current;
  };
}

export function createChmodCommand(configuration: MetadataCommandsOptions = {}) {
  const configured = settings(configuration);
  return metadataCommand("chmod", async context => {
    const budget = new MetadataBudget(context, configured.limits);
    const parsed = options(context.args, "Rvcfr:", { recursive: "R", verbose: "v", changes: "c", silent: "f", quiet: "f", reference: "r" });
    const reference = value(parsed, "r");
    requireOperands(parsed.operands, reference === undefined ? 2 : 1);
    const change = reference === undefined ? modeChange(parsed.operands[0]!, configured.umask) : undefined;
    const paths = reference === undefined ? parsed.operands.slice(1) : parsed.operands;
    if (context.fs.capabilities.readOnly) throw new FsError("EROFS", { syscall: "chmod" });
    if (!context.fs.chmod || context.fs.capabilities.permissions === false) throw new FsError("ENOTSUP", { syscall: "chmod" });
    const referenceMode = reference === undefined ? undefined : (await context.fs.stat(pathOf(context, reference), { signal: context.signal })).mode & 0o7777;
    let exitCode = 0;
    const visit = async (path: string, display: string, depth: number, top: boolean): Promise<void> => {
      await budget.step(depth);
      const link = await context.fs.lstat(path, { signal: context.signal });
      if (link.type === "symlink" && !top) return;
      const target = link.type === "symlink" ? await context.fs.realpath(path, { signal: context.signal }) : path;
      const stat = link.type === "symlink" ? await context.fs.stat(target, { signal: context.signal }) : link;
      const mode = referenceMode ?? change!(stat);
      if (parsed.flags.has("R") && stat.type === "directory" && await context.fs.realpath(target, { signal: context.signal }) === "/") throw new FsError("EBUSY", { syscall: "chmod", path, message: "refusing recursive mode changes at virtual root" });
      const apply = async () => {
        context.signal.throwIfAborted();
        const fresh = await context.fs.lstat(target, { signal: context.signal });
        if (fresh.type === "symlink" || fresh.type !== stat.type || stat.ino !== undefined && fresh.ino !== stat.ino || stat.dev !== undefined && fresh.dev !== stat.dev) throw new FsError("EIO", { syscall: "chmod", path, message: "path changed during permission update" });
        await context.fs.chmod!(target, mode, { signal: context.signal });
        if (parsed.flags.has("v") || parsed.flags.has("c") && mode !== (stat.mode & 0o7777)) {
          await budget.output(`mode of '${display}' ${mode === (stat.mode & 0o7777) ? "retained as" : "changed from " + (stat.mode & 0o7777).toString(8).padStart(4, "0") + " (" + permissionString(stat.mode, stat.type).slice(1) + ") to"} ${mode.toString(8).padStart(4, "0")} (${permissionString(mode, stat.type).slice(1)})\n`);
        }
      };
      const deferred = stat.type === "directory" && parsed.flags.has("R") && (stat.mode & 0o777 & ~mode) !== 0;
      if (!deferred) await apply();
      if (stat.type === "directory" && parsed.flags.has("R")) {
        const entries = await context.fs.readdir(target, { signal: context.signal });
        if (entries.length > configured.limits.maxEntries) throw new FsError("EFBIG", { message: "metadata traversal limit exceeded" });
        for (const entry of entries) {
          if (!entry.name || entry.name === "." || entry.name === ".." || entry.name.includes("/") || entry.name.includes("\0")) throw new FsError("EIO", { message: "invalid directory entry" });
          try { await visit(`${target.replace(/\/$/u, "")}/${entry.name}`, `${display.replace(/\/$/u, "")}/${entry.name}`, depth + 1, false); }
          catch (error) { context.signal.throwIfAborted(); if (codeOf(error) === "EFBIG") throw error; exitCode = 1; if (!parsed.flags.has("f")) await diagnostic(context, error); }
        }
      }
      if (deferred) await apply();
    };
    for (const operand of paths) {
      try { await visit(pathOf(context, operand), operand, 0, true); }
      catch (error) { context.signal.throwIfAborted(); if (codeOf(error) === "EFBIG") throw error; exitCode = 1; if (!parsed.flags.has("f")) await diagnostic(context, error); }
    }
    return { exitCode };
  });
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createChmodCommand } from "./chmod.js";
import { createStatCommand } from "./stat.js";
import { createMktempCommand } from "./mktemp.js";
import { settings, type MetadataCommandsOptions } from "./internal.js";
export type { MetadataCommandsOptions, MetadataLimits } from "./internal.js";

export function createMetadataCommands(options: MetadataCommandsOptions = {}): readonly CommandDefinition[] {
  settings(options);
  return [createChmodCommand(options), createStatCommand(options), createMktempCommand(options)];
}

export function metadataCommands(options: MetadataCommandsOptions = {}): VirtualShellPlugin {
  const commands = createMetadataCommands(options);
  return { name: "metadata-commands", setup(host) {
    if (!options.replace) for (const command of commands) if (host.commands.has(command.name)) throw new Error(`Command already registered: ${command.name}`);
    for (const command of commands) host.commands.register(command, { replace: options.replace ?? false });
  } };
}

import { FsError, writeBytes, type CommandContext, type CommandDefinition, type CommandHandler } from "../../contracts/index.js";
import { diagnostic } from "../internal.js";

export interface MetadataLimits {
  readonly maxEntries: number;
  readonly maxDepth: number;
  readonly maxOutputBytes: number;
  readonly maxArgumentBytes: number;
  readonly maxAttempts: number;
}

export interface MetadataCommandsOptions {
  readonly replace?: boolean;
  readonly umask?: number;
  readonly limits?: Partial<MetadataLimits>;
}

export function settings(options: MetadataCommandsOptions = {}) {
  const limits: MetadataLimits = { maxEntries: 100_000, maxDepth: 128, maxOutputBytes: 1024 * 1024, maxArgumentBytes: 64 * 1024, maxAttempts: 128, ...options.limits };
  for (const [key, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < (key === "maxDepth" ? 0 : 1)) throw new RangeError(`Invalid metadata limit: ${key}`);
  }
  const umask = options.umask ?? 0o022;
  if (!Number.isInteger(umask) || umask < 0 || umask > 0o777) throw new RangeError("Invalid metadata umask");
  return { limits, umask };
}

export class MetadataBudget {
  private entries = 0;
  private outputBytes = 0;
  constructor(readonly context: CommandContext, readonly limits: MetadataLimits) {
    if (context.args.reduce((size, argument) => size + Buffer.byteLength(argument), 0) > limits.maxArgumentBytes) throw new FsError("EFBIG", { message: "metadata argument limit exceeded" });
  }
  async step(depth = 0): Promise<void> {
    this.context.signal.throwIfAborted();
    if (++this.entries > this.limits.maxEntries || depth > this.limits.maxDepth) throw new FsError("EFBIG", { message: "metadata traversal limit exceeded" });
    if (this.entries % 128 === 0) await new Promise<void>(resolve => setImmediate(resolve));
    this.context.signal.throwIfAborted();
  }
  async output(text: string | Uint8Array): Promise<void> {
    const bytes = typeof text === "string" ? new TextEncoder().encode(text) : text;
    if (bytes.byteLength > this.limits.maxOutputBytes - this.outputBytes) throw new FsError("EFBIG", { message: "metadata output limit exceeded" });
    this.outputBytes += bytes.byteLength;
    await writeBytes(this.context.stdout, bytes, this.context.signal);
  }
}

export function metadataCommand(name: string, handler: CommandHandler): CommandDefinition {
  return { name, async execute(context) {
    context.signal.throwIfAborted();
    try { return await handler(context); }
    catch (error) { context.signal.throwIfAborted(); await diagnostic(context, error); return { exitCode: 1 }; }
  } };
}

export function permissionString(mode: number, type: "file" | "directory" | "symlink"): string {
  let text = type === "directory" ? "d" : type === "symlink" ? "l" : "-";
  for (const [read, write, execute, special, lower, upper] of [
    [0o400, 0o200, 0o100, 0o4000, "s", "S"],
    [0o040, 0o020, 0o010, 0o2000, "s", "S"],
    [0o004, 0o002, 0o001, 0o1000, "t", "T"],
  ] as const) {
    text += mode & read ? "r" : "-";
    text += mode & write ? "w" : "-";
    text += mode & special ? (mode & execute ? lower : upper) : mode & execute ? "x" : "-";
  }
  return text;
}

import { randomInt } from "node:crypto";
import { FsError, validatePath } from "../../contracts/index.js";
import { codeOf, diagnostic, pathOf, UsageError } from "../internal.js";
import { MetadataBudget, metadataCommand, settings, type MetadataCommandsOptions } from "./internal.js";

function parse(args: readonly string[]) {
  let directory = false;
  let dryRun = false;
  let quiet = false;
  let useTmpdir = false;
  let tmpdir: string | undefined;
  let suffix: string | undefined;
  let literal = false;
  const operands: string[] = [];
  for (let index = 0; index < args.length; index++) {
    const argument = args[index]!;
    if (literal || argument === "-" || !argument.startsWith("-")) operands.push(argument);
    else if (argument === "--") literal = true;
    else if (argument === "--directory") directory = true;
    else if (argument === "--dry-run") dryRun = true;
    else if (argument === "--quiet") quiet = true;
    else if (argument === "--tmpdir" || argument.startsWith("--tmpdir=")) {
      useTmpdir = true;
      tmpdir = argument.includes("=") ? argument.slice(argument.indexOf("=") + 1) : "";
    } else if (argument === "--suffix" || argument.startsWith("--suffix=")) {
      suffix = argument.includes("=") ? argument.slice(argument.indexOf("=") + 1) : args[++index];
      if (suffix === undefined) throw new UsageError("--suffix requires an argument");
    } else if (!argument.startsWith("--")) {
      for (let offset = 1; offset < argument.length; offset++) {
        const option = argument[offset];
        if (option === "d") directory = true;
        else if (option === "u") dryRun = true;
        else if (option === "q") quiet = true;
        else if (option === "p") {
          tmpdir = argument.slice(offset + 1) || args[++index];
          if (tmpdir === undefined) throw new UsageError("-p requires an argument");
          useTmpdir = true;
          break;
        } else throw new UsageError(`unrecognized option '${argument}'`);
      }
    } else throw new UsageError(`unrecognized option '${argument}'`);
  }
  if (operands.length > 1) throw new UsageError("too many templates");
  const template = operands[0] ?? "tmp.XXXXXXXXXX";
  if (operands.length === 0) useTmpdir = true;
  validatePath(template);
  validatePath(suffix ?? "");
  if (suffix?.includes("/") || suffix !== undefined && !template.endsWith("X")) throw new UsageError("suffix requires a template ending in X and cannot contain '/'");
  const name = template.slice(template.lastIndexOf("/") + 1);
  const match = /^(.*?)(X{3,})([^X]*)$/u.exec(name);
  if (!match) throw new UsageError("template must contain at least three consecutive X characters in its last component");
  if (useTmpdir && template.startsWith("/")) throw new UsageError("template must be relative with --tmpdir/-p");
  const tail = suffix ?? match[3]!;
  if (Buffer.byteLength(name + (suffix ?? "")) > 255) throw new FsError("ENAMETOOLONG", { path: template });
  return { directory, dryRun, quiet, useTmpdir, tmpdir, template, prefix: template.slice(0, template.length - name.length) + match[1]!, count: match[2]!.length, tail };
}

export function createMktempCommand(configuration: MetadataCommandsOptions = {}) {
  const configured = settings(configuration);
  return metadataCommand("mktemp", async context => {
    const budget = new MetadataBudget(context, configured.limits);
    const parsed = parse(context.args);
    const parent = parsed.tmpdir || context.env.TMPDIR || "/tmp";
    validatePath(parent);
    const alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    try {
      if (!parsed.dryRun) {
        if (context.fs.capabilities.readOnly) throw new FsError("EROFS", { syscall: "mktemp" });
        if (context.fs.capabilities.permissions !== true) throw new FsError("ENOTSUP", { syscall: "mktemp", message: "private temporary creation requires declared permission support" });
      }
      for (let attempt = 0; attempt < configured.limits.maxAttempts; attempt++) {
        await budget.step();
        let random = "";
        for (let index = 0; index < parsed.count; index++) random += alphabet[randomInt(alphabet.length)];
        const generated = `${parsed.prefix}${random}${parsed.tail}`;
        const display = parsed.useTmpdir ? `${parent.replace(/\/+$/u, "")}/${generated}` : generated;
        const path = pathOf(context, display);
        if (Buffer.byteLength(display) + 1 > configured.limits.maxOutputBytes) throw new FsError("EFBIG", { message: "temporary pathname output exceeds limit" });
        if (parsed.dryRun) {
          try { await context.fs.lstat(path, { signal: context.signal }); continue; }
          catch (error) {
            context.signal.throwIfAborted();
            if (codeOf(error) !== "ENOENT") throw error;
          }
        } else {
          try {
            const mode = (parsed.directory ? 0o700 : 0o600) & ~configured.umask;
            if (parsed.directory) await context.fs.mkdir(path, { mode, recursive: false, signal: context.signal });
            else await context.fs.writeFile(path, new Uint8Array(), { mode, flag: "wx", signal: context.signal });
          } catch (error) {
            context.signal.throwIfAborted();
            if (codeOf(error) !== "EEXIST") throw error;
            continue;
          }
        }
        await budget.output(`${display}\n`);
        return { exitCode: 0 };
      }
      throw new FsError("EEXIST", { syscall: "mktemp", message: "temporary name collision limit exceeded" });
    } catch (error) {
      context.signal.throwIfAborted();
      if (!parsed.quiet) await diagnostic(context, error);
      return { exitCode: 1 };
    }
  });
}

import { dirname, FsError, isPathWithin, joinPath, type CommandContext, type FileStat } from "../contracts/index.js";
import { compareCopyIdentity, compareObservedEntries } from "./copy-identity.js";
import { codeOf, diagnostic } from "./internal.js";

interface MoveEntry {
  readonly source: string;
  readonly target: string;
  readonly stat: FileStat;
  readonly targetStat: FileStat | undefined;
  readonly link: string | undefined;
}

export class MoveBudget {
  private steps = 0;
  constructor(readonly signal: AbortSignal) {}
  get remaining(): number { return 100_000 - this.steps; }
  async step(): Promise<void> {
    this.signal.throwIfAborted();
    if (++this.steps > 100_000) throw new FsError("EFBIG", { message: "cross-device move entry limit exceeded" });
    if (this.steps % 128 === 0) await new Promise<void>(resolve => setImmediate(resolve));
    this.signal.throwIfAborted();
  }
}

async function optionalStat(context: CommandContext, path: string): Promise<FileStat | undefined> {
  try { return await context.fs.lstat(path, { signal: context.signal }); }
  catch (error) { context.signal.throwIfAborted(); if (codeOf(error) === "ENOENT") return undefined; throw error; }
}

function unchanged(before: FileStat, after: FileStat, content: boolean): boolean {
  const identity = compareCopyIdentity(before, after);
  const stableIdentity = compareCopyIdentity(before, before) === "same" ? identity === "same" : identity !== "distinct";
  return stableIdentity && before.type === after.type
    && (!content || (before.size === after.size && before.mtimeMs === after.mtimeMs && before.mode === after.mode));
}

async function recheck(context: CommandContext, entry: MoveEntry, content = true): Promise<void> {
  context.signal.throwIfAborted();
  const current = await context.fs.lstat(entry.source, { signal: context.signal });
  if (!unchanged(entry.stat, current, content)) throw new FsError("EBUSY", { path: entry.source, message: "move source changed before removal" });
}

export async function moveAcrossDevices(context: CommandContext, source: string, target: string, noClobber: boolean, budget: MoveBudget): Promise<boolean> {
  const plan: MoveEntry[] = [];
  const sourceStat = await context.fs.lstat(source, { signal: context.signal });
  const targetStat = await optionalStat(context, target);
  if (noClobber && targetStat) return false;
  if (source === target || compareCopyIdentity(sourceStat, targetStat) === "same") return false;
  const compare = (origin: string, destination: string, stat: FileStat, existing: FileStat) =>
    stat.type === "symlink" || existing.type === "symlink" ? Promise.resolve(compareCopyIdentity(stat, existing))
      : compareObservedEntries(context.fs, origin, stat, context.fs, destination, existing, { signal: context.signal });
  const rootIdentity = targetStat ? await compare(source, target, sourceStat, targetStat) : "unknown";
  if (rootIdentity === "same") return false;
  if (source === "/") throw new FsError("EBUSY", { path: source });
  if (sourceStat.type === "directory") {
    if (!context.fs.rmdir) throw new FsError("ENOTSUP", { syscall: "rmdir", path: source });
    if (isPathWithin(source, target)) throw new FsError("EINVAL", { path: target, message: "cannot move a directory into itself" });
    let parent = dirname(target);
    while (true) {
      await budget.step();
      const parentStat = await optionalStat(context, parent);
      if (compareCopyIdentity(sourceStat, parentStat) === "same") throw new FsError("EINVAL", { path: target, message: "cannot move a directory into itself" });
      if (parent === "/") break;
      parent = dirname(parent);
    }
  }
  const visit = async (origin: string, destination: string, stat: FileStat, existing: FileStat | undefined, depth: number): Promise<void> => {
    await budget.step();
    if (depth > 128) throw new FsError("EFBIG", { message: "cross-device move depth limit exceeded" });
    if (existing) {
      const identity = depth === 0 ? rootIdentity : await compare(origin, destination, stat, existing);
      if (identity === "same") throw new FsError("EINVAL", { path: origin, dest: destination, message: "move source and destination are aliases" });
      if (identity === "unknown") throw new FsError("ENOTSUP", { path: origin, dest: destination, message: "existing move destination lacks authoritative distinctness" });
      if ((stat.type === "directory") !== (existing.type === "directory")) throw new FsError(existing.type === "directory" ? "EISDIR" : "ENOTDIR", { path: destination });
      if (stat.type === "directory" && (await context.fs.readdir(destination, { signal: context.signal })).length) throw new FsError("ENOTEMPTY", { path: destination });
    }
    let link: string | undefined;
    if (stat.type === "symlink") {
      if (!context.fs.readlink || !context.fs.symlink) throw new FsError("ENOTSUP", { syscall: "symlink", path: origin });
      link = await context.fs.readlink(origin, { signal: context.signal });
    }
    plan.push({ source: origin, target: destination, stat, targetStat: existing, link });
    if (stat.type === "directory") {
      const entries = await context.fs.readdir(origin, { signal: context.signal });
      if (entries.length > budget.remaining) throw new FsError("EFBIG", { message: "cross-device move entry limit exceeded" });
      for (const entry of entries.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0)) {
        const child = joinPath(origin, entry.name), childTarget = joinPath(destination, entry.name);
        await visit(child, childTarget, await context.fs.lstat(child, { signal: context.signal }), await optionalStat(context, childTarget), depth + 1);
      }
    }
  };
  await visit(source, target, sourceStat, targetStat, 0);
  for (const entry of plan) {
    await recheck(context, entry);
    try {
      if (entry.stat.type === "directory") {
        if (!entry.targetStat) await context.fs.mkdir(entry.target, { mode: 0o700, signal: context.signal });
      } else if (entry.stat.type === "symlink") {
        if (entry.targetStat) await context.fs.rm(entry.target, { recursive: false, signal: context.signal });
        await context.fs.symlink!(entry.link!, entry.target, { signal: context.signal });
      } else {
        if (entry.targetStat?.type === "symlink") await context.fs.rm(entry.target, { recursive: false, signal: context.signal });
        await context.fs.copyFile(entry.source, entry.target, { exclusive: !entry.targetStat || entry.targetStat.type === "symlink", signal: context.signal });
      }
    } catch (error) {
      context.signal.throwIfAborted();
      if (noClobber && entry === plan[0] && !entry.targetStat && codeOf(error) === "EEXIST") return false;
      throw error;
    }
  }
  for (const entry of [...plan].reverse()) {
    context.signal.throwIfAborted();
    if (entry.stat.type !== "symlink") {
      if (context.fs.capabilities.permissions === true && context.fs.chmod) await context.fs.chmod(entry.target, entry.stat.mode & 0o7777, { signal: context.signal });
      if (context.fs.capabilities.timestamps === true && context.fs.utimes) {
        try { await context.fs.utimes(entry.target, entry.stat.atimeMs, entry.stat.mtimeMs, { signal: context.signal }); }
        catch (error) {
          context.signal.throwIfAborted();
          if (codeOf(error) !== "ENOTSUP" && codeOf(error) !== "EOPNOTSUPP") throw error;
          await diagnostic(context, new Error(`cannot preserve timestamps for '${entry.target}': operation not supported; retaining copied data`));
        }
      }
    }
  }
  for (const entry of plan) await recheck(context, entry);
  for (const entry of [...plan].reverse()) {
    await recheck(context, entry, entry.stat.type !== "directory");
    if (entry.stat.type === "directory") await context.fs.rmdir!(entry.source, { signal: context.signal });
    else await context.fs.rm(entry.source, { recursive: false, signal: context.signal });
  }
  return true;
}

import { randomBytes } from "node:crypto";
import { posix } from "node:path";
import { setImmediate } from "node:timers/promises";
import { collectBytes, readBytes, type ByteSource, type CommandContext } from "../../contracts/index.js";
import { pathOf } from "../internal.js";
import type { CurlArguments, DataArgument } from "./args.js";
import { encode } from "./shared.js";
import { CurlError, type NetworkLimits } from "./types.js";

interface Part {
  readonly bytes?: Uint8Array;
  readonly file?: string;
  readonly strip?: boolean;
  readonly urlencode?: boolean;
}

export interface RequestBody {
  readonly contentType?: string;
  open(signal: AbortSignal): ByteSource;
}

function percent(bytes: Uint8Array): Uint8Array {
  let output = "";
  for (const byte of bytes) output += (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122) ||
    (byte >= 48 && byte <= 57) || [45, 46, 95, 126].includes(byte)
    ? String.fromCharCode(byte) : byte === 32 ? "+" : `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
  return encode(output);
}

function dataPart(argument: DataArgument): Part[] {
  const value = argument.value;
  if (argument.kind === "urlencode") {
    const equals = value.indexOf("=");
    if (equals >= 0) return [{ bytes: encode(equals ? `${value.slice(0, equals)}=` : "") }, { bytes: encode(value.slice(equals + 1)), urlencode: true }];
    const at = value.indexOf("@");
    if (at >= 0) return [{ bytes: encode(at ? `${value.slice(0, at)}=` : "") }, { file: value.slice(at + 1), urlencode: true }];
    return [{ bytes: encode(value), urlencode: true }];
  }
  if (argument.kind !== "raw" && value.startsWith("@")) return [{ file: value.slice(1), strip: argument.kind === "data" }];
  return [{ bytes: encode(value) }];
}

function quoted(value: string): string {
  if (/[\r\n\0]/.test(value)) throw new CurlError(2, "Invalid multipart field metadata");
  return value.replace(/["\\]/g, "\\$&");
}

function multipart(argument: DataArgument, boundary: string): Part[] {
  const equals = argument.value.indexOf("=");
  if (equals < 1) throw new CurlError(2, "Multipart form requires name=value");
  const name = quoted(argument.value.slice(0, equals));
  let value = argument.value.slice(equals + 1);
  let type: string | undefined;
  let filename: string | undefined;
  if (argument.kind === "form") {
    const fields = value.split(";");
    value = fields.shift()!;
    for (const field of fields) {
      if (field.startsWith("type=")) type = field.slice(5);
      else if (field.startsWith("filename=")) filename = field.slice(9);
      else throw new CurlError(2, "Unsupported multipart form attribute");
    }
  }
  const isFile = argument.kind === "form" && /^[<@]/.test(value);
  if (isFile && (value.slice(1).includes(",") || !value.slice(1))) throw new CurlError(2, "Unsupported multipart file list");
  if (isFile && value.startsWith("@")) filename ??= posix.basename(value.slice(1));
  if (type !== undefined && !/^[\w!#$&^_.+-]+\/[\w!#$&^_.+-]+$/.test(type)) throw new CurlError(2, "Invalid multipart content type");
  let preamble = `--${boundary}\r\nContent-Disposition: form-data; name="${name}"`;
  if (filename !== undefined) preamble += `; filename="${quoted(filename)}"`;
  preamble += "\r\n";
  if (type || filename !== undefined) preamble += `Content-Type: ${type ?? "application/octet-stream"}\r\n`;
  preamble += "\r\n";
  return [{ bytes: encode(preamble) }, isFile ? { file: value.slice(1) } : { bytes: encode(value) }, { bytes: encode("\r\n") }];
}

export function createBody(context: CommandContext, args: CurlArguments, limits: NetworkLimits): RequestBody | undefined {
  if (!args.data.length && args.upload === undefined) return undefined;
  const parts: Part[] = [];
  let contentType: string | undefined;
  const form = args.data.some(part => part.kind.startsWith("form"));
  if (form) {
    const boundary = `virtual-bash-${randomBytes(18).toString("hex")}`;
    contentType = `multipart/form-data; boundary=${boundary}`;
    for (const argument of args.data) parts.push(...multipart(argument, boundary));
    parts.push({ bytes: encode(`--${boundary}--\r\n`) });
  } else if (args.upload !== undefined) parts.push({ file: args.upload });
  else {
    const json = args.data[0]?.kind === "json";
    contentType = json ? "application/json" : "application/x-www-form-urlencoded";
    args.data.forEach((argument, index) => {
      if (index && !json) parts.push({ bytes: encode("&") });
      parts.push(...dataPart(argument));
    });
  }
  const hasStdin = parts.some(part => part.file === "-");
  let opened = false;
  let replayComplete = false;
  let replayable = true;
  let cachedBytes = 0;
  let cache: Uint8Array[] = [];
  let stdinUsed = false;
  const source = async function* (part: Part, signal: AbortSignal): ByteSource {
    if (part.bytes !== undefined) { yield part.bytes; return; }
    if (part.file === "-") {
      if (!stdinUsed) { stdinUsed = true; yield* readBytes(context.stdin, signal); }
      return;
    }
    try {
      const path = pathOf(context, part.file!);
      if (context.fs.readStream) yield* readBytes(context.fs.readStream(path, { signal }), signal);
      else yield await context.fs.readFile(path, { signal, maxBytes: Math.min(limits.maxBufferBytes, limits.maxUploadBytes) });
    } catch (error) {
      signal.throwIfAborted();
      if (error instanceof CurlError) throw error;
      throw new CurlError(26, "Failed to read virtual upload file");
    }
  };
  return {
    ...(contentType === undefined ? {} : { contentType }),
    open(signal) {
      return (async function* (): ByteSource {
        if (hasStdin && opened) {
          if (!replayComplete || !replayable) throw new CurlError(65, "Cannot replay stdin upload within the host buffer limit");
          for (const chunk of cache) { signal.throwIfAborted(); yield chunk.slice(); }
          return;
        }
        opened = true;
        let count = 0;
        let chunks = 0;
        for (const part of parts) for await (const raw of source(part, signal)) {
          if (++chunks % 256 === 0) await setImmediate(undefined, { signal });
          for (let offset = 0; offset < raw.length; offset += 16 * 1024) {
            signal.throwIfAborted();
            let chunk = raw.subarray(offset, offset + 16 * 1024);
            if (part.strip) chunk = chunk.filter(byte => byte !== 0 && byte !== 10 && byte !== 13);
            if (part.urlencode) chunk = percent(chunk);
            count += chunk.length;
            if (count > limits.maxUploadBytes) throw new CurlError(63, "Upload exceeds host byte limit");
            if (hasStdin && replayable) {
              cachedBytes += chunk.length;
              if (cachedBytes > limits.maxBufferBytes) { replayable = false; cache = []; }
              else cache.push(new Uint8Array(chunk));
            }
            if (chunk.length) yield chunk;
          }
        }
        replayComplete = true;
      })();
    },
  };
}

export async function queryData(body: RequestBody, signal: AbortSignal, limits: NetworkLimits): Promise<string> {
  try { return Buffer.from(await collectBytes(body.open(signal), { signal, maxBytes: limits.maxBufferBytes })).toString("utf8"); }
  catch (error) {
    signal.throwIfAborted();
    if (error instanceof CurlError) throw error;
    throw new CurlError(63, "Query data exceeds host buffer limit");
  }
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createCurlCommand } from "./curl.js";
import type { NetworkCommandsOptions } from "./types.js";

export * from "./types.js";
export { createNodeHttpTransport, type NodeHttpTransportOptions } from "./transport.js";
export { createCurlCommand } from "./curl.js";

export function createNetworkCommands(options: NetworkCommandsOptions): readonly CommandDefinition[] {
  return [createCurlCommand(options)];
}

export function networkCommands(options: NetworkCommandsOptions): VirtualShellPlugin {
  const definitions = createNetworkCommands(options);
  return {
    name: "network-commands",
    setup(host) {
      if (!options.replace && host.commands.has("curl")) throw new Error("Command already registered: curl");
      for (const definition of definitions) host.commands.register(definition, { replace: options.replace ?? false });
    },
  };
}

export const createCurlCommands = createNetworkCommands;
export const curlCommands = networkCommands;

import { readBytes, writeBytes, type ByteSource, type CommandContext } from "../../contracts/index.js";
import { pathOf } from "../internal.js";
import { encode, withSignal } from "./shared.js";
import { CurlError, type HttpResponse } from "./types.js";

export function responseHeaders(response: HttpResponse, maxBytes: number): Uint8Array {
  if (!Number.isInteger(response.status) || response.status < 100 || response.status > 599 || /[\r\n]/.test(response.statusText)) {
    throw new CurlError(56, "Invalid HTTP response status");
  }
  const version = response.httpVersion ?? "1.1";
  if (!/^\d(?:\.\d)?$/.test(version)) throw new CurlError(56, "Invalid HTTP response version");
  let text = `HTTP/${version} ${response.status} ${response.statusText}\r\n`;
  for (const [name, value] of response.headers) {
    if (!/^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/.test(name) || /[\r\n\0]/.test(value)) throw new CurlError(56, "Invalid HTTP response header");
    text += `${name}: ${value}\r\n`;
    if (Buffer.byteLength(text, "latin1") > maxBytes) throw new CurlError(63, "Response headers exceed host byte limit");
  }
  return new Uint8Array(Buffer.from(`${text}\r\n`, "latin1"));
}

export async function writeOutput(context: CommandContext, path: string | undefined, source: ByteSource, signal: AbortSignal): Promise<void> {
  if (path === undefined || path === "-") {
    for await (const chunk of readBytes(source, signal)) {
      try { await writeBytes(context.stdout, chunk, signal); }
      catch (error) { signal.throwIfAborted(); throw new CurlError(23, "Failed writing output"); }
    }
    return;
  }
  try {
    const target = pathOf(context, path);
    if (context.fs.writeStream) await withSignal(() => context.fs.writeStream!(target, source, { signal, flag: "w" }), signal);
    else {
      await withSignal(() => context.fs.writeFile(target, new Uint8Array(), { signal, flag: "w" }), signal);
      for await (const chunk of readBytes(source, signal)) await withSignal(() => context.fs.appendFile(target, chunk, { signal }), signal);
    }
  } catch (error) {
    signal.throwIfAborted();
    if (error instanceof CurlError) throw error;
    throw new CurlError(23, "Failed writing virtual output file");
  }
}

export async function dumpHeaders(context: CommandContext, path: string, bytes: Uint8Array, append: boolean, signal: AbortSignal): Promise<void> {
  try {
    if (path === "-") await writeBytes(context.stdout, bytes, signal);
    else if (append) await withSignal(() => context.fs.appendFile(pathOf(context, path), bytes, { signal }), signal);
    else await withSignal(() => context.fs.writeFile(pathOf(context, path), bytes, { signal, flag: "w" }), signal);
  } catch {
    signal.throwIfAborted();
    throw new CurlError(23, "Failed writing response headers");
  }
}

export function writeOutFormat(format: string, values: Readonly<Record<string, string>>): Uint8Array {
  let result = "";
  for (let index = 0; index < format.length; index++) {
    const character = format[index]!;
    if (character === "\\") {
      const next = format[++index];
      result += next === "n" ? "\n" : next === "r" ? "\r" : next === "t" ? "\t" : next === undefined ? "\\" : `\\${next}`;
    } else if (character === "%" && format[index + 1] === "%") { result += "%"; index++; }
    else if (character === "%" && format[index + 1] === "{") {
      const end = format.indexOf("}", index + 2);
      if (end < 0) throw new CurlError(2, "Invalid write-out format");
      const name = format.slice(index + 2, end);
      if (!Object.hasOwn(values, name)) throw new CurlError(2, "Unsupported write-out variable");
      result += values[name]; index = end;
    } else result += character;
  }
  return encode(result);
}

import type { CommandContext } from "../../contracts/index.js";
import { writeBytes } from "../../contracts/index.js";
import { CurlError, defaultNetworkLimits, type HttpHeaders, type NetworkLimits } from "./types.js";

export const encode = (text: string): Uint8Array => new TextEncoder().encode(text);

export function limitsFor(overrides: Partial<NetworkLimits> = {}): NetworkLimits {
  const result = { ...defaultNetworkLimits, ...overrides };
  for (const [name, value] of Object.entries(result)) {
    const minimum = name === "maxRedirects" || name === "maxRetries" ? 0 : 1;
    if (!Number.isSafeInteger(value) || value < minimum || (name === "maxTimeMs" && value > 2_147_483_647)) {
      throw new RangeError(`Invalid network limit: ${name}`);
    }
  }
  return Object.freeze(result);
}

export async function withSignal<Value>(operation: () => PromiseLike<Value> | Value, signal: AbortSignal): Promise<Value> {
  signal.throwIfAborted();
  return new Promise<Value>((resolve, reject) => {
    const onAbort = (): void => { cleanup(); reject(signal.reason); };
    const cleanup = (): void => signal.removeEventListener("abort", onAbort);
    signal.addEventListener("abort", onAbort, { once: true });
    Promise.resolve().then(operation).then(value => { cleanup(); resolve(value); }, error => { cleanup(); reject(error); });
  });
}

export async function delay(milliseconds: number, signal: AbortSignal): Promise<void> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try { await withSignal(() => new Promise<void>(resolve => { timer = setTimeout(resolve, milliseconds); }), signal); }
  finally { clearTimeout(timer); }
}

export function header(headers: HttpHeaders, name: string): string | undefined {
  return headers.find(([key]) => key.toLowerCase() === name.toLowerCase())?.[1];
}

export function networkError(error: unknown): CurlError {
  if (error instanceof CurlError) return error;
  const code = error && typeof error === "object" && "code" in error ? String(error.code) : "";
  if (["ENOTFOUND", "EAI_AGAIN"].includes(code)) return new CurlError(6, "Could not resolve host");
  if (["ECONNREFUSED", "ENETUNREACH", "EHOSTUNREACH"].includes(code)) return new CurlError(7, "Failed to connect");
  if (/CERT|SELF_SIGNED|UNABLE_TO_VERIFY/.test(code)) return new CurlError(60, "TLS certificate verification failed");
  if (/TLS|SSL/.test(code)) return new CurlError(35, "TLS handshake failed");
  return new CurlError(56, "Network transfer failed");
}

export async function diagnostic(context: CommandContext, error: CurlError): Promise<void> {
  await writeBytes(context.stderr, encode(`curl: (${error.exitCode}) ${error.message}\n`), context.signal);
}

import { request as httpRequest, validateHeaderName, validateHeaderValue, type ClientRequest } from "node:http";
import { request as httpsRequest } from "node:https";
import { readBytes, type ByteSource } from "../../contracts/index.js";
import { CurlError, type HttpTransport } from "./types.js";
import { withSignal } from "./shared.js";

export interface NodeHttpTransportOptions {
  readonly ca?: string | Buffer | readonly (string | Buffer)[];
  readonly maxHeaderBytes?: number;
}

export function createNodeHttpTransport(options: NodeHttpTransportOptions = {}): HttpTransport {
  const maxHeaderSize = options.maxHeaderBytes ?? 64 * 1024;
  if (!Number.isSafeInteger(maxHeaderSize) || maxHeaderSize < 1) throw new RangeError("Invalid header limit");
  const ca = Array.isArray(options.ca) ? [...options.ca] : options.ca;
  return async input => {
    input.signal.throwIfAborted();
    const url = new URL(input.url);
    if (!["http:", "https:"].includes(url.protocol)) throw new CurlError(1, "Unsupported protocol");
    const headers: Record<string, string[]> = Object.create(null) as Record<string, string[]>;
    for (const [name, value] of input.headers) {
      validateHeaderName(name);
      validateHeaderValue(name, value);
      (headers[name.toLowerCase()] ??= []).push(value);
    }
    const stopped = new AbortController();
    const signal = AbortSignal.any([input.signal, stopped.signal]);
    return new Promise((resolve, reject) => {
      let request: ClientRequest | undefined;
      let finish: (() => void) | undefined;
      const closed = new Promise<void>(resolve => { finish = resolve; });
      let cleanup: Promise<void> | undefined;
      const dispose = (): Promise<void> => {
        cleanup ??= Promise.resolve().then(async () => {
          stopped.abort();
          if (request) { request.destroy(); await closed; }
        });
        return cleanup;
      };
      input.registerCleanup?.(dispose);
      request = (url.protocol === "https:" ? httpsRequest : httpRequest)(url, {
        method: input.method, headers, signal, maxHeaderSize, agent: false,
        ...(ca === undefined ? {} : { ca: ca as string | Buffer | (string | Buffer)[] }),
      }, response => {
        const responseHeaders: [string, string][] = [];
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
          responseHeaders.push([response.rawHeaders[index]!, response.rawHeaders[index + 1]!]);
        }
        const body: ByteSource = (async function* () {
          try {
            for await (const chunk of response) {
              input.signal.throwIfAborted();
              yield new Uint8Array(chunk as Buffer);
            }
          } finally { response.destroy(); await dispose(); }
        })();
        resolve({
          status: response.statusCode ?? 0, statusText: response.statusMessage ?? "",
          httpVersion: response.httpVersion, headers: responseHeaders, body,
          async dispose() { response.destroy(); await dispose(); },
        });
      });
      request.on("error", reject);
      request.on("close", () => { stopped.abort(); finish?.(); });
      const upload = async (): Promise<void> => {
        if (input.body) for await (const chunk of readBytes(input.body, signal)) {
          await withSignal(() => new Promise<void>((done, failed) => {
            request!.write(chunk, error => error ? failed(error) : done());
          }), signal);
        }
        request!.end();
      };
      void upload().catch(error => request!.destroy(error instanceof Error ? error : new Error("Upload canceled")));
    });
  };
}

import type { ByteSource, InvocationCleanup } from "../../contracts/index.js";

export type HttpHeaders = readonly (readonly [string, string])[];

export interface HttpRequest {
  readonly url: string;
  readonly method: string;
  readonly headers: HttpHeaders;
  readonly body?: ByteSource;
  readonly signal: AbortSignal;
  readonly registerCleanup?: (cleanup: InvocationCleanup) => void;
}

export interface HttpResponse {
  readonly status: number;
  readonly statusText: string;
  readonly headers: HttpHeaders;
  readonly httpVersion?: string;
  readonly body: ByteSource;
  dispose(): Promise<void>;
}

export type HttpTransport = (request: HttpRequest) => Promise<HttpResponse>;

export interface NetworkAuthorization {
  readonly url: string;
  readonly method: string;
  readonly redirectFrom?: string;
  readonly attempt: number;
  readonly signal: AbortSignal;
}

export type NetworkAuthorizer = (request: NetworkAuthorization) => boolean | Promise<boolean>;

export interface NetworkLimits {
  readonly maxUploadBytes: number;
  readonly maxDownloadBytes: number;
  readonly maxBufferBytes: number;
  readonly maxHeaderBytes: number;
  readonly maxRedirects: number;
  readonly maxRetries: number;
  readonly maxUrls: number;
  readonly maxTimeMs: number;
}

export interface NetworkCommandsOptions {
  readonly authorize: NetworkAuthorizer;
  readonly transport?: HttpTransport;
  readonly limits?: Partial<NetworkLimits>;
  readonly replace?: boolean;
}

export const defaultNetworkLimits: Readonly<NetworkLimits> = Object.freeze({
  maxUploadBytes: 64 * 1024 * 1024,
  maxDownloadBytes: 64 * 1024 * 1024,
  maxBufferBytes: 8 * 1024 * 1024,
  maxHeaderBytes: 64 * 1024,
  maxRedirects: 10,
  maxRetries: 5,
  maxUrls: 32,
  maxTimeMs: 120_000,
});

export class CurlError extends Error {
  constructor(readonly exitCode: number, message: string) {
    super(message);
    this.name = "CurlError";
  }
}

import { type CommandContext, type CommandDefinition, type FileStat } from "../contracts/index.js";
import { codeOf, define, pathOf, UsageError } from "./internal.js";

type Predicate = () => Promise<boolean>;

async function metadata(context: CommandContext, path: string, link = false): Promise<FileStat | undefined> {
  try { return await context.fs[link ? "lstat" : "stat"](pathOf(context, path), { signal: context.signal }); }
  catch (error) {
    context.signal.throwIfAborted();
    if (["ENOENT", "ENOTDIR", "EACCES", "ELOOP"].includes(codeOf(error) ?? "")) return undefined;
    throw error;
  }
}

export function predicateCommands(): CommandDefinition[] {
  return ["test", "["].map(name => define(name, async context => {
    const args = [...context.args];
    if (name === "[") {
      if (args.pop() !== "]") throw new UsageError("missing ']'");
    }
    if (!args.length) return { exitCode: 1 };
    if (args.length === 1) return { exitCode: args[0] ? 0 : 1 };
    if (args.length === 2 && args[0] === "!") return { exitCode: args[1] ? 1 : 0 };
    const unary = new Set(["-n", "-z", "-e", "-a", "-f", "-d", "-L", "-h", "-s", "-r", "-w", "-x"]);
    const binary = new Set(["=", "==", "!=", "<", ">", "-eq", "-ne", "-lt", "-le", "-gt", "-ge", "-nt", "-ot", "-ef"]);
    let offset = 0;
    const number = (text: string): bigint => {
      if (!/^[ \t]*[+-]?[0-9]+[ \t]*$/u.test(text)) throw new UsageError(`integer expression expected: '${text}'`);
      return BigInt(text.trim());
    };
    const primary = (): Predicate => {
      const token = args[offset++];
      if (token === undefined) throw new UsageError("argument expected");
      if (token === "!" && !binary.has(args[offset] ?? "")) { const inner = primary(); return async () => !await inner(); }
      if (token === "(" && !binary.has(args[offset] ?? "")) {
        const inner = disjunction();
        if (args[offset++] !== ")") throw new UsageError("missing ')'");
        return inner;
      }
      const operator = args[offset];
      if (operator !== undefined && binary.has(operator)) {
        offset++;
        const right = args[offset++];
        if (right === undefined) throw new UsageError("binary operator requires two operands");
        return async () => {
          if (operator === "=" || operator === "==") return token === right;
          if (operator === "!=") return token !== right;
          if (operator === "<") return token < right;
          if (operator === ">") return token > right;
          if (["-nt", "-ot", "-ef"].includes(operator)) {
            const leftStat = await metadata(context, token);
            const rightStat = await metadata(context, right);
            if (operator === "-nt") return leftStat !== undefined && (!rightStat || leftStat.mtimeMs > rightStat.mtimeMs);
            if (operator === "-ot") return rightStat !== undefined && (!leftStat || leftStat.mtimeMs < rightStat.mtimeMs);
            return leftStat?.ino !== undefined && rightStat?.ino !== undefined && leftStat.ino === rightStat.ino && leftStat.dev === rightStat.dev;
          }
          const leftNumber = number(token);
          const rightNumber = number(right);
          if (operator === "-eq") return leftNumber === rightNumber;
          if (operator === "-ne") return leftNumber !== rightNumber;
          if (operator === "-lt") return leftNumber < rightNumber;
          if (operator === "-le") return leftNumber <= rightNumber;
          if (operator === "-gt") return leftNumber > rightNumber;
          return leftNumber >= rightNumber;
        };
      }
      if (unary.has(token)) {
        const operand = args[offset++];
        if (operand === undefined) throw new UsageError("unary operator requires an operand");
        return async () => {
          if (token === "-n") return operand !== "";
          if (token === "-z") return operand === "";
          if (["-r", "-w", "-x"].includes(token)) {
            try { await context.fs.access(pathOf(context, operand), token === "-r" ? 4 : token === "-w" ? 2 : 1, { signal: context.signal }); return true; }
            catch (error) { context.signal.throwIfAborted(); if (["ENOENT", "ENOTDIR", "EACCES", "EROFS"].includes(codeOf(error) ?? "")) return false; throw error; }
          }
          const stat = await metadata(context, operand, token === "-L" || token === "-h");
          if (!stat) return false;
          if (token === "-f") return stat.type === "file";
          if (token === "-d") return stat.type === "directory";
          if (token === "-L" || token === "-h") return stat.type === "symlink";
          if (token === "-s") return stat.size > 0;
          return true;
        };
      }
      return async () => token !== "";
    };
    const conjunction = (): Predicate => {
      let predicate = primary();
      while (args[offset] === "-a") {
        offset++;
        const left = predicate;
        const right = primary();
        predicate = async () => await left() && await right();
      }
      return predicate;
    };
    const disjunction = (): Predicate => {
      let predicate = conjunction();
      while (args[offset] === "-o") {
        offset++;
        const left = predicate;
        const right = conjunction();
        predicate = async () => await left() || await right();
      }
      return predicate;
    };
    const evaluate = disjunction();
    if (offset !== args.length) throw new UsageError(`unexpected argument '${args[offset]}'`);
    return { exitCode: await evaluate() ? 0 : 1 };
  }));
}

import { parentPort } from "node:worker_threads";
import { compile } from "./matching.js";
import { matchExpr } from "../expr/bre-worker.js";
import { ExprMatchError, validateExprRequest, type ExprMatchRequest, type ExprMatchReply, type Request, type Reply } from "./protocol.js";

if (!parentPort) throw new Error("regex worker requires a parent port");
const port = parentPort;
let previous = "";
let matcher: ReturnType<typeof compile> | undefined;
port.on("message", (request: Request | ExprMatchRequest) => {
  if (request?.descriptor?.kind === "expr-match") {
    let reply: ExprMatchReply;
    try {
      validateExprRequest(request);
      reply = { id: request.id, operation: "expr-match", result: matchExpr(request.descriptor, request.rows[0]!.bytes) };
    } catch (error) {
      if (!(error instanceof ExprMatchError)) throw error;
      reply = { id: request.id, operation: "expr-match", category: error.category, error: error.message };
    }
    port.postMessage(reply);
    return;
  }
  const legacy = request as Request;
  let reply: Reply;
  try {
    const identity = JSON.stringify(request.descriptor);
    if (identity !== previous || !matcher) {
      matcher = undefined;
      matcher = compile(legacy.descriptor);
      previous = identity;
    }
    const results = request.rows.map((row, index) => {
      const matches = matcher!(row, index);
      const ranges = new Float64Array(matches.length * 2);
      for (let index = 0; index < matches.length; index++) {
        ranges[index * 2] = matches[index]!.start;
        ranges[index * 2 + 1] = matches[index]!.end;
      }
      return ranges;
    });
    reply = { id: request.id, results };
    port.postMessage(reply, results.map(result => result.buffer));
  } catch (error) {
    reply = { id: request.id, error: error instanceof Error ? error.message : String(error) };
    port.postMessage(reply);
  }
});
port.postMessage({ ready: true });

import { setImmediate } from "node:timers/promises";
import { readBytes, writeBytes, type ByteSink, type ByteSource } from "../../contracts/index.js";
import { SafeJsCommandLimitError } from "./types.js";
import { renderOutput } from "./render.js";

const chunkSize = 64 * 1024;

export class GuestInput {
  private readonly iterator: AsyncGenerator<Uint8Array>;
  private pending: Uint8Array = new Uint8Array();
  private consumed = 0;
  private pulls = 0;
  private queue = Promise.resolve();
  constructor(source: ByteSource, private readonly limit: number, private readonly signal: AbortSignal,
    private readonly fail: (error: unknown) => void, private readonly resource: "maxSourceBytes" | "maxInputBytes" = "maxInputBytes") {
    this.iterator = readBytes(source, signal);
  }
  private async take(size: number): Promise<Uint8Array | undefined> {
    this.signal.throwIfAborted();
    while (!this.pending.length) {
      if (++this.pulls % 64 === 0) await setImmediate(undefined, { signal: this.signal });
      const next = await this.iterator.next();
      if (next.done) return undefined;
      this.pending = next.value;
    }
    const length = Math.min(size, this.pending.length);
    if (length > this.limit - this.consumed) {
      const error = new SafeJsCommandLimitError(this.resource); this.fail(error); throw error;
    }
    const bytes = this.pending.slice(0, length);
    this.pending = this.pending.subarray(length);
    this.consumed += length;
    return bytes;
  }
  private serialize<Result>(operation: () => Promise<Result>): Promise<Result> {
    const result = this.queue.then(operation);
    this.queue = result.then(() => {}, () => {});
    return result;
  }
  readBytes(size: unknown = chunkSize): Promise<number[] | null> {
    if (typeof size !== "number" || !Number.isSafeInteger(size) || size < 1 || size > chunkSize) throw new TypeError("readBytes size must be an integer from 1 through 65536");
    return this.serialize(async () => { const bytes = await this.take(size); return bytes === undefined ? null : Array.from(bytes); });
  }
  readText(): Promise<string> {
    return this.serialize(async () => {
      const pieces: Uint8Array[] = [];
      for (;;) { const chunk = await this.take(chunkSize); if (!chunk) break; pieces.push(chunk); }
      return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(Buffer.concat(pieces));
    });
  }
  async close(): Promise<void> { await this.iterator.return(undefined); }
}

export class GuestOutput {
  private queue = Promise.resolve();
  private produced = 0;
  stderrFailed = false;
  constructor(private readonly stdout: ByteSink, private readonly stderr: ByteSink, private readonly limit: number,
    private readonly signal: AbortSignal, private readonly fail: (error: unknown) => void) {}
  private enqueue(bytes: Uint8Array, target: ByteSink): Promise<void> {
    this.signal.throwIfAborted();
    if (bytes.length > this.limit - this.produced) {
      const error = new SafeJsCommandLimitError("maxOutputBytes"); this.fail(error); throw error;
    }
    this.produced += bytes.length;
    const queued = this.queue.then(async () => {
      for (let offset = 0; offset < bytes.length; offset += chunkSize) await writeBytes(target, bytes.subarray(offset, offset + chunkSize), this.signal);
    }).catch(error => { if (target === this.stderr) this.stderrFailed = true; this.fail(error); throw error; });
    this.queue = queued;
    void queued.catch(() => {});
    return queued;
  }
  text(value: unknown, stderr = false): Promise<void> {
    if (typeof value !== "string") throw new TypeError("stdio text output requires a string");
    if (Buffer.byteLength(value) > this.limit - this.produced) {
      const error = new SafeJsCommandLimitError("maxOutputBytes"); this.fail(error); throw error;
    }
    return this.enqueue(Buffer.from(value), stderr ? this.stderr : this.stdout);
  }
  bytes(value: unknown, stderr = false): Promise<void> {
    if (!Array.isArray(value) || value.length > chunkSize) throw new TypeError("stdio byte output requires an array of at most 65536 bytes");
    for (const byte of value) if (!Number.isInteger(byte) || byte < 0 || byte > 255) throw new TypeError("stdio byte values must be integers from 0 through 255");
    return this.enqueue(Uint8Array.from(value as number[]), stderr ? this.stderr : this.stdout);
  }
  console(args: readonly unknown[], stderr: boolean): void {
    void this.text(renderOutput(args, this.limit - this.produced, this.fail), stderr);
  }
  result(value: unknown): Promise<void> {
    return this.text(renderOutput([value], this.limit - this.produced, this.fail));
  }
  async drain(): Promise<void> { await this.queue; }
}

import { UsageError } from "../internal.js";
import type { SafeJsCommandLimits } from "./types.js";

export const defaultSafeJsLimits: Readonly<SafeJsCommandLimits> = Object.freeze({
  maxSourceBytes: 1024 * 1024, maxInputBytes: 8 * 1024 * 1024, maxOutputBytes: 8 * 1024 * 1024,
  timeoutMs: 5000, maxSteps: 100_000, maxCallDepth: 128, stringLength: 1024 * 1024,
  arrayLength: 100_000, dataSize: 16 * 1024 * 1024,
});

export function commandLimits(options: Partial<SafeJsCommandLimits> = {}): SafeJsCommandLimits {
  const result = { ...defaultSafeJsLimits, ...options };
  for (const [name, value] of Object.entries(result)) {
    if (!Object.hasOwn(defaultSafeJsLimits, name)) throw new TypeError(`Unknown SafeJS limit: ${name}`);
    if (!Number.isSafeInteger(value) || value < (name === "timeoutMs" ? 1 : 0)) throw new RangeError(`Invalid SafeJS limit: ${name}`);
  }
  if (result.timeoutMs > 2_147_483_647) throw new RangeError("SafeJS timeoutMs exceeds timer range");
  return Object.freeze(result);
}

export interface Invocation { readonly source?: string; readonly file: string; readonly args: readonly string[]; readonly print: boolean; readonly help: boolean }

export function invocation(args: readonly string[]): Invocation {
  let print = false;
  for (let index = 0; index < args.length; index++) {
    const argument = args[index]!;
    if (argument === "-h" || argument === "--help") return { file: "-", args: [], print, help: true };
    if (argument === "-p" || argument === "--print") { print = true; continue; }
    if (argument === "-e" || argument === "--eval" || argument.startsWith("--eval=") || argument.startsWith("-e")) {
      const source = argument.startsWith("--eval=") ? argument.slice(7) : argument.length > 2 && argument !== "--eval" ? argument.slice(2) : args[++index];
      if (source === undefined) throw new UsageError(`${argument} requires SafeJS source`);
      const rest = args.slice(index + 1);
      return { source, file: "<safejs -e>", args: rest[0] === "--" ? rest.slice(1) : rest, print, help: false };
    }
    if (argument === "--") {
      const file = args[index + 1] ?? "-";
      return { file, args: args.slice(index + 2), print, help: false };
    }
    if (argument !== "-" && argument.startsWith("-")) throw new UsageError(`unrecognized option '${argument}'`);
    return { file: argument, args: args.slice(index + 1), print, help: false };
  }
  return { file: "-", args: [], print, help: false };
}

import { record } from "../../integrations/safejs/values.js";
import { SafeJsCommandLimitError } from "./types.js";

class Text {
  private readonly parts: string[] = [];
  private size = 0;
  private readonly active = new Set<object>();
  constructor(private readonly limit: number, private readonly fail: (error: unknown) => void) {}
  append(value: string): void {
    if (Buffer.byteLength(value) > this.limit - this.size) {
      const error = new SafeJsCommandLimitError("maxOutputBytes"); this.fail(error); throw error;
    }
    this.size += Buffer.byteLength(value);
    this.parts.push(value);
  }
  private quoted(value: string): void {
    if (Buffer.byteLength(value) + 2 > this.limit - this.size) {
      const error = new SafeJsCommandLimitError("maxOutputBytes"); this.fail(error); throw error;
    }
    this.append(JSON.stringify(value));
  }
  json(value: unknown, depth = 0): void {
    if (depth > 64) throw new TypeError("output JSON exceeds depth 64");
    if (value === null || value === undefined) { this.append("null"); return; }
    if (typeof value === "string") { this.quoted(value); return; }
    if (typeof value === "boolean" || typeof value === "number") { this.append(JSON.stringify(value)); return; }
    if (typeof value !== "object" || this.active.has(value)) throw new TypeError("output requires acyclic JSON data");
    this.active.add(value);
    try {
      if (Array.isArray(value)) {
        this.append("[");
        for (let index = 0; index < value.length; index++) {
          if (index) this.append(",");
          const property = Object.getOwnPropertyDescriptor(value, String(index));
          if (property && !("value" in property)) throw new TypeError("output arrays must contain data properties");
          this.json(property?.value, depth + 1);
        }
        this.append("]");
      } else {
        const entries = record(value, "output value");
        this.append("{");
        let first = true;
        for (const [key, item] of Object.entries(entries)) {
          if (item === undefined) continue;
          if (!first) this.append(","); first = false;
          this.quoted(key); this.append(":"); this.json(item, depth + 1);
        }
        this.append("}");
      }
    } finally { this.active.delete(value); }
  }
  finish(): string { return this.parts.join(""); }
}

export function renderOutput(values: readonly unknown[], limit: number, fail: (error: unknown) => void): string {
  const text = new Text(limit, fail);
  for (let index = 0; index < values.length; index++) {
    if (index) text.append(" ");
    const value = values[index];
    if (typeof value === "string") text.append(value);
    else if (value === undefined) text.append("undefined");
    else text.json(value);
  }
  text.append("\n");
  return text.finish();
}

