export function pathFor(context: CommandContext, path: string): string {
  if (!path || path.includes("\0")) throw new SearchError("invalid empty or NUL-containing path");
  return path.startsWith("/") ? path : `${context.cwd.replace(/\/$/u, "")}/${path}`;
}

export class OutputClosed extends SearchError {}

export class Limits {
  readonly maxOutputBytes: number;
  readonly maxLineBytes: number;
  readonly maxFileBytes: number;
  readonly maxFiles: number;
  outputBytes = 0;
  files = 0;
  private ticks = 0;
  private readonly stopped = new AbortController();
  readonly signal: AbortSignal;
  constructor(readonly context: CommandContext, options: SearchOptions) {
    this.signal = AbortSignal.any([context.signal, this.stopped.signal]);
    this.maxOutputBytes = options.maxOutputBytes ?? 16 * 1024 * 1024;
    this.maxLineBytes = options.maxLineBytes ?? 1024 * 1024;
    this.maxFileBytes = options.maxFileBytes ?? 64 * 1024 * 1024;
    this.maxFiles = options.maxFiles ?? 100000;
    for (const limit of [this.maxOutputBytes, this.maxLineBytes, this.maxFileBytes, this.maxFiles]) {
      if (!Number.isSafeInteger(limit) || limit < 1) throw new SearchError("search limits must be positive safe integers");
    }
  }
  async tick(): Promise<void> {
    this.context.signal.throwIfAborted();
    if (++this.ticks % 128 === 0) await setImmediate(undefined, { signal: this.context.signal });
  }
  private async write(chunk: Uint8Array): Promise<void> {
    try { await writeBytes(this.context.stdout, chunk, this.signal); }
    catch (error) {
      this.context.signal.throwIfAborted();
      if ((error as { code?: string }).code === "EPIPE") {
        const closed = new OutputClosed("stdout closed"); this.stopped.abort(closed); throw closed;
      }
      throw error;
    }
  }
  async output(value: string | Uint8Array): Promise<void> {
    const chunk = typeof value === "string" ? Buffer.from(value) : value;
    if (this.outputBytes + chunk.byteLength > this.maxOutputBytes) throw new SearchError("output byte limit exceeded");
    await this.write(chunk);
    this.outputBytes += chunk.byteLength;
  }
}

export async function* fileInput(context: CommandContext, path: string, limits: Limits): ByteSource {
  if (context.fs.readStream) yield* readBytes(context.fs.readStream(path, { signal: context.signal }), limits.signal);
  else yield await context.fs.readFile(path, { signal: context.signal, maxBytes: limits.maxFileBytes });
}

export async function diagnostic(context: CommandContext, error: unknown): Promise<void> {
  await writeBytes(context.stderr, Buffer.from(`rg: ${error instanceof Error ? error.message : String(error)}\n`), context.signal);
}

export interface Line { readonly bytes: Buffer; readonly content: Buffer; readonly number: number; readonly offset: number }
export interface ReadState { bytesRead: number; bytesSearched: number; binaryOffset: number | null; skipped: boolean }

export async function* lines(source: ByteSource, limits: Limits, state: ReadState, binary: "skip" | "binary" | "text", nullData: boolean): AsyncGenerator<Line> {
  let pending = Buffer.alloc(0);
  let offset = 0;
  let number = 0;
  const delimiter = nullData ? 0 : 10;
  for await (const data of readBytes(source, limits.signal)) {
    await limits.tick();
    const chunk = Buffer.from(data);
    if (state.bytesRead + chunk.length > limits.maxFileBytes) throw new SearchError("input file byte limit exceeded");
    const nul = nullData || binary === "text" ? -1 : chunk.indexOf(0);
    if (nul >= 0 && state.binaryOffset === null) state.binaryOffset = state.bytesRead + nul;
    state.bytesRead += chunk.length;
    if (nul >= 0 && binary === "skip") { state.skipped = true; return; }
    let start = 0;
    for (let end = 0; end < chunk.length; end++) {
      if (chunk[end] !== delimiter && !(binary === "binary" && chunk[end] === 0)) continue;
      if (pending.length + end - start > limits.maxLineBytes) throw new SearchError("line byte limit exceeded");
      const content = Buffer.concat([pending, chunk.subarray(start, end)]);
      const bytes = Buffer.concat([content, Buffer.from([delimiter])]);
      state.bytesSearched = offset + bytes.length;
      yield { content, bytes, number: ++number, offset };
      offset += bytes.length; pending = Buffer.alloc(0); start = end + 1;
    }
    if (pending.length + chunk.length - start > limits.maxLineBytes) throw new SearchError("line byte limit exceeded");
    pending = Buffer.concat([pending, chunk.subarray(start)]);
  }
  if (pending.length) { state.bytesSearched = offset + pending.length; yield { bytes: pending, content: pending, number: ++number, offset }; }
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { settings, type SplitCommandsOptions } from "./options.js";
import { createSplitCommand } from "./split.js";
export type { SplitCommandsOptions, SplitLimits } from "./options.js";

export function createSplitCommands(options: SplitCommandsOptions = {}): readonly CommandDefinition[] {
  return [createSplitCommand(settings(options))];
}

export function splitCommands(options: SplitCommandsOptions = {}): VirtualShellPlugin {
  const commands = createSplitCommands(options);
  return { name: "split-commands", setup(host) {
    if (!options.replace) for (const command of commands) {
      if (host.commands.has(command.name)) throw new Error(`Command already registered: ${command.name}`);
    }
    for (const command of commands) host.commands.register(command, { replace: options.replace ?? false });
  } };
}

import { setImmediate as yieldTurn } from "node:timers/promises";
import { FsError, readBytes, type ByteSource, type CommandContext } from "../../contracts/index.js";
import { pathOf } from "../internal.js";
import type { SplitLimits } from "./options.js";

export async function interruptible<Result>(operation: () => Promise<Result>, signal: AbortSignal): Promise<Result> {
  signal.throwIfAborted();
  return new Promise<Result>((resolve, reject) => {
    const abort = (): void => reject(signal.reason);
    signal.addEventListener("abort", abort, { once: true });
    Promise.resolve().then(() => { signal.throwIfAborted(); return operation(); }).then(resolve, reject)
      .finally(() => signal.removeEventListener("abort", abort));
  });
}

export class Budget {
  private inputBytes = 0;
  private outputBytes = 0;
  private steps = 0;
  private untilYield = 65536;
  constructor(readonly limits: SplitLimits, readonly signal: AbortSignal) {}
  check(value: number, maximum: number, label: string): void {
    if (value > maximum) throw new FsError("EFBIG", { message: `split ${label} limit exceeded` });
  }
  input(size: number): void {
    this.check(size, this.limits.maxInputBytes - this.inputBytes, "input");
    this.inputBytes += size;
  }
  output(size: number): void {
    this.signal.throwIfAborted();
    this.check(size, this.limits.maxOutputBytes - this.outputBytes, "output");
    this.outputBytes += size;
  }
  async step(count = 1): Promise<void> {
    this.signal.throwIfAborted();
    this.check(count, this.limits.maxSteps - this.steps, "work");
    this.steps += count;
    this.untilYield -= count;
    if (this.untilYield <= 0) {
      this.untilYield = 65536;
      await yieldTurn(undefined, { signal: this.signal }).catch(error => { this.signal.throwIfAborted(); throw error; });
    }
    this.signal.throwIfAborted();
  }
}

export class Cursor {
  private readonly iterator: AsyncGenerator<Uint8Array>;
  private bytes: Uint8Array = new Uint8Array();
  private offset = 0;
  private ended = false;

  constructor(context: CommandContext, input: string, readonly budget: Budget) {
    const { signal, limits } = budget;
    const source = (async function* (): ByteSource {
      if (input === "-") yield* readBytes(context.stdin, signal);
      else {
        const path = pathOf(context, input);
        if (context.fs.readStream && context.fs.capabilities.streamingRead !== false) {
          yield* readBytes(context.fs.readStream(path, { signal, chunkSize: limits.maxChunkBytes }), signal);
        } else {
          const maxBytes = Math.min(limits.maxInputBytes, limits.maxBufferBytes);
          const bytes = await interruptible(() => context.fs.readFile(path, { signal, maxBytes }), signal);
          budget.check(bytes.byteLength, maxBytes, "read buffer");
          yield bytes;
        }
      }
    })();
    this.iterator = readBytes(source, signal);
  }

  async peek(): Promise<Uint8Array> {
    while (!this.ended && this.offset === this.bytes.length) {
      await this.budget.step();
      const result = await this.iterator.next();
      if (result.done) { this.ended = true; this.bytes = new Uint8Array(); this.offset = 0; break; }
      this.budget.input(result.value.byteLength);
      this.bytes = result.value;
      this.offset = 0;
    }
    return this.bytes.subarray(this.offset, Math.min(this.bytes.length, this.offset + this.budget.limits.maxChunkBytes));
  }

  take(size: number): Uint8Array {
    const result = new Uint8Array(this.bytes.subarray(this.offset, this.offset + size));
    this.offset += size;
    return result;
  }

  close(): void {
    void this.iterator.return(undefined).catch(() => {});
  }
}

import type { SplitArguments, SplitLimits } from "./options.js";

export class Names {
  private digits: number[];
  private extension = "";
  private first = true;

  constructor(private readonly args: SplitArguments, private readonly limits: SplitLimits) {
    this.digits = Array.from({ length: args.suffixLength }, () => 0);
    if (args.alphabet[0] === "0") {
      const start = args.numericStart.padStart(args.suffixLength, "0");
      this.digits = Array.from(start, digit => Number(digit));
    }
  }

  next(): string {
    if (!this.first) {
      let advanced = false;
      for (let index = this.digits.length - 1; index >= 0; index--) {
        this.digits[index] = this.digits[index]! + 1;
        if (index === 0 && this.args.automatic && this.digits[index] === this.args.alphabet.length - 1) {
          if (this.extension.length + this.digits.length + 2 > this.limits.maxSuffixLength) throw new Error("split suffix length limit exceeded");
          this.extension += this.args.alphabet.at(-1)!;
          this.digits = Array.from({ length: this.digits.length + 1 }, () => 0);
          advanced = true;
          break;
        }
        if (this.digits[index]! < this.args.alphabet.length) { advanced = true; break; }
        this.digits[index] = 0;
      }
      if (!advanced) throw new Error("output file suffixes exhausted");
    }
    this.first = false;
    return this.args.prefix + this.extension + this.digits.map(digit => this.args.alphabet[digit]).join("") + this.args.additionalSuffix;
  }
}

export interface SplitLimits {
  readonly maxInputBytes: number;
  readonly maxOutputBytes: number;
  readonly maxFiles: number;
  readonly maxBufferBytes: number;
  readonly maxChunkBytes: number;
  readonly maxArgumentBytes: number;
  readonly maxSuffixLength: number;
  readonly maxSteps: number;
}

export interface SplitCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<SplitLimits>;
}

export function settings(options: SplitCommandsOptions): SplitLimits {
  const limits: SplitLimits = {
    maxInputBytes: 256 * 1024 * 1024, maxOutputBytes: 256 * 1024 * 1024,
    maxFiles: 4096, maxBufferBytes: 8 * 1024 * 1024, maxChunkBytes: 64 * 1024,
    maxArgumentBytes: 65536, maxSuffixLength: 128, maxSteps: 512 * 1024 * 1024,
    ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid split limit: ${name}`);
  }
  return limits;
}

export interface SplitArguments {
  readonly mode: "lines" | "bytes" | "line-bytes";
  readonly size: number;
  readonly input: string;
  readonly prefix: string;
  readonly alphabet: string;
  readonly suffixLength: number;
  readonly automatic: boolean;
  readonly numericStart: string;
  readonly additionalSuffix: string;
}

function number(text: string, label: string, units = false, zero = false): number {
  const match = /^[\t\n\v\f\r ]*\+?([0-9]*)([a-zA-Z]*)$/u.exec(text);
  if (!match || (!match[1] && (!units || !match[2] || text !== match[2]))) throw new Error(`invalid ${label}: '${text}'`);
  const suffix = match[2]!;
  let multiplier = 1;
  if (suffix) {
    if (!units) throw new Error(`invalid ${label}: '${text}'`);
    if (suffix === "b") multiplier = 512;
    else {
      const unit = /^([kKmMGTPEZYRQ])(?:(i?B))?$/u.exec(suffix);
      if (!unit) throw new Error(`invalid ${label}: '${text}'`);
      const exponent = "KMGTPEZYRQ".indexOf(unit[1]!.toUpperCase()) + 1;
      multiplier = (unit[2] === "B" ? 1000 : 1024) ** exponent;
    }
  }
  const value = Number(match[1] || "1") * multiplier;
  if (!Number.isSafeInteger(value) || value < (zero ? 0 : 1)) throw new Error(`invalid ${label}: '${text}'`);
  return value;
}

export function parseArguments(args: readonly string[], limits: SplitLimits): SplitArguments {
  if (args.reduce((total, argument) => total + Buffer.byteLength(argument), 0) > limits.maxArgumentBytes) {
    throw new Error("split argument limit exceeded");
  }
  let mode: SplitArguments["mode"] | undefined;
  let size = 1000;
  let suffixLength = 0;
  let numeric = false;
  let numericStart: string | undefined;
  let additionalSuffix = "";
  const operands: string[] = [];
  let ended = false;
  const apply = (option: string, value?: string): void => {
    if (option === "d") {
      numeric = true;
      if (value !== undefined) {
        if (!/^[0-9]*$/u.test(value)) throw new Error(`invalid start value for numerical suffix: '${value}'`);
        numericStart = value.replace(/^0+(?=\d)/u, "") || "0";
      }
    } else if (option === "a") suffixLength = number(value!, "suffix length", false, true);
    else if (option === "additional-suffix") {
      if (value!.includes("/") || value!.includes("\0")) throw new Error("invalid additional suffix: contains directory separator or NUL");
      additionalSuffix = value!;
    } else {
      if (mode) throw new Error("cannot split in more than one way");
      mode = option === "l" ? "lines" : option === "b" ? "bytes" : "line-bytes";
      size = number(value!, option === "l" ? "number of lines" : "number of bytes", option !== "l");
    }
  };
  const long: Readonly<Record<string, string>> = {
    lines: "l", bytes: "b", "line-bytes": "C", "suffix-length": "a",
    "numeric-suffixes": "d", "additional-suffix": "additional-suffix",
  };
  for (let index = 0; index < args.length; index++) {
    const argument = args[index]!;
    if (ended || argument === "-" || !argument.startsWith("-")) { operands.push(argument); continue; }
    if (argument === "--") { ended = true; continue; }
    if (argument.startsWith("--")) {
      const equals = argument.indexOf("=");
      const name = argument.slice(2, equals < 0 ? undefined : equals);
      const option = long[name];
      if (!option) throw new Error(`unrecognized option '${argument}'`);
      const value = equals < 0 ? (option === "d" ? undefined : args[++index]) : argument.slice(equals + 1);
      if (option !== "d" && value === undefined) throw new Error(`option '--${name}' requires an argument`);
      apply(option, value);
    } else {
      for (let offset = 1; offset < argument.length; offset++) {
        const option = argument[offset]!;
        if (!"lbaCd".includes(option)) throw new Error(`invalid option -- '${option}'`);
        if (option === "d") apply(option);
        else {
          const value = argument.slice(offset + 1) || args[++index];
          if (value === undefined) throw new Error(`option requires an argument -- '${option}'`);
          apply(option, value);
          break;
        }
      }
    }
  }
  if (operands.length > 2) throw new Error(`extra operand '${operands[2]}'`);
  if ((suffixLength || 2) > limits.maxSuffixLength) throw new Error("split suffix length limit exceeded");
  if (numericStart !== undefined && numericStart.length > (suffixLength || 2)) throw new Error("numerical suffix start value is too large for the suffix length");
  if (mode === "line-bytes" && size > limits.maxBufferBytes) throw new Error("split line-bytes window exceeds buffer limit");
  return {
    mode: mode ?? "lines", size, input: operands[0] ?? "-", prefix: operands[1] ?? "x",
    alphabet: numeric ? "0123456789" : "abcdefghijklmnopqrstuvwxyz",
    suffixLength: suffixLength || 2, automatic: suffixLength === 0 && numericStart === undefined,
    numericStart: numericStart ?? "0", additionalSuffix,
  };
}

import { FsError, isFsError, type CommandContext, type FileStat, type WriteFileOptions } from "../../contracts/index.js";
import { pathOf } from "../internal.js";
import { Budget, interruptible } from "./io.js";

interface Entry { readonly path: string; readonly stat: FileStat }

function complete(stat: FileStat): boolean {
  return ((typeof stat.identityScope === "object" && stat.identityScope !== null) || typeof stat.identityScope === "symbol")
    && typeof stat.dev === "number" && Number.isSafeInteger(stat.dev) && stat.dev >= 0
    && typeof stat.ino === "number" && Number.isSafeInteger(stat.ino) && stat.ino >= 0;
}

export class Outputs {
  private input: Entry | undefined;
  private readonly published: Entry[] = [];
  constructor(private readonly context: CommandContext, private readonly budget: Budget) {}

  async prepareInput(name: string): Promise<void> {
    if (name === "-") return;
    const path = pathOf(this.context, name);
    const stat = await this.stat(path);
    if (stat.type === "directory") throw new FsError("EISDIR", { path });
    if (stat.type !== "file") throw new FsError("ENOTSUP", { path, message: "input is not a regular file" });
    this.input = { path, stat };
  }

  private stat(path: string): Promise<FileStat> {
    return interruptible(() => this.context.fs.stat(path, { signal: this.budget.signal }), this.budget.signal);
  }

  private async distinct(previous: Entry, current: Entry): Promise<void> {
    await this.budget.step();
    let relation: "same" | "distinct" | "unknown" = "unknown";
    if (previous.path === current.path) relation = "same";
    else if (complete(previous.stat) && complete(current.stat)) {
      relation = previous.stat.identityScope === current.stat.identityScope && previous.stat.dev === current.stat.dev && previous.stat.ino === current.stat.ino ? "same" : "distinct";
    } else if (this.context.fs.compareEntry) {
      relation = await interruptible(() => this.context.fs.compareEntry!(previous.path, this.context.fs, current.path, { signal: this.budget.signal }), this.budget.signal);
      if (relation !== "same" && relation !== "distinct" && relation !== "unknown") throw new FsError("EIO", { path: current.path, message: "invalid entry comparison answer" });
    }
    if (relation === "unknown") {
      const before = await interruptible(() => this.context.fs.realpath(previous.path, { signal: this.budget.signal }), this.budget.signal);
      const after = await interruptible(() => this.context.fs.realpath(current.path, { signal: this.budget.signal }), this.budget.signal);
      if (before === after) relation = "same";
    }
    if (relation === "same") throw new FsError("EINVAL", { path: current.path, message: previous === this.input ? "output would overwrite input; aborting" : "output aliases an earlier output; aborting" });
    if (relation === "unknown") throw new FsError("ENOTSUP", { path: current.path, message: "cannot establish that existing output is distinct from input or earlier output" });
  }

  private async destination(path: string, links = 0): Promise<{ path: string; stat?: FileStat }> {
    await this.budget.step();
    let entry: FileStat;
    try {
      entry = await interruptible(() => this.context.fs.lstat(path, { signal: this.budget.signal }), this.budget.signal);
    } catch (error) {
      this.budget.signal.throwIfAborted();
      if (isFsError(error, "ENOENT")) return { path };
      throw error;
    }
    if (entry.type !== "symlink") return { path, stat: entry };
    try { return { path, stat: await this.stat(path) }; }
    catch (error) {
      this.budget.signal.throwIfAborted();
      if (!isFsError(error, "ENOENT")) throw error;
    }
    if (!this.context.fs.readlink) throw new FsError("ENOTSUP", { path, message: "cannot resolve dangling output symlink without readlink" });
    if (links >= 40) throw new FsError("ELOOP", { path });
    const target = await interruptible(() => this.context.fs.readlink!(path, { signal: this.budget.signal }), this.budget.signal);
    const parent = target.startsWith("/") ? "" : await interruptible(
      () => this.context.fs.realpath(path.slice(0, path.lastIndexOf("/")) || "/", { signal: this.budget.signal }), this.budget.signal);
    return this.destination(target.startsWith("/") ? target : `${parent.replace(/\/$/u, "")}/${target}`, links + 1);
  }

  async prepare(name: string): Promise<{ path: string; flag: NonNullable<WriteFileOptions["flag"]> }> {
    const { path, stat } = await this.destination(pathOf(this.context, name));
    if (!stat) return { path, flag: "wx" };
    if (stat.type === "directory") throw new FsError("EISDIR", { path });
    if (stat.type !== "file") throw new FsError("ENOTSUP", { path, message: "output is not a regular file" });
    const current = { path, stat };
    if (this.input) await this.distinct(this.input, current);
    for (const previous of this.published) await this.distinct(previous, current);
    return { path, flag: "w" };
  }

  async remember(path: string): Promise<void> {
    this.published.push({ path, stat: await this.stat(path) });
  }
}

import { FsError, isFsError, collectBytes, writeBytes, type ByteSource, type CommandContext, type CommandDefinition } from "../../contracts/index.js";
import { Budget, Cursor, interruptible } from "./io.js";
import { Names } from "./names.js";
import { Outputs } from "./outputs.js";
import { parseArguments, type SplitArguments, type SplitLimits } from "./options.js";

async function* segment(cursor: Cursor, args: SplitArguments): AsyncGenerator<Uint8Array> {
  let remaining = args.size;
  while (remaining > 0) {
    const bytes = await cursor.peek();
    if (!bytes.length) break;
    let count = args.mode === "bytes" ? Math.min(remaining, bytes.length) : bytes.length;
    if (args.mode === "lines") {
      for (let offset = 0; offset < bytes.length; offset++) {
        if (bytes[offset] === 10 && --remaining === 0) { count = offset + 1; break; }
      }
    } else remaining -= count;
    await cursor.budget.step(count);
    yield cursor.take(count);
  }
}

class LineBytes {
  private readonly buffer: Uint8Array;
  private used = 0;
  constructor(private readonly cursor: Cursor, private readonly size: number) { this.buffer = new Uint8Array(size); }
  async next(): Promise<Uint8Array> {
    while (this.used < this.size) {
      const bytes = await this.cursor.peek();
      if (!bytes.length) break;
      const count = Math.min(bytes.length, this.size - this.used);
      await this.cursor.budget.step(count);
      this.buffer.set(this.cursor.take(count), this.used);
      this.used += count;
    }
    let count = this.used;
    if (this.used === this.size) {
      for (let offset = this.used - 1; offset >= 0; offset--) {
        if (this.buffer[offset] === 10) { count = offset + 1; break; }
      }
    }
    const result = this.buffer.slice(0, count);
    this.buffer.copyWithin(0, count, this.used);
    this.used -= count;
    return result;
  }
}

async function run(context: CommandContext, limits: SplitLimits): Promise<void> {
  const args = parseArguments(context.args, limits);
  const controller = new AbortController();
  const signal = AbortSignal.any([context.signal, controller.signal]);
  const budget = new Budget(limits, signal);
  const outputs = new Outputs(context, budget);
  const names = new Names(args, limits);
  let cursor: Cursor | undefined;
  try {
    await outputs.prepareInput(args.input);
    let name = names.next();
    let initial: Awaited<ReturnType<Outputs["prepare"]>> | undefined;
    let initialDirectoryError: FsError | undefined;
    if (args.input !== "-") {
      try { initial = await outputs.prepare(name); }
      catch (error) {
        signal.throwIfAborted();
        if (!isFsError(error, "EISDIR")) throw error;
        initialDirectoryError = error;
      }
    }
    cursor = new Cursor(context, args.input, budget);
    const window = args.mode === "line-bytes" ? new LineBytes(cursor, args.size) : undefined;
    let files = 0;
    while (true) {
      const chunks = window ? (async function* (): AsyncGenerator<Uint8Array> {
        const bytes = await window.next();
        for (let offset = 0; offset < bytes.length; offset += limits.maxChunkBytes) yield bytes.slice(offset, offset + limits.maxChunkBytes);
      })() : segment(cursor, args);
      const first = await chunks.next();
      if (first.done) break;
      budget.check(++files, limits.maxFiles, "file");
      if (files > 1) name = names.next();
      if (files === 1 && initialDirectoryError) throw initialDirectoryError;
      const destination = files === 1 && initial ? initial : await outputs.prepare(name);
      const source = (async function* (): ByteSource {
        budget.output(first.value.length);
        yield first.value;
        for await (const chunk of chunks) {
          budget.output(chunk.length);
          yield chunk;
        }
      })();
      if (context.fs.writeStream && context.fs.capabilities.streamingWrite !== false) {
        await interruptible(() => context.fs.writeStream!(destination.path, source, { signal, flag: destination.flag }), signal);
      } else {
        const bytes = await collectBytes(source, { signal, maxBytes: limits.maxBufferBytes });
        await interruptible(() => context.fs.writeFile(destination.path, bytes, { signal, flag: destination.flag }), signal);
      }
      await outputs.remember(destination.path);
    }
  } catch (error) {
    controller.abort(error);
    throw error;
  } finally {
    cursor?.close();
  }
}

export function createSplitCommand(limits: SplitLimits): CommandDefinition {
  return { name: "split", async execute(context) {
    context.signal.throwIfAborted();
    try {
      await run(context, limits);
      context.signal.throwIfAborted();
      return { exitCode: 0 };
    } catch (error) {
      context.signal.throwIfAborted();
      const message = error instanceof FsError ? error.message.slice(error.code.length + 2) : error instanceof Error ? error.message : String(error);
      await writeBytes(context.stderr, Buffer.from(`split: ${message.slice(0, 4096)}\n`), context.signal);
      return { exitCode: 1 };
    }
  } };
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createSeqCommand } from "./seq.js";
import { createNlCommand } from "./nl.js";
import { createRevCommand } from "./rev.js";
import { createUnexpandCommand } from "./unexpand.js";
import { settings, type StreamFormatCommandsOptions } from "./shared.js";
export type { StreamFormatCommandsOptions, StreamFormatLimits } from "./shared.js";

export function createStreamFormatCommands(options: StreamFormatCommandsOptions = {}): readonly CommandDefinition[] {
  const limits = settings(options);
  return [createSeqCommand(limits), createNlCommand(limits), createRevCommand(limits), createUnexpandCommand(limits)];
}

export function streamFormatCommands(options: StreamFormatCommandsOptions = {}): VirtualShellPlugin {
  const commands = createStreamFormatCommands(options);
  return { name: "stream-format-commands", setup(host) {
    if (!options.replace) for (const definition of commands) {
      if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
    }
    for (const definition of commands) host.commands.register(definition, { replace: options.replace ?? false });
  } };
}

import type { CommandDefinition } from "../../contracts/index.js";
import { integer, options, UsageError, value } from "../internal.js";
import { Pattern } from "../text-programs/regex.js";
import { Budget } from "../text-programs/shared.js";
import { command, records, type Session, type StreamFormatLimits } from "./shared.js";

type Style = "a" | "t" | "n" | Pattern;

class PatternBudget extends Budget {
  constructor(readonly session: Session) {
    super({ ...session.context, signal: session.signal }, { maxSteps: session.limits.maxSteps, maxBufferBytes: session.limits.maxRecordBytes });
  }
  override step(count = 1): void { this.session.charge(count); }
}

function style(text: string): Style {
  if (text === "a" || text === "t" || text === "n") return text;
  if (text.startsWith("p")) return new Pattern(Buffer.from(text.slice(1)).toString("latin1"), false);
  throw new UsageError(`invalid numbering style: '${text}'`);
}

function signed(text: string): bigint {
  if (!/^[+-]?\d+$/u.test(text.trim())) throw new UsageError(`invalid line number: '${text}'`);
  const number = BigInt(text);
  if (number < -(1n << 63n) || number >= 1n << 63n) throw new UsageError(`line number out of range: '${text}'`);
  return number;
}

export function createNlCommand(limits: StreamFormatLimits): CommandDefinition {
  return command("nl", limits, async session => {
    const parsed = options(session.context.args, "h:b:f:v:i:pl:s:w:n:d:", {
      "header-numbering": "h", "body-numbering": "b", "footer-numbering": "f",
      "starting-line-number": "v", "line-increment": "i", "no-renumber": "p",
      "join-blank-lines": "l", "number-separator": "s", "number-width": "w",
      "number-format": "n", "section-delimiter": "d",
    });
    const header = style(value(parsed, "h") ?? "n"), body = style(value(parsed, "b") ?? "t"), footer = style(value(parsed, "f") ?? "n");
    const start = signed(value(parsed, "v") ?? "1"), increment = signed(value(parsed, "i") ?? "1");
    const join = Math.max(1, integer(value(parsed, "l") ?? "1")), width = integer(value(parsed, "w") ?? "6", 1);
    const separator = value(parsed, "s") ?? "\t", format = value(parsed, "n") ?? "rn";
    if (!["ln", "rn", "rz"].includes(format)) throw new UsageError(`invalid line numbering format: '${format}'`);
    session.check(width + Buffer.byteLength(separator), limits.maxRecordBytes, "number field");
    let delimiter = Buffer.from("\\:");
    for (const argument of parsed.values.get("d") ?? []) {
      const next = Buffer.from(argument);
      delimiter = next.length === 1 ? Buffer.concat([next, delimiter.subarray(1)]) : next;
    }
    const delimiters = [1, 2, 3].map(count => Buffer.concat(Array.from({ length: count }, () => delimiter)));
    const budget = new PatternBudget(session);
    const unnumbered = " ".repeat(width + Buffer.byteLength(separator));
    let current: Style = body, number = start, blanks = 0;
    await session.files(session.names(parsed.operands), async source => {
      for await (const record of records(source, session)) {
        const bytes = Buffer.from(record);
        const section = delimiter.length ? delimiters.findIndex(candidate => candidate.equals(bytes)) : -1;
        if (section >= 0) {
          current = section === 0 ? footer : section === 1 ? body : header;
          if (!parsed.flags.has("p")) number = start;
          await session.text("\n");
          continue;
        }
        let numbered: boolean;
        if (current === "a") {
          numbered = record.length > 0 || ++blanks === join || join === 1;
          if (numbered) blanks = 0;
        } else if (current === "t") numbered = record.length > 0;
        else if (current === "n") numbered = false;
        else numbered = current.find(bytes.toString("latin1"), budget) !== undefined;
        if (numbered) {
          if (number < -(1n << 63n) || number >= 1n << 63n) throw new UsageError("line number overflow");
          let label = number.toString();
          if (format === "ln") label = label.padEnd(width, " ");
          else if (format === "rz" && number < 0n) label = "-" + label.slice(1).padStart(width - 1, "0");
          else label = label.padStart(width, format === "rz" ? "0" : " ");
          await session.text(label + separator);
          number += increment;
        } else await session.text(unnumbered);
        await session.output(record);
        await session.text("\n");
      }
    });
  });
}

import type { CommandDefinition } from "../../contracts/index.js";
import { diagnostic, options, UsageError } from "../internal.js";
import { command, records, type Session, type StreamFormatLimits } from "./shared.js";

async function validPrefix(bytes: Uint8Array, session: Session): Promise<number> {
  for (let offset = 0; offset < bytes.length;) {
    await session.step();
    const first = bytes[offset]!;
    if (first < 128) { offset++; continue; }
    const width = first >= 194 && first <= 223 ? 2 : first >= 224 && first <= 239 ? 3 : first >= 240 && first <= 244 ? 4 : 0;
    if (!width || offset + width > bytes.length) return offset;
    for (let position = 1; position < width; position++) {
      const next = bytes[offset + position]!;
      if (next < 128 || next > 191) return offset;
    }
    const second = bytes[offset + 1]!;
    if (first === 224 && second < 160 || first === 237 && second >= 160 || first === 240 && second < 144 || first === 244 && second > 143) return offset;
    offset += width;
  }
  return bytes.length;
}

async function reversed(bytes: Uint8Array, utf8: boolean, session: Session): Promise<Uint8Array> {
  const result = new Uint8Array(bytes.length);
  let destination = 0;
  for (let end = bytes.length; end > 0;) {
    await session.step();
    let start = end - 1;
    if (utf8) while (start > 0 && (bytes[start]! & 192) === 128) start--;
    result.set(bytes.subarray(start, end), destination);
    destination += end - start;
    end = start;
  }
  return result;
}

export function createRevCommand(limits: StreamFormatLimits): CommandDefinition {
  return command("rev", limits, async session => {
    const parsed = options(session.context.args, "", {}, true);
    const locale = session.context.env.LC_ALL || session.context.env.LC_CTYPE || session.context.env.LANG || "C";
    const utf8 = /(?:^|[._-])utf-?8(?:@.*)?$/iu.test(locale);
    if (!utf8 && locale !== "C" && locale !== "POSIX") throw new UsageError(`unsupported character encoding locale: '${locale}'`);
    const names = parsed.operands.length ? parsed.operands.map(name => name === "-" ? "./-" : name) : [];
    await session.files(session.names(names), async (source, name) => {
      for await (const record of records(source, session)) {
        const length = utf8 ? await validPrefix(record, session) : record.length;
        if (length || length === record.length) {
          await session.output(await reversed(record.subarray(0, length), utf8, session));
          await session.text("\n");
        }
        if (length !== record.length) {
          await diagnostic(session.context, new Error(`${name === "-" ? "stdin" : name}: Illegal byte sequence`));
          session.failed = true;
          break;
        }
      }
    });
  });
}

import { FsError, readBytes, resolvePath, writeBytes, type ByteSource, type CommandContext, type CommandDefinition } from "../../contracts/index.js";
import { diagnostic } from "../internal.js";

export interface StreamFormatLimits {
  readonly maxInputBytes: number;
  readonly maxOutputBytes: number;
  readonly maxRecordBytes: number;
  readonly maxChunkBytes: number;
  readonly maxFiles: number;
  readonly maxSteps: number;
  readonly maxArgumentBytes: number;
  readonly maxNumericDigits: number;
}

export interface StreamFormatCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<StreamFormatLimits>;
}

export function settings(options: StreamFormatCommandsOptions): StreamFormatLimits {
  const limits = {
    maxInputBytes: 32 * 1024 * 1024, maxOutputBytes: 64 * 1024 * 1024,
    maxRecordBytes: 8 * 1024 * 1024, maxChunkBytes: 1024 * 1024,
    maxFiles: 64, maxSteps: 256 * 1024 * 1024, maxArgumentBytes: 65536,
    maxNumericDigits: 4096, ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid stream-format limit: ${name}`);
  }
  return limits;
}

class InputFailure extends Error {
  constructor(readonly original: unknown) { super("input failed"); }
}

export class Session {
  private inputBytes = 0;
  private outputBytes = 0;
  private steps = 0;
  private untilYield = 4096;
  private stdin: AsyncIterator<Uint8Array> | undefined;
  private readonly controller = new AbortController();
  readonly signal: AbortSignal;
  failed = false;

  constructor(readonly context: CommandContext, readonly limits: StreamFormatLimits) {
    this.signal = AbortSignal.any([context.signal, this.controller.signal]);
    this.check(context.args.reduce((size, argument) => size + Buffer.byteLength(argument), 0), limits.maxArgumentBytes, "argument");
  }

  check(size: number, maximum: number, label: string): void {
    if (!Number.isSafeInteger(size) || size > maximum) throw new FsError("EFBIG", { message: `stream-format ${label} limit exceeded` });
  }

  charge(count = 1): void {
    this.signal.throwIfAborted();
    this.steps += count;
    this.check(this.steps, this.limits.maxSteps, "step");
    this.untilYield -= count;
  }

  async step(count = 1): Promise<void> {
    this.charge(count);
    if (this.untilYield <= 0) {
      this.untilYield = 4096;
      await new Promise<void>(resolve => setImmediate(resolve));
      this.signal.throwIfAborted();
    }
  }

  async output(bytes: Uint8Array): Promise<void> {
    this.check(this.outputBytes + bytes.length, this.limits.maxOutputBytes, "output");
    this.outputBytes += bytes.length;
    const width = Math.min(16384, this.limits.maxChunkBytes);
    for (let offset = 0; offset < bytes.length; offset += width) {
      await this.step();
      await writeBytes(this.context.stdout, new Uint8Array(bytes.subarray(offset, offset + width)), this.signal);
    }
  }

  async text(text: string): Promise<void> { await this.output(Buffer.from(text)); }

  names(operands: readonly string[]): readonly string[] {
    const names = operands.length ? operands : ["-"];
    this.check(names.length, this.limits.maxFiles, "file");
    return names;
  }

  private async *read(name: string): ByteSource {
    const controller = new AbortController();
    const signal = AbortSignal.any([this.signal, controller.signal]);
    let reader: AsyncGenerator<Uint8Array> | undefined;
    try {
      const session = this;
      const source = (async function* (): ByteSource {
        if (name === "-") {
          session.stdin ??= session.context.stdin[Symbol.asyncIterator]();
          const cursor = session.stdin;
          yield* { [Symbol.asyncIterator]() { return { next: () => cursor.next() }; } };
        } else {
          if (!name) throw new FsError("ENOENT", { path: name });
          const path = resolvePath(session.context.cwd, name);
          const stat = await session.context.fs.stat(path, { signal });
          signal.throwIfAborted();
          if (stat.type === "directory") throw new FsError("EISDIR", { path });
          if (session.context.fs.readStream) yield* session.context.fs.readStream(path, { signal });
          else yield await session.context.fs.readFile(path, { signal, maxBytes: Math.min(session.limits.maxChunkBytes, session.limits.maxInputBytes - session.inputBytes) });
        }
      })();
      reader = readBytes(source, signal);
      while (true) {
        await this.step();
        let item: IteratorResult<Uint8Array>;
        try { item = await reader.next(); }
        catch (error) { this.signal.throwIfAborted(); throw new InputFailure(error); }
        if (item.done) break;
        this.check(item.value.length, this.limits.maxChunkBytes, "chunk");
        this.inputBytes += item.value.length;
        this.check(this.inputBytes, this.limits.maxInputBytes, "input");
        yield item.value;
      }
    } finally {
      controller.abort(new FsError("EPIPE", { message: "stream-format input transfer ended" }));
      if (reader) await reader.return(undefined).catch(() => {});
    }
  }

  async files(names: readonly string[], process: (source: ByteSource, name: string) => Promise<void>): Promise<void> {
    for (const name of names) {
      try { await process(this.read(name), name); }
      catch (error) {
        this.signal.throwIfAborted();
        if (!(error instanceof InputFailure)) throw error;
        await diagnostic(this.context, error.original);
        this.failed = true;
      }
    }
  }

  async close(): Promise<void> {
    this.controller.abort(new FsError("EPIPE", { message: "stream-format command ended" }));
    if (this.stdin?.return) {
      const cleanup = Promise.resolve().then(() => this.stdin!.return!());
      void cleanup.catch(() => {});
    }
  }
}

export function command(name: string, limits: StreamFormatLimits, run: (session: Session) => Promise<void>): CommandDefinition {
  return { name, async execute(context) {
    context.signal.throwIfAborted();
    let session: Session | undefined;
    try {
      session = new Session(context, limits);
      await run(session);
      context.signal.throwIfAborted();
      return { exitCode: session.failed ? 1 : 0 };
    } catch (error) {
      context.signal.throwIfAborted();
      await diagnostic(context, error);
      return { exitCode: 1 };
    } finally { await session?.close(); }
  } };
}

export async function* records(source: ByteSource, session: Session): AsyncGenerator<Uint8Array> {
  let buffer = new Uint8Array(Math.min(1024, session.limits.maxRecordBytes));
  let size = 0;
  for await (const chunk of source) {
    for (const byte of chunk) {
      await session.step();
      if (byte === 10) {
        yield buffer.slice(0, size);
        size = 0;
      } else {
        session.check(size + 1, session.limits.maxRecordBytes, "record");
        if (size === buffer.length) {
          const grown = new Uint8Array(Math.min(buffer.length * 2, session.limits.maxRecordBytes));
          grown.set(buffer); buffer = grown;
        }
        buffer[size++] = byte;
      }
    }
  }
  if (size) yield buffer.slice(0, size);
}

export class ByteOutput {
  private readonly bytes: Uint8Array;
  private size = 0;
  constructor(readonly session: Session) { this.bytes = new Uint8Array(Math.min(16384, session.limits.maxChunkBytes)); }
  async byte(value: number): Promise<void> {
    this.bytes[this.size++] = value;
    if (this.size === this.bytes.length) await this.flush();
  }
  async flush(): Promise<void> {
    if (this.size) await this.session.output(this.bytes.subarray(0, this.size));
    this.size = 0;
  }
}

import type { CommandDefinition } from "../../contracts/index.js";
import { integer, options, UsageError } from "../internal.js";
import { ByteOutput, command, type Session, type StreamFormatLimits } from "./shared.js";

function tabStops(specifications: readonly string[], session: Session): (column: number) => number | undefined {
  const stops: number[] = [];
  let repeat = 0, relative = false;
  for (const specification of specifications) {
    for (const entry of specification.split(/[, \t]+/u).filter(Boolean)) {
      if (repeat) throw new UsageError("repeating tab stop must be last");
      const marker = entry[0] === "+" || entry[0] === "/" ? entry[0] : "";
      const number = integer(entry.slice(marker.length), 1);
      if (marker) { repeat = number; relative = marker === "+"; }
      else {
        if (number <= (stops.at(-1) ?? 0)) throw new UsageError("tab stops must be ascending");
        stops.push(number);
      }
    }
  }
  if (!stops.length && !repeat) repeat = 8;
  if (stops.length === 1 && !repeat) repeat = stops.pop()!;
  return column => {
    let lower = 0, upper = stops.length;
    while (lower < upper) {
      session.charge();
      const middle = Math.floor((lower + upper) / 2);
      if (stops[middle]! <= column) lower = middle + 1; else upper = middle;
    }
    if (lower < stops.length) return stops[lower]!;
    if (!repeat) return undefined;
    const origin = relative ? stops.at(-1) ?? 0 : 0;
    const next = column + repeat - (column - origin) % repeat;
    session.check(next, Number.MAX_SAFE_INTEGER, "column");
    return next;
  };
}

export function createUnexpandCommand(limits: StreamFormatLimits): CommandDefinition {
  return command("unexpand", limits, async session => {
    const normalized: string[] = [], obsolete: string[] = [];
    let ended = false;
    for (let index = 0; index < session.context.args.length; index++) {
      const argument = session.context.args[index]!;
      if (!ended && /^-\d[\d,]*$/u.test(argument)) obsolete.push(argument.slice(1));
      else {
        normalized.push(argument);
        if (argument === "--") ended = true;
        if (!ended && (argument === "-t" || argument === "--tabs") && index + 1 < session.context.args.length) normalized.push(session.context.args[++index]!);
      }
    }
    const parsed = options(normalized, "at:F", { all: "a", tabs: "t", "first-only": "F" });
    const nextTab = tabStops([...obsolete, ...parsed.values.get("t") ?? []], session);
    const all = !parsed.flags.has("F") && (parsed.flags.has("a") || parsed.flags.has("t"));
    const output = new ByteOutput(session);
    let column = 0, initial = true, active = true;
    let pendingStart = 0, pendingCount = 0, pendingTab = false;
    const flushBlanks = async (): Promise<void> => {
      if (!pendingCount) return;
      let position = pendingStart;
      const convertSingle = initial || pendingCount > 1 || pendingTab;
      while (position < column) {
        await session.step();
        const stop = nextTab(position);
        if (stop !== undefined && stop <= column && (stop - position > 1 || convertSingle)) {
          await output.byte(9); position = stop;
        } else { await output.byte(32); position++; }
      }
      pendingCount = 0; pendingTab = false;
    };
    await session.files(session.names(parsed.operands), async source => {
      for await (const chunk of source) {
        for (const byte of chunk) {
          await session.step();
          if (active && (byte === 32 || byte === 9)) {
            const stop = nextTab(column);
            if (stop !== undefined) {
              if (!pendingCount) pendingStart = column;
              pendingCount++;
              pendingTab ||= byte === 9;
              column = byte === 9 ? stop : column + 1;
              session.check(column, Number.MAX_SAFE_INTEGER, "column");
              continue;
            }
            await flushBlanks(); active = false;
          } else await flushBlanks();
          await output.byte(byte);
          if (byte === 10) { column = 0; initial = true; active = true; }
          else if (active) {
            column = byte === 8 ? Math.max(0, column - 1) : column + 1;
            session.check(column, Number.MAX_SAFE_INTEGER, "column");
            initial = false;
            if (!all) active = false;
          }
        }
        await output.flush();
      }
    });
    await flushBlanks();
    await output.flush();
  });
}

import type { CommandDefinition } from "../../contracts/index.js";
import { integer, UsageError } from "../internal.js";
import { numericOptions } from "./numeric-options.js";
import { ByteOutput, command, type StreamInspectionLimits } from "./shared.js";

function tabs(specifications: readonly string[]): (column: number) => number {
  const stops: number[] = [];
  let absoluteRepeat = 0, relativeRepeat = 0;
  for (const specification of specifications) {
    const entries = specification.split(/[, \t]+/u);
    let marker = "";
    for (const entry of entries) {
      if (!entry) continue;
      const prefix = entry.match(/^[+/]+/u)?.[0] ?? "";
      if (prefix) marker = prefix.at(-1)!;
      const number = entry.slice(prefix.length);
      if (!number) continue;
      const stop = integer(number, marker ? 0 : 1);
      if (marker === "+") {
        if (relativeRepeat) throw new UsageError("repeating tab stop must be last");
        relativeRepeat = stop;
      } else if (marker === "/") {
        if (absoluteRepeat) throw new UsageError("repeating tab stop must be last");
        absoluteRepeat = stop;
      } else {
        if (stop <= (stops.at(-1) ?? 0)) throw new UsageError("tab stops must be ascending");
        stops.push(stop);
      }
    }
  }
  if (absoluteRepeat && relativeRepeat) throw new UsageError("'/' specifier is mutually exclusive with '+'");
  let repeat = absoluteRepeat || relativeRepeat;
  const relative = relativeRepeat !== 0;
  if (!stops.length && !repeat) repeat = 8;
  if (stops.length === 1 && !repeat) repeat = stops.pop()!;
  return column => {
    let lower = 0, upper = stops.length;
    while (lower < upper) {
      const middle = Math.floor((lower + upper) / 2);
      if (stops[middle]! <= column) lower = middle + 1; else upper = middle;
    }
    if (lower < stops.length) return stops[lower]!;
    if (!repeat) return column + 1;
    const origin = relative ? stops.at(-1) ?? 0 : 0;
    return column + repeat - (column - origin) % repeat;
  };
}

export function createExpandCommand(limits: StreamInspectionLimits): CommandDefinition {
  return command("expand", limits, async session => {
    const parsed = numericOptions(session.context.args, "it:", { initial: "i", tabs: "t" }, "t");
    const nextTab = tabs(parsed.values.get("t") ?? []);
    const output = new ByteOutput(session);
    let column = 0, initial = true;
    await session.files(session.names(parsed.operands), async source => {
      for await (const chunk of source) {
        for (const byte of chunk) {
          await session.step();
          if (byte === 9 && (initial || !parsed.flags.has("i"))) {
            const stop = nextTab(column);
            session.check(stop - column, limits.maxOutputBytes, "output");
            while (column < stop) { await session.step(); await output.byte(32); column++; }
          } else {
            await output.byte(byte);
            if (byte === 10) { column = 0; initial = true; }
            else { column = byte === 8 ? Math.max(0, column - 1) : column + 1; if (byte !== 32 && byte !== 9) initial = false; }
          }
        }
        await output.flush();
      }
    });
    await output.flush();
  });
}

import type { CommandDefinition } from "../../contracts/index.js";
import { integer } from "../internal.js";
import { numericOptions } from "./numeric-options.js";
import { command, RecordBuffer, type StreamInspectionLimits } from "./shared.js";

export function createFoldCommand(limits: StreamInspectionLimits): CommandDefinition {
  return command("fold", limits, async session => {
    const parsed = numericOptions(session.context.args, "bsw:", { bytes: "b", spaces: "s", width: "w" }, "w");
    let width = 80;
    for (const specification of parsed.values.get("w") ?? []) width = integer(specification, 1);
    const adjust = (column: number, byte: number): number => {
      if (parsed.flags.has("b")) return column + 1;
      if (byte === 8) return Math.max(0, column - 1);
      if (byte === 13) return 0;
      return column + (byte === 9 ? 8 - column % 8 : 1);
    };
    await session.files(session.names(parsed.operands), async source => {
      const record = new RecordBuffer(session);
      let column = 0, lastBlank = -1;
      for await (const chunk of source) {
        for (const byte of chunk) {
          await session.step();
          if (byte === 10) {
            await session.output(record.view()); await session.output(Uint8Array.of(10));
            record.clear(); column = 0; lastBlank = -1; continue;
          }
          while (adjust(column, byte) > width && record.size) {
            const boundary = parsed.flags.has("s") && lastBlank >= 0 ? lastBlank + 1 : record.size;
            await session.output(record.view().subarray(0, boundary));
            await session.output(Uint8Array.of(10));
            record.drop(boundary); column = 0; lastBlank = -1;
            for (const retained of record.view()) { await session.step(); column = adjust(column, retained); }
          }
          column = adjust(column, byte);
          record.push(byte);
          if (byte === 32 || byte === 9) lastBlank = record.size - 1;
        }
      }
      await session.output(record.view());
    });
  });
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createTacCommand } from "./tac.js";
import { createExpandCommand } from "./expand.js";
import { createFoldCommand } from "./fold.js";
import { createStringsCommand } from "./strings.js";
import { settings, type StreamInspectionCommandsOptions } from "./shared.js";
export type { StreamInspectionCommandsOptions, StreamInspectionLimits } from "./shared.js";

export function createStreamInspectionCommands(options: StreamInspectionCommandsOptions = {}): readonly CommandDefinition[] {
  const limits = settings(options);
  return [createTacCommand(limits), createExpandCommand(limits), createFoldCommand(limits), createStringsCommand(limits)];
}

export function streamInspectionCommands(options: StreamInspectionCommandsOptions = {}): VirtualShellPlugin {
  const commands = createStreamInspectionCommands(options);
  return { name: "stream-inspection-commands", setup(host) {
    if (!options.replace) for (const definition of commands) {
      if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
    }
    for (const definition of commands) host.commands.register(definition, { replace: options.replace ?? false });
  } };
}

import { options, type ParsedOptions } from "../internal.js";

export function numericOptions(
  args: readonly string[], short: string, long: Readonly<Record<string, string>>, key?: string,
): ParsedOptions & { readonly legacyValue?: string } {
  const normalized: string[] = [], ordered: string[] = [], operands: string[] = [];
  let ended = false, legacyIndex: number | undefined, legacyFallback = "";
  for (let index = 0; index < args.length; index++) {
    const argument = args[index]!;
    normalized.push(argument);
    if (ended || argument === "-" || !argument.startsWith("-")) {
      operands.push(argument);
      continue;
    }
    ordered.push(argument);
    if (argument === "--") { ended = true; continue; }
    if (argument.startsWith("--")) {
      const name = argument.slice(2);
      if (long[name] && short.includes(`${long[name]}:`) && index + 1 < args.length) {
        const argumentValue = args[++index]!;
        normalized.push(argumentValue); ordered.push(argumentValue);
      }
      continue;
    }
    for (let offset = 1; offset < argument.length; offset++) {
      const option = argument[offset]!;
      if (option >= "0" && option <= "9") {
        if (key) {
          normalized[normalized.length - 1] = `${argument.slice(0, offset)}${key}${argument.slice(offset)}`;
          break;
        }
        legacyIndex = index - (offset === argument.length - 1 ? 0 : 1);
        legacyFallback = argument.slice(1);
      } else if (short.includes(`${option}:`)) {
        if (offset === argument.length - 1 && index + 1 < args.length) {
          const argumentValue = args[++index]!;
          normalized.push(argumentValue); ordered.push(argumentValue);
        }
        break;
      } else if (!short.includes(option)) break;
    }
  }
  const parsed = options(normalized, key ? short : `${short}0123456789`, long);
  return legacyIndex === undefined ? parsed : {
    ...parsed, legacyValue: [...ordered, ...operands][legacyIndex]?.slice(1) ?? legacyFallback,
  };
}

import { FsError, readBytes, resolvePath, writeBytes, type ByteSource, type CommandContext, type CommandDefinition } from "../../contracts/index.js";
import { diagnostic } from "../internal.js";

export interface StreamInspectionLimits {
  readonly maxInputBytes: number;
  readonly maxOutputBytes: number;
  readonly maxRecordBytes: number;
  readonly maxChunkBytes: number;
  readonly maxFiles: number;
  readonly maxSteps: number;
  readonly maxArgumentBytes: number;
}

export interface StreamInspectionCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<StreamInspectionLimits>;
}

export function settings(options: StreamInspectionCommandsOptions): StreamInspectionLimits {
  const limits = {
    maxInputBytes: 32 * 1024 * 1024, maxOutputBytes: 64 * 1024 * 1024,
    maxRecordBytes: 8 * 1024 * 1024, maxChunkBytes: 1024 * 1024,
    maxFiles: 64, maxSteps: 256 * 1024 * 1024, maxArgumentBytes: 65536,
    ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid stream-inspection limit: ${name}`);
  }
  return limits;
}

class InputFailure extends Error {
  constructor(readonly original: unknown) { super("input failed"); }
}

export class Session {
  private inputBytes = 0;
  private outputBytes = 0;
  private steps = 0;
  private untilYield = 4096;
  private stdin: AsyncIterator<Uint8Array> | undefined;
  private controller = new AbortController();
  readonly signal: AbortSignal;
  failed = false;

  constructor(readonly context: CommandContext, readonly limits: StreamInspectionLimits) {
    this.signal = AbortSignal.any([context.signal, this.controller.signal]);
    this.check(context.args.reduce((size, value) => size + Buffer.byteLength(value), 0), limits.maxArgumentBytes, "argument");
  }

  check(size: number, maximum: number, label: string): void {
    if (size > maximum) throw new FsError("EFBIG", { message: `stream-inspection ${label} limit exceeded` });
  }

  async step(count = 1): Promise<void> {
    this.signal.throwIfAborted();
    this.steps += count;
    this.check(this.steps, this.limits.maxSteps, "step");
    this.untilYield -= count;
    if (this.untilYield <= 0) {
      this.untilYield = 4096;
      await new Promise<void>(resolve => setImmediate(resolve));
      this.signal.throwIfAborted();
    }
  }

  async output(bytes: Uint8Array): Promise<void> {
    this.check(this.outputBytes + bytes.length, this.limits.maxOutputBytes, "output");
    this.outputBytes += bytes.length;
    const width = Math.min(16384, this.limits.maxChunkBytes);
    for (let offset = 0; offset < bytes.length; offset += width) {
      await this.step();
      await writeBytes(this.context.stdout, new Uint8Array(bytes.subarray(offset, offset + width)), this.signal);
    }
  }

  names(operands: readonly string[]): readonly string[] {
    const names = operands.length ? operands : ["-"];
    this.check(names.length, this.limits.maxFiles, "file");
    return names;
  }

  private async *read(name: string): ByteSource {
    const controller = new AbortController();
    const signal = AbortSignal.any([this.signal, controller.signal]);
    let reader: AsyncGenerator<Uint8Array> | undefined;
    try {
      const session = this;
      const source = (async function* (): ByteSource {
        if (name === "-") {
          session.stdin ??= session.context.stdin[Symbol.asyncIterator]();
          const cursor = session.stdin;
          yield* { [Symbol.asyncIterator]() { return { next: () => cursor.next() }; } };
        } else {
          if (!name) throw new FsError("ENOENT", { path: name });
          const path = resolvePath(session.context.cwd, name);
          const stat = await session.context.fs.stat(path, { signal });
          signal.throwIfAborted();
          if (stat.type === "directory") throw new FsError("EISDIR", { path });
          if (session.context.fs.readStream) yield* session.context.fs.readStream(path, { signal });
          else yield await session.context.fs.readFile(path, { signal, maxBytes: Math.min(session.limits.maxChunkBytes, session.limits.maxInputBytes - session.inputBytes) });
        }
      })();
      reader = readBytes(source, signal);
      while (true) {
        await this.step();
        let item: IteratorResult<Uint8Array>;
        try { item = await reader.next(); }
        catch (error) { this.signal.throwIfAborted(); throw new InputFailure(error); }
        if (item.done) break;
        this.check(item.value.length, this.limits.maxChunkBytes, "chunk");
        this.inputBytes += item.value.length;
        this.check(this.inputBytes, this.limits.maxInputBytes, "input");
        yield item.value;
      }
    } finally {
      controller.abort(new FsError("EPIPE", { message: "stream-inspection input transfer ended" }));
      if (reader) await reader.return(undefined).catch(() => {});
    }
  }

  async files(names: readonly string[], process: (source: ByteSource, name: string) => Promise<void>): Promise<void> {
    for (const name of names) {
      try { await process(this.read(name), name); }
      catch (error) {
        this.signal.throwIfAborted();
        if (!(error instanceof InputFailure)) throw error;
        await diagnostic(this.context, error.original);
        this.failed = true;
      }
    }
  }

  async close(): Promise<void> {
    this.controller.abort(new FsError("EPIPE", { message: "stream-inspection command ended" }));
    if (this.stdin?.return) {
      const cleanup = Promise.resolve().then(() => this.stdin!.return!());
      void cleanup.catch(() => {});
    }
  }
}

export function command(name: string, limits: StreamInspectionLimits, run: (session: Session) => Promise<void>): CommandDefinition {
  return { name, async execute(context) {
    context.signal.throwIfAborted();
    let session: Session | undefined;
    try {
      session = new Session(context, limits);
      await run(session);
      context.signal.throwIfAborted();
      return { exitCode: session.failed ? 1 : 0 };
    } catch (error) {
      context.signal.throwIfAborted();
      await diagnostic(context, error);
      return { exitCode: 1 };
    } finally { await session?.close(); }
  } };
}

export class ByteOutput {
  private bytes: Uint8Array;
  private size = 0;
  constructor(readonly session: Session) { this.bytes = new Uint8Array(Math.min(16384, session.limits.maxChunkBytes)); }
  async byte(value: number): Promise<void> {
    this.bytes[this.size++] = value;
    if (this.size === this.bytes.length) await this.flush();
  }
  async flush(): Promise<void> {
    if (this.size) await this.session.output(this.bytes.subarray(0, this.size));
    this.size = 0;
  }
}

export class RecordBuffer {
  private bytes: Uint8Array;
  size = 0;
  constructor(readonly session: Session) { this.bytes = new Uint8Array(Math.min(1024, session.limits.maxRecordBytes)); }
  push(byte: number): void {
    this.session.check(this.size + 1, this.session.limits.maxRecordBytes, "record");
    if (this.size === this.bytes.length) {
      const grown = new Uint8Array(Math.min(this.bytes.length * 2, this.session.limits.maxRecordBytes));
      grown.set(this.bytes); this.bytes = grown;
    }
    this.bytes[this.size++] = byte;
  }
  view(): Uint8Array { return this.bytes.subarray(0, this.size); }
  drop(count: number): void { this.bytes.copyWithin(0, count, this.size); this.size -= count; }
  clear(): void { this.size = 0; }
}

import type { CommandDefinition } from "../../contracts/index.js";
import { integer, UsageError, value } from "../internal.js";
import { numericOptions } from "./numeric-options.js";
import { command, RecordBuffer, type StreamInspectionLimits } from "./shared.js";

export function createStringsCommand(limits: StreamInspectionLimits): CommandDefinition {
  return command("strings", limits, async session => {
    const parsed = numericOptions(session.context.args, "afn:t:", { all: "a", "print-file-name": "f", bytes: "n", radix: "t" });
    let minimum = 4;
    for (const specification of parsed.values.get("n") ?? []) minimum = integer(specification, 1);
    if (parsed.legacyValue !== undefined) {
      const specification = parsed.legacyValue;
      if (!/^(?:0[0-7]*|[1-9][0-9]*)$/u.test(specification)) throw new UsageError(`invalid number '${specification}'`);
      minimum = Number.parseInt(specification, specification.startsWith("0") ? 8 : 10);
      if (minimum < 1 || minimum >= 4294967295) throw new UsageError(`invalid number '${specification}'`);
    }
    const radix = value(parsed, "t");
    if (radix !== undefined && !["d", "o", "x"].includes(radix)) throw new UsageError(`invalid radix '${radix}'`);
    const files = parsed.operands.filter(name => name !== "-");
    if (parsed.operands.length && !files.length) throw new UsageError("missing file operand after '-' (use no operands for stdin)");
    await session.files(session.names(files), async (source, name) => {
      const record = new RecordBuffer(session);
      let offset = 0, start = 0;
      const flush = async () => {
        if (record.size >= minimum) {
          const label = parsed.flags.has("f") ? `${name === "-" ? "{standard input}" : name}: ` : "";
          const location = radix === undefined ? "" : `${start.toString(radix === "x" ? 16 : radix === "o" ? 8 : 10).padStart(7, " ")} `;
          await session.output(new TextEncoder().encode(label + location));
          await session.output(record.view());
          await session.output(Uint8Array.of(10));
        }
        record.clear();
      };
      for await (const chunk of source) {
        for (const byte of chunk) {
          await session.step();
          if (byte === 9 || byte >= 32 && byte <= 126) {
            if (!record.size) start = offset;
            record.push(byte);
          } else await flush();
          offset++;
        }
      }
      await flush();
    });
  });
}

import type { CommandDefinition } from "../../contracts/index.js";
import { options, value } from "../internal.js";
import { command, type StreamInspectionLimits } from "./shared.js";

export function createTacCommand(limits: StreamInspectionLimits): CommandDefinition {
  return command("tac", limits, async session => {
    const parsed = options(session.context.args, "bs:", { before: "b", separator: "s" });
    const text = value(parsed, "s") ?? "\n";
    const separator = Buffer.from(text || "\0");
    const reversed = Uint8Array.from(separator).reverse();
    const prefix = new Uint32Array(reversed.length);
    for (let index = 1, matched = 0; index < reversed.length; index++) {
      await session.step();
      while (matched && reversed[index] !== reversed[matched]) { matched = prefix[matched - 1]!; await session.step(); }
      if (reversed[index] === reversed[matched]) matched++;
      prefix[index] = matched;
    }
    await session.files(session.names(parsed.operands), async source => {
      let bytes = new Uint8Array(Math.min(65536, limits.maxInputBytes));
      let size = 0;
      for await (const chunk of source) {
        if (size + chunk.length > bytes.length) {
          const grown = new Uint8Array(Math.min(limits.maxInputBytes, Math.max(size + chunk.length, bytes.length * 2)));
          grown.set(bytes.subarray(0, size)); bytes = grown;
        }
        bytes.set(chunk, size); size += chunk.length;
      }
      let end = size, matched = 0;
      for (let index = size - 1; index >= 0; index--) {
        await session.step();
        while (matched && bytes[index] !== reversed[matched]) { matched = prefix[matched - 1]!; await session.step(); }
        if (bytes[index] === reversed[matched]) matched++;
        if (matched !== reversed.length) continue;
        const boundary = parsed.flags.has("b") ? index : index + separator.length;
        session.check(end - boundary, limits.maxRecordBytes, "record");
        await session.output(bytes.subarray(boundary, end));
        end = boundary;
        matched = 0;
      }
      session.check(end, limits.maxRecordBytes, "record");
      await session.output(bytes.subarray(0, end));
    });
  });
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { jqCommand } from "./jq.js";
import type { StructuredCommandsOptions } from "./limits.js";

export { defaultJqLimits } from "./limits.js";
export type { JqLimits, StructuredCommandsOptions } from "./limits.js";

export function createStructuredCommands(options: StructuredCommandsOptions = {}): readonly CommandDefinition[] {
  return [jqCommand(options)];
}
export function structuredCommands(options: StructuredCommandsOptions = {}): VirtualShellPlugin {
  const definitions = createStructuredCommands(options);
  return {
    name: "structured-commands",
    setup(host) {
      if (!options.replace) for (const definition of definitions) {
        if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
      }
      for (const definition of definitions) host.commands.register(definition, { replace: options.replace ?? false });
    },
  };
}

import { setImmediate } from "node:timers/promises";
import { Decimal, isNumber, numberText } from "./numbers.js";

export type Json = null | boolean | number | Decimal | string | Json[] | { [key: string]: Json };
export interface JqLimits {
  readonly maxInputBytes: number;
  readonly maxValueBytes: number;
  readonly maxOutputBytes: number;
  readonly maxSourceBytes: number;
  readonly maxDepth: number;
  readonly maxAstDepth: number;
  readonly maxSteps: number;
  readonly maxResults: number;
  readonly maxCollectionSize: number;
}
export interface StructuredCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<JqLimits>;
}
export const defaultJqLimits: Readonly<JqLimits> = Object.freeze({
  maxInputBytes: 64 * 1024 * 1024, maxValueBytes: 8 * 1024 * 1024,
  maxOutputBytes: 16 * 1024 * 1024, maxSourceBytes: 64 * 1024,
  maxDepth: 128, maxAstDepth: 64, maxSteps: 1_000_000,
  maxResults: 100_000, maxCollectionSize: 100_000,
});
export class JqError extends Error {
  constructor(message: string, readonly exitCode = 5) { super(message); }
}
export class JqLimitError extends JqError {
  constructor(name: keyof JqLimits) { super(`${name} limit exceeded`); }
}
export interface InputLocation {
  name: string;
  line: number;
  complete: boolean;
}
export function resolveJqLimits(options: Partial<JqLimits> = {}): JqLimits {
  const limits = { ...defaultJqLimits, ...options };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`${name} must be a positive safe integer`);
  }
  if (limits.maxDepth > 256 || limits.maxAstDepth > 128) throw new RangeError("maxDepth must be <=256 and maxAstDepth <=128");
  return Object.freeze(limits);
}
export class Budget {
  private steps = 0;
  private nextYield = 1024;
  inputBytes = 0;
  outputBytes = 0;
  results = 0;
  inputLocation: InputLocation = { name: "<unknown>", line: 0, complete: true };
  constructor(readonly limits: JqLimits, readonly signal: AbortSignal) {}
  step(count = 1): void {
    this.signal.throwIfAborted();
    this.steps += count;
    if (this.steps > this.limits.maxSteps) throw new JqLimitError("maxSteps");
  }
  async tick(): Promise<void> {
    this.step();
    if (this.steps >= this.nextYield) {
      this.nextYield = this.steps + 1024;
      await setImmediate(undefined, { signal: this.signal });
      this.signal.throwIfAborted();
    }
  }
  collection(size: number): void {
    if (size > this.limits.maxCollectionSize) throw new JqLimitError("maxCollectionSize");
  }
  text(text: string): void {
    if (text.length > this.limits.maxValueBytes || Buffer.byteLength(text) > this.limits.maxValueBytes) throw new JqLimitError("maxValueBytes");
  }
  value(value: Json): number {
    let bytes = 0;
    const visit = (current: Json, depth: number): void => {
      this.step();
      if (depth > this.limits.maxDepth) throw new JqLimitError("maxDepth");
      if (current !== null && typeof current === "object" && !(current instanceof Decimal)) {
        if (depth + 1 > this.limits.maxDepth) throw new JqLimitError("maxDepth");
        const keys = Array.isArray(current) ? Object.keys(current) : objectKeys(current);
        this.collection(keys.length);
        bytes += 2 + Math.max(0, keys.length - 1);
        for (const key of keys) {
          if (!Array.isArray(current)) {
            this.text(key);
            bytes += Buffer.byteLength(JSON.stringify(key)) + 1;
          }
          if (bytes > this.limits.maxValueBytes) throw new JqLimitError("maxValueBytes");
          visit((current as Record<string, Json>)[key]!, depth + 1);
        }
      } else {
        if (typeof current === "string") this.text(current);
        bytes += Buffer.byteLength(scalarJson(current, this));
      }
      if (bytes > this.limits.maxValueBytes) throw new JqLimitError("maxValueBytes");
    };
    visit(value, 0);
    return bytes;
  }
}
const keyOrders = new WeakMap<Record<string, Json>, string[]>();
export function object(): Record<string, Json> {
  const result = Object.create(null) as Record<string, Json>;
  keyOrders.set(result, []);
  return result;
}
export function objectKeys(value: Record<string, Json>): string[] { return keyOrders.get(value)?.slice() ?? Object.keys(value); }
export function objectSize(value: Record<string, Json>): number { return keyOrders.get(value)?.length ?? Object.keys(value).length; }
export function put(value: Record<string, Json>, key: string, item: Json): void {
  if (!Object.hasOwn(value, key)) keyOrders.get(value)?.push(key);
  value[key] = item;
}
export function remove(value: Record<string, Json>, key: string): void {
  delete value[key];
  const keys = keyOrders.get(value);
  if (keys) { const index = keys.indexOf(key); if (index >= 0) keys.splice(index, 1); }
}
export function copyObject(...sources: (Record<string, Json> | null)[]): Record<string, Json> {
  const result = object();
  for (const source of sources) if (source) for (const key of objectKeys(source)) put(result, key, source[key]!);
  return result;
}
export function wellFormed(text: string): boolean {
  for (let index = 0; index < text.length; index++) {
    const code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(++index);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return false;
    } else if (code >= 0xdc00 && code <= 0xdfff) return false;
  }
  return true;
}
export function isObject(value: Json): value is Record<string, Json> { return value !== null && typeof value === "object" && !Array.isArray(value) && !(value instanceof Decimal); }
export function truth(value: Json): boolean { return value !== null && value !== false; }
export function scalarJson(value: null | boolean | number | Decimal | string, budget: Budget): string {
  if (value instanceof Decimal) budget.step(Math.ceil(value.text.length / 32));
  return isNumber(value) ? numberText(value) : JSON.stringify(value);
}
export async function interruptible<Result>(operation: () => PromiseLike<Result>, signal: AbortSignal): Promise<Result> {
  signal.throwIfAborted();
  return new Promise<Result>((resolve, reject) => {
    const aborted = (): void => { signal.removeEventListener("abort", aborted); reject(signal.reason); };
    signal.addEventListener("abort", aborted, { once: true });
    try {
      Promise.resolve(operation()).then(
        result => { signal.removeEventListener("abort", aborted); resolve(result); },
        error => { signal.removeEventListener("abort", aborted); reject(error); },
      );
    } catch (error) { signal.removeEventListener("abort", aborted); reject(error); }
  });
}

import type { Budget } from "./limits.js";

export class Decimal {
  constructor(readonly digits: string, readonly exponent: number, readonly negative: boolean, readonly text: string, readonly double: number) {
    Object.freeze(this);
  }
}
export type Numeric = number | Decimal;
export function isNumber(value: unknown): value is Numeric { return typeof value === "number" || value instanceof Decimal; }
export function numberValue(value: Numeric): number { return typeof value === "number" ? value : value.double; }
export function numericToken(token: string, budget: Budget): Numeric | undefined {
  budget.step(Math.ceil(token.length / 32));
  const end = token.indexOf("\0");
  const text = end < 0 ? token : token.slice(0, end);
  if (/^[+-]?s?nan[0-9]*$/iu.test(text)) return new Decimal("0", NaN, false, "null", NaN);
  if (/^[+-]?inf(?:inity)?$/iu.test(text)) {
    const negative = text[0] === "-";
    const value = negative ? -Infinity : Infinity;
    return new Decimal("1", Infinity, negative, numberText(value), value);
  }
  if (!/^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$/u.test(text)) return undefined;
  return decimalNumber(text[0] === "+" ? text.slice(1) : text, budget);
}

function increment(digits: string): string {
  let position = digits.length - 1;
  while (position >= 0 && digits[position] === "9") position--;
  return position < 0 ? `1${"0".repeat(digits.length)}` : `${digits.slice(0, position)}${Number(digits[position]) + 1}${"0".repeat(digits.length - position - 1)}`;
}
function decimalDouble(digits: string, exponent: number, negative: boolean): number {
  let rounded = digits;
  if (digits.length > 17) {
    rounded = digits.slice(0, 17);
    const next = digits[17]!;
    if (next > "5" || (next === "5" && (/[1-9]/u.test(digits.slice(18)) || Number(rounded[16]) % 2 !== 0))) rounded = increment(rounded);
    exponent += digits.length - 17;
  }
  return Number(`${negative ? "-" : ""}${rounded}e${exponent}`);
}
function decimalText(digits: string, exponent: number, negative: boolean): string {
  const sign = negative ? "-" : "";
  const adjusted = exponent + digits.length - 1;
  if (exponent > 0 || adjusted < -6) return `${sign}${digits[0]}${digits.length > 1 ? `.${digits.slice(1)}` : ""}E${adjusted >= 0 ? "+" : ""}${adjusted}`;
  const point = digits.length + exponent;
  if (point <= 0) return `${sign}0.${"0".repeat(-point)}${digits}`;
  return `${sign}${digits.slice(0, point)}${point < digits.length ? `.${digits.slice(point)}` : ""}`;
}
export function decimalNumber(token: string, budget: Budget): Numeric {
  budget.text(token);
  budget.step(Math.ceil(token.length / 32));
  const negative = token[0] === "-";
  const unsigned = negative ? token.slice(1) : token;
  const marker = unsigned.search(/[eE]/u);
  const coefficient = marker < 0 ? unsigned : unsigned.slice(0, marker);
  const point = coefficient.indexOf(".");
  let exponent = (marker < 0 ? 0 : Number(unsigned.slice(marker + 1))) - (point < 0 ? 0 : coefficient.length - point - 1);
  let digits = coefficient.replace(".", "").replace(/^0+/u, "") || "0";
