import { setImmediate } from "node:timers/promises";
import { FsError, readBytes, writeBytes, type ByteSource, type CommandContext, type CommandDefinition } from "../../contracts/index.js";

export interface TextProgramOptions {
  readonly replace?: boolean;
  readonly maxSteps?: number;
  readonly maxBufferBytes?: number;
}

export class ProgramError extends Error {}

export class Budget {
  readonly maxBufferBytes: number;
  private remaining: number;
  private checkpoints = 0;
  constructor(readonly context: CommandContext, options: TextProgramOptions) {
    this.remaining = options.maxSteps ?? 5_000_000;
    this.maxBufferBytes = options.maxBufferBytes ?? 32 * 1024 * 1024;
    for (const value of [this.remaining, this.maxBufferBytes]) {
      if (!Number.isSafeInteger(value) || value < 1) throw new ProgramError("limits must be positive safe integers");
    }
  }
  step(count = 1): void {
    this.context.signal.throwIfAborted();
    this.remaining -= count;
    if (this.remaining < 0) throw new ProgramError("execution step limit exceeded");
  }
  check(text: string): string {
    if (text.length > this.maxBufferBytes) throw new ProgramError("text buffer limit exceeded");
    return text;
  }
  async checkpoint(): Promise<void> {
    if (++this.checkpoints % 256 === 0) await setImmediate(undefined, { signal: this.context.signal });
    this.context.signal.throwIfAborted();
  }
}

export function byteString(text: string): string { return Buffer.from(text, "utf8").toString("latin1"); }
export function bytes(text: string): Uint8Array { return Buffer.from(text, "latin1"); }

export function virtualPath(context: CommandContext, path: string): string {
  if (!path) throw new FsError("ENOENT", { path });
  if (path.includes("\0")) throw new FsError("EINVAL", { path });
  return path.startsWith("/") ? path : `${context.cwd.replace(/\/$/u, "")}/${path}`;
}

export async function write(context: CommandContext, text: string): Promise<void> {
  context.signal.throwIfAborted();
  await writeBytes(context.stdout, bytes(text), context.signal);
}

export async function* input(context: CommandContext, file = "-"): ByteSource {
  context.signal.throwIfAborted();
  if (file === "-") yield* readBytes(context.stdin, context.signal);
  else {
    const path = virtualPath(context, file);
    if (context.fs.readStream) yield* readBytes(context.fs.readStream(path, { signal: context.signal }), context.signal);
    else yield await context.fs.readFile(path, { signal: context.signal, maxBytes: 32 * 1024 * 1024 });
  }
}

export async function readProgram(context: CommandContext, file: string): Promise<string> {
  const contents = await context.fs.readFile(virtualPath(context, file), { signal: context.signal, maxBytes: 1024 * 1024 });
  return Buffer.from(contents).toString("latin1");
}

export interface RecordLine { readonly text: string; readonly terminated: boolean; readonly file: string; readonly fileIndex: number }

export async function* lineRecords(context: CommandContext, files: readonly string[], budget: Budget): AsyncGenerator<RecordLine> {
  const names = files.length ? files : ["-"];
  for (let fileIndex = 0; fileIndex < names.length; fileIndex++) {
    const file = names[fileIndex]!;
    let pending = "";
    for await (const chunk of input(context, file)) {
      budget.step();
      const text = Buffer.from(chunk).toString("latin1");
      let start = 0;
      let end: number;
      while ((end = text.indexOf("\n", start)) >= 0) {
        yield { text: budget.check(pending + text.slice(start, end)), terminated: true, file, fileIndex };
        pending = ""; start = end + 1;
      }
      pending = budget.check(pending + text.slice(start));
    }
    if (pending) yield { text: pending, terminated: false, file, fileIndex };
  }
}

export function command(name: string, run: (context: CommandContext) => Promise<number>): CommandDefinition {
  return {
    name,
    async execute(context) {
      context.signal.throwIfAborted();
      try { return { exitCode: await run(context) }; }
      catch (error) {
        context.signal.throwIfAborted();
        await writeBytes(context.stderr, new TextEncoder().encode(`${name}: ${error instanceof Error ? error.message : String(error)}\n`), context.signal);
        return { exitCode: error instanceof ProgramError ? 2 : 1 };
      }
    },
  };
}

import { FsError, resolvePath } from "../../contracts/index.js";
import { TimeZone, millisecondsInstant, parseDate } from "./calendar.js";
import { formatDate } from "./format.js";
import { command, CommandFailure, emit, ownEnvironment, type Settings } from "./shared.js";

interface DateArguments {
  readonly input?: string;
  readonly reference?: string;
  readonly utc: boolean;
  readonly format: string;
  readonly informational?: "help" | "version";
}

function parseArguments(args: readonly string[]): DateArguments {
  let input: string | undefined, reference: string | undefined, format: string | undefined, style: string | undefined;
  let utc = false, ended = false;
  const formatted = (value: string): void => {
    if (style !== undefined) throw new CommandFailure("multiple output formats specified");
    style = value;
  };
  const iso = (value: string): string => {
    switch (value) {
      case "date": return "%F";
      case "hours": return "%FT%H%:z";
      case "minutes": return "%FT%H:%M%:z";
      case "seconds": return "%FT%T%:z";
      case "ns": return "%FT%T,%N%:z";
      default: throw new CommandFailure(`unsupported ISO precision: ${value}`);
    }
  };
  for (let index = 0; index < args.length; index++) {
    const argument = args[index]!;
    if (!ended && argument === "--") { ended = true; continue; }
    if (!ended && argument.startsWith("--")) {
      const separator = argument.indexOf("=");
      const name = separator < 0 ? argument : argument.slice(0, separator);
      const attached = separator < 0 ? undefined : argument.slice(separator + 1);
      const required = (): string => {
        const value = attached ?? args[++index];
        if (value === undefined) throw new CommandFailure(`option requires an argument: ${name}`);
        return value;
      };
      if (["--help", "--version", "--utc", "--universal", "--rfc-email", "--rfc-2822"].includes(name) && attached !== undefined) {
        throw new CommandFailure(`option does not allow an argument: ${name}`);
      }
      switch (name) {
        case "--help": return { utc, format: "", informational: "help" };
        case "--version": return { utc, format: "", informational: "version" };
        case "--utc": case "--universal": utc = true; break;
        case "--date": input = required(); break;
        case "--reference": reference = required(); break;
        case "--iso-8601": formatted(iso(attached ?? "date")); break;
        case "--rfc-email": case "--rfc-2822": formatted("%a, %d %b %Y %T %z"); break;
        case "--rfc-3339": {
          const precision = required();
          if (!["date", "seconds", "ns"].includes(precision)) throw new CommandFailure(`unsupported RFC3339 precision: ${precision}`);
          formatted(precision === "date" ? "%F" : precision === "ns" ? "%F %T.%N%:z" : "%F %T%:z");
          break;
        }
        case "--set": throw new CommandFailure("setting clocks is unsupported");
        default: throw new CommandFailure(`unsupported option: ${name}`);
      }
    } else if (!ended && argument.startsWith("-") && argument !== "-") {
      for (let position = 1; position < argument.length; position++) {
        const flag = argument[position]!;
        if (flag === "u") utc = true;
        else if (flag === "R") formatted("%a, %d %b %Y %T %z");
        else if (flag === "I") { formatted(iso(argument.slice(position + 1) || "date")); break; }
        else if (flag === "d" || flag === "r") {
          const value = argument.slice(position + 1) || args[++index];
          if (value === undefined) throw new CommandFailure(`option requires an argument: -${flag}`);
          if (flag === "d") input = value; else reference = value;
          break;
        } else if (flag === "s") throw new CommandFailure("setting clocks is unsupported");
        else throw new CommandFailure(`unsupported option: -${flag}`);
      }
    } else {
      if (!argument.startsWith("+")) throw new CommandFailure("expected +FORMAT; clock-setting operands are unsupported");
      if (format !== undefined) throw new CommandFailure("extra format operand");
      format = argument.slice(1);
    }
  }
  if (input !== undefined && reference !== undefined) throw new CommandFailure("--date and --reference are mutually exclusive");
  if (format !== undefined && style !== undefined) throw new CommandFailure("multiple output formats specified");
  return { utc, format: format ?? style ?? "%a %b %e %T %Z %Y",
    ...(input === undefined ? {} : { input }), ...(reference === undefined ? {} : { reference }) };
}

export function createDateCommand(configuration: Settings) {
  new TimeZone(configuration.defaultTimeZone);
  return command("date", configuration, async context => {
    const parsed = parseArguments(context.args);
    if (parsed.informational) {
      await emit(context, parsed.informational === "version" ? "date (safe-bash virtual command)\n"
        : "Usage: date [-u] [-d DATE | -r FILE] [+FORMAT]\nAlso: -I[date|hours|minutes|seconds|ns], -R, --rfc-3339=PRECISION\nDATE accepts @seconds, ISO calendar/time, RFC dates, now/today/yesterday/tomorrow, and integer seconds/minutes/hours relative to now.\nVirtual TZ defaults to UTC; no clock setting or host-locale parsing.\n", configuration.limits);
      return 0;
    }
    const zone = new TimeZone(parsed.utc ? "UTC" : ownEnvironment(context, "TZ") ?? configuration.defaultTimeZone);
    let current: bigint | undefined;
    const now = (): bigint => current ??= millisecondsInstant(configuration.clock());
    let instant: bigint;
    if (parsed.reference !== undefined) {
      try {
        if (!parsed.reference) throw new FsError("ENOENT", { path: parsed.reference });
        const stat = await context.fs.stat(resolvePath(context.cwd, parsed.reference), { signal: context.signal });
        context.signal.throwIfAborted();
        instant = millisecondsInstant(stat.mtimeMs);
      } catch (error) {
        context.signal.throwIfAborted();
        if (error instanceof FsError) throw new CommandFailure(error.message);
        throw error;
      }
    } else instant = parsed.input === undefined ? now() : parseDate(parsed.input, zone, now);
    await emit(context, formatDate(parsed.format, instant, zone, configuration.limits), configuration.limits);
    return 0;
  });
}

import { checkSize, CommandFailure, type TimeEnvLimits } from "./shared.js";
import { floorDivide, monthNames, nanosecondsPerSecond, TimeZone, utcMilliseconds, weekdayNames } from "./calendar.js";

function offsetText(offset: number, colons: number): { value: string; width: number } {
  const sign = offset < 0 ? "-" : "+";
  const total = Math.abs(offset);
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor(total % 3600 / 60).toString().padStart(2, "0");
  const seconds = (total % 60).toString().padStart(2, "0");
  if (colons === 0) return { value: `${sign}${hours * 100 + Number(minutes)}`, width: 5 };
  if (colons === 2 || (colons === 3 && seconds !== "00")) return { value: `${sign}${hours}:${minutes}:${seconds}`, width: 9 };
  if (colons === 1 || minutes !== "00") return { value: `${sign}${hours}:${minutes}`, width: 6 };
  return { value: `${sign}${hours}`, width: 3 };
}

export function formatDate(format: string, instant: bigint, zone: TimeZone, limits: TimeEnvLimits): string {
  const fields = zone.fields(instant);
  const midnight = utcMilliseconds({ ...fields, hour: 0, minute: 0, second: 0 });
  const weekday = new Date(midnight).getUTCDay();
  const ordinal = Math.floor((midnight - utcMilliseconds({ ...fields, month: 1, day: 1, hour: 0, minute: 0, second: 0 })) / 86400000) + 1;
  const thursday = new Date(midnight + (3 - (weekday + 6) % 7) * 86400000);
  const isoYear = thursday.getUTCFullYear();
  const isoWeek = 1 + Math.floor((thursday.getTime() - utcMilliseconds({ year: isoYear, month: 1, day: 1, hour: 0, minute: 0, second: 0 })) / 604800000);
  const nano = (instant - floorDivide(instant, nanosecondsPerSecond) * nanosecondsPerSecond).toString().padStart(9, "0");
  const number = (value: number, width = 2, padding = "0"): string => value.toString().padStart(width, padding);
  const time = `${number(fields.hour)}:${number(fields.minute)}:${number(fields.second)}`;
  const hour12 = fields.hour % 12 || 12;
  const meridian = fields.hour < 12 ? "AM" : "PM";
  const pieces: string[] = [];
  let size = 0;
  const append = (value: string): void => {
    size += Buffer.byteLength(value);
    checkSize(size + 1, limits.maxOutputBytes, "output");
    pieces.push(value);
  };
  for (let offset = 0; offset < format.length;) {
    const next = format.indexOf("%", offset);
    if (next < 0) { append(format.slice(offset)); break; }
    append(format.slice(offset, next));
    offset = next + 1;
    let padding: string | undefined, upper = false, swap = false;
    while (offset < format.length && "-_0^#".includes(format[offset]!)) {
      const flag = format[offset++]!;
      if (flag === "^") upper = true;
      else if (flag === "#") swap = true;
      else padding = flag === "-" ? "" : flag === "_" ? " " : "0";
    }
    let widthText = "";
    while (offset < format.length && /[0-9]/.test(format[offset]!)) widthText += format[offset++];
    const width = widthText ? Number(widthText) : undefined;
    if (width !== undefined) checkSize(width, limits.maxFormatWidth, "format width");
    let colons = 0;
    while (format[offset] === ":") { colons++; offset++; }
    const modifier = format[offset] === "E" || format[offset] === "O" ? format[offset++] : undefined;
    const code = format[offset++];
    if (!code || colons > 3 || (colons && code !== "z")) throw new CommandFailure("unsupported date format directive");
    if (code === "%" && (padding !== undefined || upper || swap || width !== undefined || modifier)) {
      throw new CommandFailure("only an unmodified %% literal is supported");
    }
    if (modifier && !(modifier === "E" ? "cCxXyY" : "deHImMSuUVwWy").includes(code)) throw new CommandFailure(`unsupported date format modifier: %${modifier}${code}`);
    let value: string, defaultWidth = 0, defaultPadding = "0";
    switch (code) {
      case "%": value = "%"; break;
      case "a": value = weekdayNames[weekday]!.slice(0, 3); break;
      case "A": value = weekdayNames[weekday]!; break;
      case "b": case "h": value = monthNames[fields.month - 1]!.slice(0, 3); break;
      case "B": value = monthNames[fields.month - 1]!; break;
      case "c": value = `${weekdayNames[weekday]!.slice(0, 3)} ${monthNames[fields.month - 1]!.slice(0, 3)} ${number(fields.day, 2, " ")} ${time} ${number(fields.year, 4)}`; break;
      case "C": value = String(Math.floor(fields.year / 100)); defaultWidth = 2; break;
      case "d": case "e": value = String(fields.day); defaultWidth = 2; if (code === "e") defaultPadding = " "; break;
      case "D": value = `${number(fields.month)}/${number(fields.day)}/${number(fields.year % 100, 2, padding ?? "0")}`; break;
      case "x": value = `${number(fields.month)}/${number(fields.day)}/${number(fields.year % 100)}`; break;
      case "F": {
        const yearWidth = width === undefined && padding === undefined ? 4 : Math.max(0, (width ?? 0) - 6);
        const year = padding === "" ? String(fields.year) : number(fields.year, yearWidth, padding ?? "0");
        append(`${year}-${number(fields.month)}-${number(fields.day)}`); continue;
      }
      case "g": value = String(Math.abs(isoYear % 100)); defaultWidth = 2; break;
      case "G": value = String(isoYear); defaultWidth = 4; break;
      case "H": case "k": value = String(fields.hour); defaultWidth = 2; if (code === "k") defaultPadding = " "; break;
      case "I": case "l": value = String(hour12); defaultWidth = 2; if (code === "l") defaultPadding = " "; break;
      case "j": value = String(ordinal); defaultWidth = 3; break;
      case "m": value = String(fields.month); defaultWidth = 2; break;
      case "M": value = String(fields.minute); defaultWidth = 2; break;
      case "n": value = "\n"; break;
      case "N": {
        const precision = width ?? 9;
        const digits = nano.slice(0, precision).replace(/0+$/, "") || "0";
        const length = padding === "" ? digits.length : precision;
        checkSize(size + length + 1, limits.maxOutputBytes, "output");
        append(padding === "" ? digits : digits.padEnd(precision, padding ?? "0")); continue;
      }
      case "p": value = meridian; break;
      case "P": value = meridian.toLowerCase(); break;
      case "q": value = String(Math.ceil(fields.month / 3)); defaultWidth = 1; break;
      case "r": value = `${number(hour12)}:${number(fields.minute)}:${number(fields.second)} ${meridian}`; break;
      case "R": value = `${number(fields.hour)}:${number(fields.minute)}`; break;
      case "s": value = floorDivide(instant, nanosecondsPerSecond).toString(); defaultWidth = 1; break;
      case "S": value = String(fields.second); defaultWidth = 2; break;
      case "t": value = "\t"; break;
      case "T": case "X": value = time; break;
      case "u": value = String(weekday || 7); defaultWidth = 1; break;
      case "U": value = String(Math.floor((ordinal - 1 + 7 - weekday) / 7)); defaultWidth = 2; break;
      case "V": value = String(isoWeek); defaultWidth = 2; break;
      case "w": value = String(weekday); defaultWidth = 1; break;
      case "W": value = String(Math.floor((ordinal - 1 + 7 - (weekday + 6) % 7) / 7)); defaultWidth = 2; break;
      case "y": value = String(fields.year % 100); defaultWidth = 2; break;
      case "Y": value = String(fields.year); defaultWidth = 4; break;
      case "z": { const offset = offsetText(fields.offset, colons); value = offset.value; defaultWidth = offset.width; break; }
      case "Z": value = fields.zone; break;
      default: throw new CommandFailure(`unsupported date format directive: %${code}`);
    }
    if (code === "P" || (swap && "pZ".includes(code))) value = value.toLowerCase();
    else if (upper || (swap && "aAbBh".includes(code))) value = value.toUpperCase();
    const fill = padding ?? (defaultWidth || code === "z" ? defaultPadding : " ");
    const minimum = width ?? defaultWidth;
    if (fill && minimum > value.length) value = /^[+-]/.test(value) && fill === "0"
      ? `${value[0]}${value.slice(1).padStart(minimum - 1, fill)}` : value.padStart(minimum, fill);
    append(value);
  }
  return pieces.join("") + "\n";
}

import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createPrintenvCommand } from "./printenv.js";
import { createDateCommand } from "./date.js";
import { createSleepCommand } from "./sleep.js";
import { settings, type TimeEnvCommandsOptions } from "./shared.js";
export type { TimeEnvCommandsOptions, TimeEnvLimits, SleepScheduler } from "./shared.js";

export function createTimeEnvCommands(options: TimeEnvCommandsOptions = {}): readonly CommandDefinition[] {
  const configuration = settings(options);
  return [createDateCommand(configuration), createSleepCommand(configuration), createPrintenvCommand(configuration)];
}

export function timeEnvCommands(options: TimeEnvCommandsOptions = {}): VirtualShellPlugin {
  const commands = createTimeEnvCommands(options);
  return { name: "time-env-commands", setup(host) {
    if (!options.replace) for (const definition of commands) {
      if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
    }
    for (const definition of commands) host.commands.register(definition, { replace: options.replace ?? false });
  } };
}

import { checkSize, command, CommandFailure, emit, ownEnvironment, type Settings } from "./shared.js";

export function createPrintenvCommand(configuration: Settings) {
  return command("printenv", configuration, async context => {
    let separator = "\n";
    let offset = 0;
    for (; offset < context.args.length; offset++) {
      const argument = context.args[offset]!;
      if (argument === "--") { offset++; break; }
      if (argument === "--help") {
        await emit(context, "Usage: printenv [-0|--null] [--] [NAME ...]\nPrint only the virtual command environment.\n", configuration.limits);
        return 0;
      }
      if (argument === "--version") {
        await emit(context, "printenv (safe-bash virtual command)\n", configuration.limits);
        return 0;
      }
      if (argument === "--null" || /^-0+$/.test(argument)) { separator = "\0"; continue; }
      if (argument.startsWith("-") && argument !== "-") throw new CommandFailure(`invalid option: ${argument}`, 2);
      break;
    }
    const names = context.args.slice(offset);
    const lines: string[] = [];
    let total = 0;
    let missing = false;
    const append = (value: string): void => {
      total += Buffer.byteLength(value) + 1;
      checkSize(total, configuration.limits.maxOutputBytes, "output");
      lines.push(value, separator);
    };
    if (names.length) {
      for (const name of names) {
        context.signal.throwIfAborted();
        const value = ownEnvironment(context, name);
        if (name.includes("=") || value === undefined) missing = true;
        else append(value);
      }
    } else {
      const keys = Object.getOwnPropertyNames(context.env);
      checkSize(keys.length, configuration.limits.maxEnvironmentEntries, "environment entry");
      for (const name of keys) {
        context.signal.throwIfAborted();
        append(`${name}=${context.env[name]!}`);
      }
    }
    await emit(context, lines.join(""), configuration.limits);
    return missing ? 1 : 0;
  });
}

import { FsError, writeBytes, type CommandContext, type CommandDefinition } from "../../contracts/index.js";

export interface SleepScheduler {
  now(): number;
  setTimeout(callback: () => void, milliseconds: number): unknown;
  clearTimeout(handle: unknown): void;
}

export interface TimeEnvLimits {
  readonly maxArguments: number;
  readonly maxArgumentBytes: number;
  readonly maxOutputBytes: number;
  readonly maxEnvironmentEntries: number;
  readonly maxFormatWidth: number;
}

export interface TimeEnvCommandsOptions {
  readonly replace?: boolean;
  readonly clock?: () => number;
  readonly defaultTimeZone?: string;
  readonly scheduler?: SleepScheduler;
  readonly maxTimerMilliseconds?: number;
  readonly limits?: Partial<TimeEnvLimits>;
}

export interface Settings {
  readonly clock: () => number;
  readonly defaultTimeZone: string;
  readonly scheduler: SleepScheduler;
  readonly maxTimerMilliseconds: number;
  readonly limits: TimeEnvLimits;
}

export function settings(options: TimeEnvCommandsOptions): Settings {
  const limits: TimeEnvLimits = { maxArguments: 4096, maxArgumentBytes: 65536, maxOutputBytes: 1024 * 1024,
    maxEnvironmentEntries: 10000, maxFormatWidth: 4096, ...options.limits };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid time-env limit: ${name}`);
  }
  const maxTimerMilliseconds = options.maxTimerMilliseconds ?? 2147483647;
  if (!Number.isInteger(maxTimerMilliseconds) || maxTimerMilliseconds < 1 || maxTimerMilliseconds > 2147483647) {
    throw new RangeError("maxTimerMilliseconds must be between1 and2147483647");
  }
  const scheduler: SleepScheduler = options.scheduler ?? {
    now: () => performance.now(),
    setTimeout: (callback, milliseconds) => setTimeout(callback, milliseconds),
    clearTimeout: handle => clearTimeout(handle as ReturnType<typeof setTimeout>),
  };
  if (typeof scheduler.now !== "function" || typeof scheduler.setTimeout !== "function" || typeof scheduler.clearTimeout !== "function") {
    throw new TypeError("Invalid sleep scheduler");
  }
  if (options.clock !== undefined && typeof options.clock !== "function") throw new TypeError("Invalid date clock");
  return { clock: options.clock ?? Date.now, defaultTimeZone: options.defaultTimeZone ?? "UTC",
    scheduler, maxTimerMilliseconds, limits };
}

export class CommandFailure extends Error {
  constructor(message: string, readonly exitCode = 1) { super(message); }
}

export function checkSize(size: number, maximum: number, label: string): void {
  if (size > maximum) throw new FsError("EFBIG", { message: `time-env ${label} limit exceeded` });
}

export async function emit(context: CommandContext, value: string, limits: TimeEnvLimits): Promise<void> {
  checkSize(Buffer.byteLength(value), limits.maxOutputBytes, "output");
  const bytes = new TextEncoder().encode(value);
  for (let offset = 0; offset < bytes.length; offset += 16384) {
    await writeBytes(context.stdout, bytes.slice(offset, offset + 16384), context.signal);
  }
}

export function command(name: string, configuration: Settings,
  execute: (context: CommandContext) => Promise<number>): CommandDefinition {
  return { name, async execute(context) {
    context.signal.throwIfAborted();
    checkSize(context.args.length, configuration.limits.maxArguments, "argument count");
    let size = 0;
    for (const argument of context.args) {
      size += Buffer.byteLength(argument);
      checkSize(size, configuration.limits.maxArgumentBytes, "argument");
    }
    try { return { exitCode: await execute(context) }; }
    catch (error) {
      context.signal.throwIfAborted();
      if (!(error instanceof CommandFailure)) throw error;
      await writeBytes(context.stderr, new TextEncoder().encode(`${name}: ${error.message}\n`), context.signal);
      return { exitCode: error.exitCode };
    }
  } };
}

export function ownEnvironment(context: CommandContext, name: string): string | undefined {
  return Object.hasOwn(context.env, name) ? context.env[name] : undefined;
}

import { command, CommandFailure, emit, type Settings } from "./shared.js";

function duration(arguments_: readonly string[]): number {
  if (!arguments_.length) throw new CommandFailure("missing operand");
  const base = 1000000000n;
  const maximum = BigInt(Number.MAX_SAFE_INTEGER);
  const columns = new Map<bigint, bigint>();
  for (const value of arguments_) {
    const match = /^\+?((?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)([smhd]?)$/.exec(value);
    if (!match) throw new CommandFailure(`invalid time interval: ${value}`);
    const parts = /^(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/.exec(match[1]!)!;
    const fraction = parts[2] ?? "";
    const digits = `${parts[1]}${fraction}`.replace(/^0+/, "");
    if (!digits) continue;
    const scale = BigInt(parts[3] ?? "0") - BigInt(fraction.length) + 3n;
    const multiplier = match[2] === "d" ? 86400n : match[2] === "h" ? 3600n : match[2] === "m" ? 60n : 1n;
    const coefficient = (BigInt(digits) * multiplier).toString();
    if (BigInt(coefficient.length) + scale > 16n) throw new CommandFailure("time interval exceeds supported finite range");
    const shift = (scale % 9n + 9n) % 9n;
    let position = (scale - shift) / 9n;
    const aligned = coefficient + "0".repeat(Number(shift));
    for (let end = aligned.length; end > 0; end -= 9, position++) {
      const column = BigInt(aligned.slice(Math.max(0, end - 9), end));
      if (column) columns.set(position, (columns.get(position) ?? 0n) + column);
    }
  }
  let whole = 0n, fractional = false, carry = 0n, carryPosition = 0n;
  const collect = (value: bigint, position: bigint): void => {
    if (position < 0n) fractional ||= value !== 0n;
    else if (value) {
      if (position > 1n) throw new CommandFailure("time interval exceeds supported finite range");
      whole += value * base ** position;
      if (whole > maximum) throw new CommandFailure("time interval exceeds supported finite range");
    }
  };
  const ordered = [...columns].sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0);
  for (const [position, value] of ordered) {
    while (carry && carryPosition < position) {
      collect(carry % base, carryPosition++);
      carry /= base;
    }
    const combined = value + carry;
    collect(combined % base, position);
    carry = combined / base;
    carryPosition = position + 1n;
  }
  while (carry) {
    collect(carry % base, carryPosition++);
    carry /= base;
  }
  const rounded = whole + BigInt(fractional);
  if (rounded > maximum) throw new CommandFailure("time interval exceeds supported finite range");
  return Number(rounded);
}

function delay(milliseconds: number, signal: AbortSignal, configuration: Settings): Promise<void> {
  signal.throwIfAborted();
  if (milliseconds === 0) return Promise.resolve();
  const scheduler = configuration.scheduler;
  return new Promise<void>((resolve, reject) => {
    let handle: unknown;
    let armed = false;
    let settled = false;
    let started: number | undefined;
    let previous: number | undefined;
    const finish = (failed: boolean, reason?: unknown): void => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", aborted);
      try { if (armed) { armed = false; scheduler.clearTimeout(handle); } }
      catch (error) { reject(error); return; }
      if (failed) reject(reason);
      else resolve();
    };
    const aborted = (): void => finish(true, signal.reason);
    const schedule = (): void => {
      if (settled) return;
      try {
        signal.throwIfAborted();
        const now = scheduler.now();
        if (!Number.isFinite(now) || Math.abs(now) > Number.MAX_SAFE_INTEGER || (previous !== undefined && now < previous)) {
          throw new RangeError("sleep scheduler must supply finite monotonic milliseconds");
        }
        started ??= now;
        previous = now;
        const remaining = milliseconds - (now - started);
        if (remaining <= 0) { finish(false); return; }
        const timer = scheduler.setTimeout(() => { armed = false; schedule(); },
          Math.min(configuration.maxTimerMilliseconds, Math.max(1, Math.ceil(remaining))));
        if (settled) scheduler.clearTimeout(timer);
        else { handle = timer; armed = true; }
      } catch (error) { finish(true, error); }
    };
    signal.addEventListener("abort", aborted, { once: true });
    schedule();
  });
}

export function createSleepCommand(configuration: Settings) {
  return command("sleep", configuration, async context => {
    let informational: string | undefined;
    for (const argument of context.args) {
      if (argument === "--") break;
      if (argument === "--help" || argument === "--version") { informational = argument; break; }
      if (argument.startsWith("-") && argument !== "-") throw new CommandFailure(`invalid option: ${argument}`);
    }
    if (informational) {
      await emit(context, informational === "--help"
        ? "Usage: sleep NUMBER[smhd] ...\nSum finite nonnegative decimal durations; cancellation clears pending timers.\n"
        : "sleep (safe-bash virtual command)\n", configuration.limits);
      return 0;
    }
    await delay(duration(context.args), context.signal, configuration);
    return 0;
  });
}

import { UsageError, type WalkBudget } from "./io.js";
import { compile, type Pattern } from "./pattern.js";
import { environmentCharset, explicitCharset, type Charset } from "./charset.js";

export interface Arguments {
  all: boolean;
  directories: boolean;
  follow: boolean;
  full: boolean;
  indent: boolean;
  json: boolean;
  report: boolean;
  reverse: boolean;
  dirsFirst: boolean;
  charset: Charset;
  level: number | undefined;
  include: Pattern[];
  exclude: Pattern[];
  operands: string[];
  help: boolean;
  version: boolean;
}

export function parse(args: readonly string[], budget: WalkBudget): Arguments {
  budget.check(args.length, budget.limits.maxArguments, "argument count");
  let bytes = 0;
  for (const arg of args) {
    budget.check(bytes + arg.length, budget.limits.maxArgumentBytes, "argument");
    budget.check(bytes += Buffer.byteLength(arg), budget.limits.maxArgumentBytes, "argument");
    if (arg.includes("\0")) throw new UsageError("arguments must not contain NUL");
    if (/[\ud800-\udfff]/u.test(arg)) throw new UsageError("arguments must be well-formed Unicode");
  }
  const result: Arguments = { all: false, directories: false, follow: false, full: false, indent: true,
    json: false, report: true, reverse: false, dirsFirst: false, charset: "ASCII", level: undefined,
    include: [], exclude: [], operands: [], help: false, version: false };
  let ended = false;
  let explicit = false;
  for (let index = 0; index < args.length; index++) {
    const arg = args[index]!;
    const value = (option: string, attached: string | undefined): string => {
      if (attached !== undefined) return attached;
      if (++index >= args.length) throw new UsageError(`${option} requires a value`);
      return args[index]!;
    };
    if (ended || !arg.startsWith("-") || arg === "-") { result.operands.push(arg); continue; }
    if (arg === "--") { ended = true; continue; }
    if (arg === "--noreport") { result.report = false; continue; }
    if (arg === "--dirsfirst") { result.dirsFirst = true; continue; }
    if (arg === "--help") { result.help = true; continue; }
    if (arg === "--version") { result.version = true; continue; }
    if (arg === "--charset" || arg.startsWith("--charset=")) {
      result.charset = explicitCharset(value("--charset", arg.startsWith("--charset=") ? arg.slice(10) : undefined));
      explicit = true; continue;
    }
    if (arg.startsWith("--")) throw new UsageError(`unsupported option: ${arg}`);
    for (let offset = 1; offset < arg.length; offset++) {
      const flag = arg[offset]!;
      switch (flag) {
        case "a": result.all = true; break;
        case "d": result.directories = true; break;
        case "l": result.follow = true; break;
        case "f": result.full = true; break;
        case "i": result.indent = false; break;
        case "J": result.json = true; break;
        case "r": result.reverse = true; break;
        case "n": break;
        case "L": case "P": case "I": {
          const argument = value(`-${flag}`, offset + 1 < arg.length ? arg.slice(offset + 1) : undefined);
          if (flag === "L") {
            const level = Number(argument);
            if (!/^[0-9]+$/u.test(argument) || !Number.isSafeInteger(level) || level < 1 || level > budget.limits.maxDepth) {
              throw new UsageError(`-L must be between 1 and ${budget.limits.maxDepth}`);
            }
            result.level = level;
          } else (flag === "P" ? result.include : result.exclude).push(compile(argument, budget));
          offset = arg.length; break;
        }
        default: throw new UsageError(`unsupported option: -${flag}`);
      }
    }
  }
  if (!result.operands.length) result.operands.push(".");
  for (const operand of result.operands) if (operand === "") throw new UsageError("empty path operand");
  if (!explicit) result.charset = environmentCharset(budget);
  return result;
}

export const help = `Usage: tree [-adlfirnJ] [-L depth] [-P pattern] [-I pattern] [--dirsfirst]
            [--charset=ASCII|US-ASCII|UTF-8|UTF8] [--noreport] [--] [path ...]
Virtual filesystem tree; no native processes or implicit host access.
Default: visible entries, no symlink traversal, C/UTF-8-byte name order,
escaped filenames. Branch charset: --charset, TREE_CHARSET, virtual locale,
then ASCII; UTF-8 changes branches only. -l follows directory links; ancestor
cycles are skipped. -P includes files; -I excludes files and directories.
Basename patterns: *, ?, bracket ranges, | alternatives, backslash literals.
-J emits JSON; -i removes text branches or JSON formatting whitespace.
Unsupported options and path/globstar patterns are rejected before VFS I/O.
`;

import { UsageError, type WalkBudget } from "./io.js";

export type Charset = "ASCII" | "UTF-8";

const utf8Locales = new Set(["C.UTF-8", "C.utf8", "en_US.UTF-8", "en_US.utf8"]);

export function explicitCharset(value: string): Charset {
  const normalized = value.toUpperCase();
  if (normalized === "UTF-8" || normalized === "UTF8") return "UTF-8";
  if (normalized === "ASCII" || normalized === "US-ASCII") return "ASCII";
  throw new UsageError("supported charsets: ASCII, US-ASCII, UTF-8, UTF8");
}

export function environmentCharset(budget: WalkBudget): Charset {
  const { env } = budget.context;
  const ownValue = (name: string): string | undefined => {
    if (!Object.hasOwn(env, name)) return undefined;
    const value = env[name];
    if (value === undefined) return undefined;
    budget.check(value.length, budget.limits.maxPathBytes, "path/name");
    budget.step(value.length + 1);
    budget.text(value);
    return value;
  };
  const configured = ownValue("TREE_CHARSET");
  if (configured !== undefined) {
    const normalized = configured.toUpperCase();
    return normalized === "UTF-8" || normalized === "UTF8" ? "UTF-8" : "ASCII";
  }
  for (const name of ["LC_ALL", "LC_CTYPE", "LANG"]) {
    const locale = ownValue(name);
    if (locale) return utf8Locales.has(locale) ? "UTF-8" : "ASCII";
  }
  return "ASCII";
}

