import { TransformStream } from "node:stream/web";
import { FsError } from "./errors.js";

export type ByteSource = AsyncIterable<Uint8Array>;

export interface ByteSink {
  write(chunk: Uint8Array): Promise<void>;
  readonly ownedOutput?: {
    readonly consumerClosed: AbortSignal;
    write(chunk: Uint8Array): Promise<void>;
  };
}

export interface BytePipe {
  readonly readable: ByteSource;
  readonly writable: ByteSink;
  close(): Promise<void>;
  abort(reason?: unknown): Promise<void>;
}

export interface BytePipeOptions {
  readonly highWaterMark?: number;
  readonly signal?: AbortSignal;
}

export interface CollectOptions {
  readonly maxBytes: number;
  readonly signal?: AbortSignal;
}

export function createBytePipe(options: BytePipeOptions = {}): BytePipe {
  const highWaterMark = options.highWaterMark ?? 64 * 1024;
  const signal = options.signal;
  if (!Number.isSafeInteger(highWaterMark) || highWaterMark < 1) {
    throw new RangeError("highWaterMark must be a positive safe integer");
  }
  const stream = new TransformStream<Uint8Array, Uint8Array>(
    undefined,
    { highWaterMark: 1 },
    { highWaterMark, size: (chunk) => chunk.byteLength },
  );
  const reader = stream.readable.getReader();
  const writer = stream.writable.getWriter();
  let ended = false;
  let failed = false;
  let failure: unknown;
  let closePromise: Promise<void> | undefined;
  let abortPromise: Promise<void> | undefined;
  let finished = false;
  const consumer = new AbortController();
  const abort = (reason: unknown = new FsError("EPIPE", { syscall: "pipe" })): Promise<void> => {
    if (abortPromise) return abortPromise;
    if (finished) return Promise.resolve();
    failed = true;
    failure = reason;
    ended = true;
    consumer.abort(reason);
    abortPromise = Promise.allSettled([reader.cancel(reason), writer.abort(reason)]).then(() => {});
    return abortPromise;
  };
  const onAbort = (): void => { void abort(signal?.reason); };
  const cleanup = (): void => signal?.removeEventListener("abort", onAbort);
  void writer.closed.catch(() => {});
  void reader.closed.then(cleanup, cleanup);
  if (signal?.aborted) onAbort();
  else signal?.addEventListener("abort", onAbort, { once: true });
  const iterator = (async function* (): AsyncGenerator<Uint8Array> {
    try {
      while (true) {
        if (failed) throw failure;
        const result = await reader.read();
        if (failed) throw failure;
        if (result.done) {
          finished = true;
          return;
        }
        yield result.value;
      }
    } finally {
      if (!finished) await abort();
      reader.releaseLock();
    }
  })();
  const readable: AsyncIterableIterator<Uint8Array> = {
    [Symbol.asyncIterator]() { return this; },
    next() { return iterator.next(); },
    async return() {
      if (!finished) await abort();
      try {
        return await iterator.return(undefined);
      } finally {
        reader.releaseLock();
      }
    },
    async throw(reason) {
      await abort(reason);
      try {
        return await iterator.throw(reason);
      } finally {
        reader.releaseLock();
      }
    },
  };
  const write = async (chunk: Uint8Array): Promise<void> => {
    if (failed) throw failure;
    if (ended) throw new FsError("EPIPE", { syscall: "write" });
    if (!(chunk instanceof Uint8Array)) throw new TypeError("Byte sinks require Uint8Array chunks");
    if (chunk.byteLength > 0) await writer.write(new Uint8Array(chunk));
  };
  return {
    readable,
    writable: {
      write,
      ownedOutput: { consumerClosed: consumer.signal, write },
    },
    close() {
      if (failed) return Promise.reject(failure);
      ended = true;
      closePromise ??= writer.close();
      return closePromise;
    },
    abort,
  };
}

export function toByteSource(input: string | Uint8Array): ByteSource {
  if (typeof input !== "string" && !(input instanceof Uint8Array)) {
    throw new TypeError("Byte source input must be a string or Uint8Array");
  }
  const bytes = typeof input === "string" ? new TextEncoder().encode(input) : new Uint8Array(input);
  return (async function* () {
    if (bytes.byteLength > 0) yield bytes;
  })();
}

export async function writeText(sink: ByteSink, text: string): Promise<void> {
  await sink.write(new TextEncoder().encode(text));
}

export async function writeBytes(sink: ByteSink, chunk: Uint8Array, signal?: AbortSignal): Promise<void> {
  if (!(chunk instanceof Uint8Array)) throw new TypeError("Byte sinks require Uint8Array chunks");
  await abortable(() => sink.write(chunk), signal);
}

export async function pipeBytes(source: ByteSource, sink: ByteSink, signal?: AbortSignal): Promise<void> {
  signal?.throwIfAborted();
  for await (const chunk of readBytes(source, signal)) {
    await writeBytes(sink, chunk, signal);
  }
  signal?.throwIfAborted();
}

export async function collectBytes(source: ByteSource, options: CollectOptions): Promise<Uint8Array> {
  if (!Number.isSafeInteger(options.maxBytes) || options.maxBytes < 0) {
    throw new RangeError("maxBytes must be a nonnegative safe integer");
  }
  const chunks: Uint8Array[] = [];
  let size = 0;
  options.signal?.throwIfAborted();
  for await (const chunk of readBytes(source, options.signal)) {
    if (chunk.byteLength > options.maxBytes - size) {
      throw new FsError("EFBIG", { syscall: "collectBytes", message: "output exceeds maxBytes" });
    }
    if (chunk.byteLength > 0) chunks.push(new Uint8Array(chunk));
    size += chunk.byteLength;
  }
  options.signal?.throwIfAborted();
  const result = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return result;
}

export async function collectText(source: ByteSource, options: CollectOptions): Promise<string> {
  return new TextDecoder().decode(await collectBytes(source, options));
}

async function abortable<Result>(operation: () => PromiseLike<Result>, signal?: AbortSignal): Promise<Result> {
  signal?.throwIfAborted();
  if (!signal) return operation();
  return new Promise<Result>((resolve, reject) => {
    const onAbort = (): void => {
      signal.removeEventListener("abort", onAbort);
      reject(signal.reason);
    };
    signal.addEventListener("abort", onAbort, { once: true });
    try {
      Promise.resolve(operation()).then(
        (result) => {
          signal.removeEventListener("abort", onAbort);
          resolve(result);
        },
        (error: unknown) => {
          signal.removeEventListener("abort", onAbort);
          reject(error);
        },
      );
    } catch (error) {
      signal.removeEventListener("abort", onAbort);
      reject(error);
    }
  });
}

export async function* readBytes(source: ByteSource, signal?: AbortSignal): AsyncGenerator<Uint8Array> {
  signal?.throwIfAborted();
  const iterator = source[Symbol.asyncIterator]();
  let finished = false;
  let failed = false;
  try {
    while (true) {
      const result = await abortable(() => iterator.next(), signal);
      if (result.done) {
        finished = true;
        return;
      }
      if (!(result.value instanceof Uint8Array)) throw new TypeError("Byte sources must yield Uint8Array chunks");
      yield result.value;
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!finished && iterator.return) {
      const cleanup = Promise.resolve().then(() => iterator.return!());
      if (signal?.aborted) void cleanup.catch(() => {});
      else {
        try { await abortable(() => cleanup, signal); }
        catch (error) { if (!failed) throw error; }
      }
    }
  }
}

import type { CommandContext, InvocationCleanup } from "./command.js";
import { writeBytes, type ByteSink } from "./io.js";

export interface OutputOperation {
  readonly signal: AbortSignal;
  readonly output: ByteSink;
  child(destination: ByteSink): OutputOperation;
  registerCleanup(cleanup: InvocationCleanup): void;
  acquire<Value>(start: (signal: AbortSignal) => Value | Promise<Value>, release: (resource: Value) => void | Promise<void>): Promise<Value>;
  close(): Promise<void>;
}

export function createOutputOperation(context: Pick<CommandContext, "signal" | "registerCleanup">, destination: ByteSink): OutputOperation {
  const controller = new AbortController();
  const signal = controller.signal;
  const capability = destination.ownedOutput;
  const callbacks: InvocationCleanup[] = [];
  const children: OutputOperation[] = [];
  const closedReason = new Error("Output operation is closed");
  let accepting = true;
  let drain: Promise<void> | undefined;
  const assertOpen = (): void => {
    context.signal.throwIfAborted();
    signal.throwIfAborted();
    if (!accepting) throw closedReason;
  };
  const close = (): Promise<void> => {
    if (drain) return drain;
    accepting = false;
    drain = Promise.resolve().then(async () => {
      try {
        const results = await Promise.allSettled(callbacks.map(async cleanup => cleanup()));
        const failures = results.filter(result => result.status === "rejected").map(result => result.reason);
        if (failures.length === 1) throw failures[0];
        if (failures.length) throw new AggregateError(failures, "Output operation cleanup failed");
      } finally {
        context.signal.removeEventListener("abort", callerAbort);
        capability?.consumerClosed.removeEventListener("abort", outputAbort);
      }
    });
    void drain.catch(() => {});
    for (const child of children) void child.close().catch(() => {});
    return drain;
  };
  const abort = (reason: unknown): void => {
    controller.abort(reason);
    void close().catch(() => {});
  };
  const callerAbort = (): void => abort(context.signal.reason);
  const outputAbort = (): void => abort(capability?.consumerClosed.reason);
  const registerCleanup = (cleanup: InvocationCleanup): void => {
    assertOpen();
    if (typeof cleanup !== "function") throw new TypeError("Cleanup must be callable");
    callbacks.push(cleanup);
  };
  const wait = <Value>(pending: Promise<Value>): Promise<Value> => new Promise((resolve, reject) => {
    const aborted = (): void => reject(signal.reason);
    if (signal.aborted) aborted();
    else signal.addEventListener("abort", aborted, { once: true });
    pending.then(value => {
      signal.removeEventListener("abort", aborted);
      resolve(value);
    }, error => {
      signal.removeEventListener("abort", aborted);
      reject(error);
    });
  });
  context.registerCleanup?.(close);
  if (context.signal.aborted) callerAbort();
  else if (capability?.consumerClosed.aborted) outputAbort();
  else {
    context.signal.addEventListener("abort", callerAbort, { once: true });
    capability?.consumerClosed.addEventListener("abort", outputAbort, { once: true });
  }
  return {
    signal,
    output: {
      async write(chunk) {
        assertOpen();
        await writeBytes(capability ?? destination, chunk, signal);
      },
    },
    registerCleanup,
    child(destination) {
      assertOpen();
      const child = createOutputOperation({ signal, registerCleanup }, destination);
      children.push(child);
      return child;
    },
    async acquire<Value>(start: (signal: AbortSignal) => Value | Promise<Value>, release: (resource: Value) => void | Promise<void>) {
      assertOpen();
      let resource: { value: Value } | undefined;
      let settled!: () => void;
      const admitted = new Promise<void>(resolve => { settled = resolve; });
      let released: Promise<void> | undefined;
      const dispose = (): Promise<void> => {
        released ??= admitted.then(async () => { if (resource) await release(resource.value); });
        return released;
      };
      registerCleanup(dispose);
      let acquisition: Promise<Value>;
      try { acquisition = Promise.resolve(start(signal)); }
      catch (error) { acquisition = Promise.reject(error); }
      const pending = acquisition.then(async value => {
        resource = { value };
        settled();
        if (!accepting) {
          await dispose();
          throw signal.aborted ? signal.reason : closedReason;
        }
        return value;
      }, error => {
        settled();
        throw error;
      });
      return wait(pending);
    },
    close,
  };
}

import { posix } from "node:path";
import { FsError } from "./errors.js";

export const posixPath = posix;
export const basename = posix.basename;
export const dirname = posix.dirname;
export const extname = posix.extname;
export const joinPath = posix.join;
export const isAbsolutePath = posix.isAbsolute;

export function validatePath(path: string): void {
  if (typeof path !== "string" || path.includes("\0")) {
    throw new FsError("EINVAL", { syscall: "resolve", message: "paths must be strings without NUL bytes" });
  }
}

export function resolvePath(cwd: string, ...paths: string[]): string {
  validatePath(cwd);
  if (!posix.isAbsolute(cwd)) {
    throw new FsError("EINVAL", { syscall: "resolve", path: cwd, message: "cwd must be absolute" });
  }
  for (const path of paths) validatePath(path);
  return posix.resolve(cwd, ...paths);
}

export function normalizePath(path: string, cwd = "/"): string {
  return resolvePath(cwd, path);
}

export function relativePath(from: string, to: string): string {
  return posix.relative(normalizePath(from), normalizePath(to));
}

export function isPathWithin(root: string, path: string): boolean {
  const normalizedRoot = normalizePath(root);
  const normalizedPath = normalizePath(path);
  return normalizedRoot === "/"
    || normalizedPath === normalizedRoot
    || normalizedPath.startsWith(`${normalizedRoot}/`);
}

export function assertPathWithin(root: string, path: string): string {
  const normalizedPath = normalizePath(path);
  if (!isPathWithin(root, normalizedPath)) {
    throw new FsError("EACCES", { syscall: "resolve", path, message: "path escapes the allowed root" });
  }
  return normalizedPath;
}

import type { AsyncCommandHandler, CommandContext, CommandHandler, CommandRegistry, CommandResult } from "./command.js";
import type { FileSystemFactory } from "./filesystem.js";

export type Next = () => Promise<CommandResult>;

export type Middleware = (
  context: CommandContext,
  next: Next,
) => CommandResult | Promise<CommandResult>;

export interface PluginHost {
  readonly commands: CommandRegistry;
  use(middleware: Middleware): void;
  registerFileSystem(scheme: string, factory: FileSystemFactory): void;
}

export interface VirtualShellPlugin {
  readonly name: string;
  setup(host: PluginHost): void | Promise<void>;
  dispose?(): void | Promise<void>;
}

export function composeMiddleware(
  middleware: readonly Middleware[],
  terminal: CommandHandler,
): AsyncCommandHandler {
  const stack = [...middleware];
  if (typeof terminal !== "function" || stack.some((handler) => typeof handler !== "function")) {
    throw new TypeError("Middleware and terminal handlers must be functions");
  }
  return async (context) => {
    let lastIndex = -1;
    const dispatch = async (index: number): Promise<CommandResult> => {
      if (index <= lastIndex) throw new Error("next() may only be called once per middleware");
      lastIndex = index;
      context.signal.throwIfAborted();
      const handler = stack[index];
      if (!handler) return terminal(context);
      let active = true;
      let downstream: Promise<CommandResult> | undefined;
      let downstreamPending = false;
      const next: Next = () => {
        const result = active
          ? dispatch(index + 1)
          : Promise.reject<CommandResult>(new Error("next() cannot be called after middleware completed"));
        if (active && !downstream) {
          downstream = result;
          downstreamPending = true;
          void result.then(
            () => { downstreamPending = false; },
            () => { downstreamPending = false; },
          );
        } else void result.catch(() => {});
        return result;
      };
      try {
        const result = await handler(context, next);
        if (downstreamPending) throw new Error("Middleware must await or return next()");
        return result;
      } finally {
        active = false;
        if (downstream) await downstream.then(() => {}, () => {});
      }
    };
    return dispatch(0);
  };
}

import { AsyncLocalStorage } from "node:async_hooks";
import { FsError } from "../../contracts/errors.js";
import type { EntryComparison, FileStat, FileSystem, FsOptions } from "../../contracts/filesystem.js";
import { compareIdentity } from "./identity.js";

export interface EntryLocation {
  readonly filesystem: FileSystem;
  readonly path: string;
  readonly readOnly?: boolean;
  readonly stat?: FileStat;
}

export interface EntryView extends EntryLocation {
  readonly stat: FileStat;
  readonly readOnly: boolean;
}

export type EntryViewResolver = (path: string, options: FsOptions) => Promise<EntryLocation>;
export type EntryAuthority = (own: EntryView, peer: EntryView, options: FsOptions) => Promise<EntryComparison>;

const resolvers = new WeakMap<FileSystem, EntryViewResolver>();
const authorities = new WeakMap<FileSystem, EntryAuthority>();
const negotiating = new AsyncLocalStorage<boolean>();

export function registerEntryView(filesystem: FileSystem, resolver: EntryViewResolver): void {
  if (resolvers.has(filesystem)) throw new TypeError("entry view already registered");
  resolvers.set(filesystem, resolver);
}

export function registerEntryAuthority(filesystem: FileSystem, authority: EntryAuthority): void {
  if (authorities.has(filesystem)) throw new TypeError("entry authority already registered");
  authorities.set(filesystem, authority);
}

export async function resolveEntryView(filesystem: FileSystem, path: string, options: FsOptions = {}): Promise<EntryView> {
  let location: EntryLocation = { filesystem, path };
  let readOnly = false;
  const visited = new Set<FileSystem>();
  for (;;) {
    options.signal?.throwIfAborted();
    if (visited.has(location.filesystem)) throw new FsError("EIO", { path, message: "cyclic entry view" });
    visited.add(location.filesystem);
    readOnly ||= location.readOnly === true || location.filesystem.capabilities.readOnly === true;
    if (location.stat) return { filesystem: location.filesystem, path: location.path, stat: location.stat, readOnly };
    const resolve = resolvers.get(location.filesystem);
    if (!resolve) {
      let stat: FileStat;
      let followedPath: string;
      try {
        followedPath = await location.filesystem.realpath(location.path, options);
        options.signal?.throwIfAborted();
        stat = await location.filesystem.lstat(followedPath, options);
      }
      catch (error) { options.signal?.throwIfAborted(); throw error; }
      options.signal?.throwIfAborted();
      if (stat.type === "symlink") throw new FsError("EIO", { path, message: "followed entry changed during observation" });
      return { filesystem: location.filesystem, path: followedPath, stat, readOnly };
    }
    let next: EntryLocation;
    try { next = await resolve(location.path, options); }
    catch (error) { options.signal?.throwIfAborted(); throw error; }
    options.signal?.throwIfAborted();
    if (next.filesystem === location.filesystem && next.stat) {
      return { filesystem: next.filesystem, path: next.path, stat: next.stat, readOnly: readOnly || next.readOnly === true };
    }
    location = next;
  }
}

export async function compareResolvedEntries(own: EntryView, peer: EntryView, options: FsOptions = {}): Promise<EntryComparison> {
  options.signal?.throwIfAborted();
  if (negotiating.getStore()) return "unknown";
  const identity = compareIdentity(own.stat, peer.stat);
  if (identity !== "unknown") return identity;
  return negotiating.run(true, async () => {
    const queried = new Set<EntryAuthority | FileSystem>();
    let result: EntryComparison = "unknown";
    for (const [left, right] of [[own, peer], [peer, own]] as const) {
      options.signal?.throwIfAborted();
      const authority = authorities.get(left.filesystem);
      const key = authority ?? left.filesystem;
      if (queried.has(key)) continue;
      queried.add(key);
      let answer: EntryComparison;
      try {
        if (authority) answer = await authority(left, right, options);
        else if (left.filesystem.compareEntry) answer = await left.filesystem.compareEntry(left.path, right.filesystem, right.path, options);
        else continue;
      } catch (error) {
        options.signal?.throwIfAborted();
        throw error;
      }
      options.signal?.throwIfAborted();
      if (answer !== "same" && answer !== "distinct" && answer !== "unknown") {
        throw new FsError("EIO", { path: own.path, dest: peer.path, message: "invalid entry comparison answer" });
      }
      if (answer === "unknown") continue;
      if (result !== "unknown" && result !== answer) {
        throw new FsError("EIO", { path: own.path, dest: peer.path, message: "conflicting entry comparison answers" });
      }
      result = answer;
    }
    return result;
  });
}

export async function compareEntries(
  filesystem: FileSystem, path: string, peer: FileSystem, peerPath: string, options: FsOptions = {},
): Promise<EntryComparison> {
  options.signal?.throwIfAborted();
  if (negotiating.getStore()) return "unknown";
  const own = await resolveEntryView(filesystem, path, options);
  const other = await resolveEntryView(peer, peerPath, options);
  return compareResolvedEntries(own, other, options);
}

import type { FileStat } from "../../contracts/filesystem.js";

function complete(stat: FileStat): boolean {
  const { identityScope, dev, ino } = stat;
  return ((typeof identityScope === "object" && identityScope !== null) || typeof identityScope === "symbol")
    && typeof dev === "number" && Number.isSafeInteger(dev) && dev >= 0
    && typeof ino === "number" && Number.isSafeInteger(ino) && ino >= 0;
}

export function compareIdentity(left: FileStat | undefined, right: FileStat | undefined): "same" | "distinct" | "unknown" {
  if (!left || !right || !complete(left) || !complete(right)) return "unknown";
  return left.identityScope === right.identityScope && left.dev === right.dev && left.ino === right.ino
    ? "same" : "distinct";
}

import { ACCESS_MODES, FsError, readBytes } from "../../contracts/index.js";
import type {
  AppendFileOptions, ByteSource, CopyFileOptions, DirectoryEntry, FileStat,
  FileSystem, FileSystemCapabilities, FsOptions, MkdirOptions, ReadFileOptions,
  ReadStreamOptions, RemoveOptions, WriteFileOptions,
} from "../../contracts/index.js";
import { compareEntries, registerEntryView } from "../mount/comparison.js";

function readOnly(syscall: string, path: string, dest?: string): never {
  throw new FsError("EROFS", { syscall, path, ...(dest === undefined ? {} : { dest }) });
}

function snapshotStat(stat: FileStat): FileStat {
  const { type, size, allocatedBytes, mode, mtimeMs, atimeMs, ctimeMs, birthtimeMs, identityScope, ino, dev, nlink, uid, gid } = stat;
  return {
    type, size, mode, mtimeMs, atimeMs, ctimeMs,
    ...(allocatedBytes === undefined ? {} : { allocatedBytes }),
    ...(birthtimeMs === undefined ? {} : { birthtimeMs }),
    ...(identityScope === undefined ? {} : { identityScope }),
    ...(ino === undefined ? {} : { ino }),
    ...(dev === undefined ? {} : { dev }),
    ...(nlink === undefined ? {} : { nlink }),
    ...(uid === undefined ? {} : { uid }),
    ...(gid === undefined ? {} : { gid }),
  };
}

export class ReadOnlyFileSystem implements FileSystem {
  readonly #filesystem: FileSystem;
  readonly #capabilities: FileSystemCapabilities;

  constructor(filesystem: FileSystem) {
    this.#filesystem = filesystem;
    registerEntryView(this, async (path) => ({ filesystem: this.#filesystem, path, readOnly: true }));
    const streamingRead = typeof filesystem.readStream === "function" ? filesystem.capabilities.streamingRead : false;
    this.#capabilities = Object.freeze({
      readOnly: true,
      symlinks: filesystem.capabilities.symlinks === true && typeof filesystem.readlink === "function",
      hardlinks: false,
      permissions: false,
      timestamps: false,
      atomicRename: false,
      ...(streamingRead === undefined ? {} : { streamingRead }),
      streamingWrite: false,
    });
  }

  get capabilities(): FileSystemCapabilities {
    return this.#capabilities;
  }

  async readFile(path: string, options?: ReadFileOptions): Promise<Uint8Array> {
    return new Uint8Array(await this.#filesystem.readFile(path, options));
  }

  async stat(path: string, options?: FsOptions): Promise<FileStat> {
    return snapshotStat(await this.#filesystem.stat(path, options));
  }

  async lstat(path: string, options?: FsOptions): Promise<FileStat> {
    return snapshotStat(await this.#filesystem.lstat(path, options));
  }

  compareEntry(path: string, peer: FileSystem, peerPath: string, options: FsOptions = {}) {
    return compareEntries(this, path, peer, peerPath, options);
  }

  async readdir(path: string, options?: FsOptions): Promise<DirectoryEntry[]> {
    return (await this.#filesystem.readdir(path, options)).map((entry) => ({ name: entry.name, type: entry.type }));
  }

  async realpath(path: string, options?: FsOptions): Promise<string> {
    return this.#filesystem.realpath(path, options);
  }

  async access(path: string, mode: number = ACCESS_MODES.F_OK, options?: FsOptions): Promise<void> {
    if (!Number.isInteger(mode) || mode < 0 || mode > 7) {
      throw new FsError("EINVAL", { syscall: "access", path });
    }
    if ((mode & ACCESS_MODES.W_OK) !== 0) readOnly("access", path);
    return this.#filesystem.access(path, mode, options);
  }

  async readlink(path: string, options?: FsOptions): Promise<string> {
    if (typeof this.#filesystem.readlink !== "function") {
      throw new FsError("ENOTSUP", { syscall: "readlink", path });
    }
    return this.#filesystem.readlink(path, options);
  }

  async *readStream(path: string, options?: ReadStreamOptions): ByteSource {
    if (typeof this.#filesystem.readStream !== "function") {
      throw new FsError("ENOTSUP", { syscall: "readStream", path });
    }
    for await (const chunk of readBytes(this.#filesystem.readStream(path, options), options?.signal)) {
      yield new Uint8Array(chunk);
    }
  }

  async writeFile(path: string, _data: Uint8Array, _options?: WriteFileOptions): Promise<void> {
    readOnly("writeFile", path);
  }

  async appendFile(path: string, _data: Uint8Array, _options?: AppendFileOptions): Promise<void> {
    readOnly("appendFile", path);
  }

  async writeStream(path: string, _source: ByteSource, _options?: WriteFileOptions): Promise<void> {
    readOnly("writeStream", path);
  }

  async mkdir(path: string, _options?: MkdirOptions): Promise<void> {
    readOnly("mkdir", path);
  }

  async rm(path: string, _options?: RemoveOptions): Promise<void> {
    readOnly("rm", path);
  }

  async unlink(path: string, _options?: FsOptions): Promise<void> {
    readOnly("unlink", path);
  }

  async rmdir(path: string, _options?: FsOptions): Promise<void> {
    readOnly("rmdir", path);
  }

  async rename(source: string, destination: string, _options?: FsOptions): Promise<void> {
    readOnly("rename", source, destination);
  }

  async copyFile(source: string, destination: string, _options?: CopyFileOptions): Promise<void> {
    readOnly("copyFile", source, destination);
  }

  async symlink(target: string, path: string, _options?: FsOptions): Promise<void> {
    readOnly("symlink", target, path);
  }

  async link(existingPath: string, newPath: string, _options?: FsOptions): Promise<void> {
    readOnly("link", existingPath, newPath);
  }

  async chmod(path: string, _mode: number, _options?: FsOptions): Promise<void> {
    readOnly("chmod", path);
  }

  async utimes(path: string, _atimeMs: number, _mtimeMs: number, _options?: FsOptions): Promise<void> {
    readOnly("utimes", path);
  }

  async truncate(path: string, _length?: number, _options?: FsOptions): Promise<void> {
    readOnly("truncate", path);
  }
}

export function createReadOnlyFileSystem(filesystem: FileSystem): ReadOnlyFileSystem {
  return new ReadOnlyFileSystem(filesystem);
}

export function nativeAllocatedBytes(blocks: unknown, platform: string): number | undefined {
  if (platform !== "darwin" && platform !== "linux") return undefined;
  if (typeof blocks !== "number" || !Number.isSafeInteger(blocks) || blocks < 0) return undefined;
  const bytes = blocks * 512;
  return Number.isSafeInteger(bytes) ? bytes : undefined;
}

import { AsyncLocalStorage } from "node:async_hooks";
import { FsError } from "../../contracts/errors.js";
import type { EntryComparison, FileStat, FileSystem, FsOptions } from "../../contracts/filesystem.js";
import type { EntryView } from "../mount/comparison.js";
import type { S3HeadOutput, S3ObjectInput } from "./transport.js";

export interface OwnedS3Entry {
  readonly storage: object;
  readonly key: string;
}

interface HeadProof {
  readonly query: S3ObjectInput;
  readonly entry: OwnedS3Entry;
}

const queries = new AsyncLocalStorage<S3ObjectInput>();
const providerHeads = new WeakMap<S3HeadOutput, HeadProof>();
const acceptedHeads = new WeakMap<S3HeadOutput, OwnedS3Entry>();
const observedStats = new WeakMap<FileStat, { filesystem: FileSystem; path: string; entry: OwnedS3Entry }>();
const entries = new WeakMap<FileSystem, (view: EntryView) => OwnedS3Entry | undefined>();
const comparisons = new WeakMap<FileSystem, NonNullable<FileSystem["compareEntry"]>>();
const configuredComparisons = new WeakMap<FileSystem, NonNullable<FileSystem["compareEntry"]>>();

export function recordMockS3Head(output: S3HeadOutput, input: S3ObjectInput, storage: object): void {
  const query = queries.getStore();
  if (query && query.Bucket === input.Bucket && query.Key === input.Key) {
    providerHeads.set(output, { query, entry: { storage, key: input.Key } });
  }
}

export async function queryS3Head(input: S3ObjectInput, action: () => Promise<S3HeadOutput>): Promise<S3HeadOutput> {
  const query = { ...input };
  return queries.run(query, async () => {
    const output = await action();
    acceptedHeads.delete(output);
    const proof = providerHeads.get(output);
    if (proof?.query === query) acceptedHeads.set(output, proof.entry);
    return output;
  });
}

export function recordS3Stat(filesystem: FileSystem, path: string, stat: FileStat, metadata: S3HeadOutput | undefined): void {
  if (!metadata) return;
  const entry = acceptedHeads.get(metadata);
  acceptedHeads.delete(metadata);
  if (entry) observedStats.set(stat, { filesystem, path, entry });
}

export function registerS3EntryOwner(filesystem: FileSystem, normalize: (path: string) => string,
  intact: () => boolean, baseComparison: NonNullable<FileSystem["compareEntry"]>, comparison?: NonNullable<FileSystem["compareEntry"]>): void {
  comparisons.set(filesystem, baseComparison);
  if (comparison) configuredComparisons.set(filesystem, comparison);
  entries.set(filesystem, view => {
    if (!intact()) return undefined;
    const observation = observedStats.get(view.stat);
    return observation?.filesystem === filesystem && observation.path === normalize(view.path) ? observation.entry : undefined;
  });
}

export function getOwnedS3Entry(view: EntryView): OwnedS3Entry | undefined {
  return entries.get(view.filesystem)?.(view);
}

export async function compareOwnedS3Entries(own: EntryView, peer: EntryView, options: FsOptions): Promise<EntryComparison> {
  options.signal?.throwIfAborted();
  let explicit = false;
  let answer: EntryComparison = "unknown";
  const visited = new Set<FileSystem>();
  for (const [left, right] of [[own, peer], [peer, own]] as const) {
    const baseComparison = comparisons.get(left.filesystem);
    if (!baseComparison || visited.has(left.filesystem)) continue;
    visited.add(left.filesystem);
    const current = left.filesystem.compareEntry;
    const comparison = current === baseComparison ? configuredComparisons.get(left.filesystem) : current;
    if (current === baseComparison && comparison === undefined) continue;
    explicit = true;
    if (comparison === undefined) continue;
    options.signal?.throwIfAborted();
    if (typeof comparison !== "function") {
      throw new FsError("EIO", { path: own.path, dest: peer.path, message: "invalid explicit S3 comparison method" });
    }
    const result = await comparison.call(left.filesystem, left.path, right.filesystem, right.path, options);
    options.signal?.throwIfAborted();
    if (result !== "same" && result !== "distinct" && result !== "unknown") {
      throw new FsError("EIO", { path: own.path, dest: peer.path, message: "invalid explicit S3 comparison" });
    }
    if (result === "unknown") continue;
    if (answer !== "unknown" && answer !== result) {
      throw new FsError("EIO", { path: own.path, dest: peer.path, message: "conflicting explicit S3 comparisons" });
    }
    answer = result;
  }
  const left = getOwnedS3Entry(own);
  options.signal?.throwIfAborted();
  const right = getOwnedS3Entry(peer);
  options.signal?.throwIfAborted();
  const same = left && right && left.storage === right.storage && left.key === right.key;
  if (same && answer === "distinct") {
    throw new FsError("EIO", { path: own.path, dest: peer.path, message: "explicit S3 comparison contradicts a known alias" });
  }
  if (same) return "same";
  if (explicit) return answer;
  return left && right ? "distinct" : "unknown";
}

import { once } from "node:events";
import { request as httpRequest } from "node:http";
import type { ClientRequest, IncomingMessage, RequestOptions } from "node:http";
import { request as httpsRequest } from "node:https";
import { S3ServiceError } from "../transport.js";
import type { S3HttpRequestFactory } from "./types.js";

export interface RequestScope {
  readonly signal: AbortSignal;
  readonly finish: () => void;
}

export function scopeFor(signal: AbortSignal | undefined, timeout: number): RequestScope {
  const controller = new AbortController();
  const abort = (): void => controller.abort(signal?.reason);
  signal?.addEventListener("abort", abort, { once: true });
  if (signal?.aborted) abort();
  const timer = setTimeout(() => controller.abort(new S3ServiceError("RequestTimeout", 408)), timeout);
  return {
    signal: controller.signal,
    finish: () => { clearTimeout(timer); signal?.removeEventListener("abort", abort); },
  };
}

export async function abortable<Value>(pending: Promise<Value>, signal: AbortSignal): Promise<Value> {
  let abort: (() => void) | undefined;
  try {
    return await new Promise<Value>((resolve, reject) => {
      abort = () => reject(signal.reason);
      signal.addEventListener("abort", abort, { once: true });
      pending.then(resolve, reject);
      if (signal.aborted) abort();
    });
  } finally {
    if (abort) signal.removeEventListener("abort", abort);
  }
}

export interface WireResponse {
  readonly message: IncomingMessage;
  readonly body: AsyncIterable<Uint8Array>;
  readonly close: () => void;
}

export async function sendRequest(
  options: RequestOptions,
  body: Uint8Array,
  scope: RequestScope,
  factory?: S3HttpRequestFactory,
): Promise<WireResponse> {
  const signal = scope.signal;
  signal.throwIfAborted();
  return new Promise<WireResponse>((resolve, reject) => {
    let request: ClientRequest | undefined;
    let response: IncomingMessage | undefined;
    let headersReceived = false;
    let finished = false;
    const cleanup = (): void => {
      signal.removeEventListener("abort", abort);
      scope.finish();
    };
    const close = (): void => {
      if (finished) return;
      finished = true;
      cleanup();
      response?.destroy();
      request?.destroy();
    };
    const fail = (error: unknown): void => {
      reject(signal.aborted ? signal.reason : error);
      close();
    };
    const abort = (): void => fail(signal.reason);
    signal.addEventListener("abort", abort, { once: true });
    try {
      const create = factory ?? (options.protocol === "https:" ? httpsRequest : httpRequest);
      request = create(options, message => {
        response = message;
        message.on("error", () => {});
        if (finished || signal.aborted) { close(); message.destroy(); return; }
        headersReceived = true;
        message.once("close", cleanup);
        let claimed = false;
        const source: AsyncIterable<Uint8Array> = {
          [Symbol.asyncIterator]() {
            if (claimed) throw new S3ServiceError("InvalidResponse", 502, "response body is single-use");
            claimed = true;
            const iterator = message[Symbol.asyncIterator]();
            let ended = false;
            return {
              async next(): Promise<IteratorResult<Uint8Array>> {
                try {
                  signal.throwIfAborted();
                  if (ended) return { done: true, value: undefined };
                  const result = await abortable(iterator.next(), signal);
                  signal.throwIfAborted();
                  if (result.done) {
                    ended = true;
                    if (!message.complete) throw new S3ServiceError("InvalidResponse", 502, "incomplete HTTP response");
                    close();
                    return { done: true, value: undefined };
                  }
                  if (!(result.value instanceof Uint8Array)) throw new S3ServiceError("InvalidResponse", 502, "nonbinary HTTP body");
                  return { done: false, value: new Uint8Array(result.value) };
                } catch (error) { ended = true; close(); throw signal.aborted ? signal.reason : error; }
              },
              async return(): Promise<IteratorResult<Uint8Array>> {
                ended = true;
                close();
                return { done: true, value: undefined };
              },
            };
          },
        };
        resolve({ message, body: source, close });
      });
      request.on("error", fail);
      request.once("close", () => {
        if (!headersReceived) fail(new S3ServiceError("InvalidResponse", 502, "connection closed before response headers"));
      });
      if (signal.aborted || finished) { abort(); request.destroy(); return; }
      void (async () => {
        for (let offset = 0; offset < body.length; offset += 64 * 1024) {
          signal.throwIfAborted();
          if (!request!.write(body.subarray(offset, offset + 64 * 1024))) await once(request!, "drain", { signal });
        }
        signal.throwIfAborted();
        request!.end();
      })().catch(fail);
    } catch (error) { fail(error); }
  });
}

export function limitedBody(response: WireResponse, maximum: number, expected?: number): AsyncIterable<Uint8Array> {
  if (expected !== undefined && expected > maximum) {
    response.close();
    throw new S3ServiceError("EntityTooLarge", 413, "response exceeds byte limit");
  }
  let claimed = false;
  return {
    [Symbol.asyncIterator]() {
      if (claimed) throw new S3ServiceError("InvalidResponse", 502, "response body is single-use");
      claimed = true;
      const iterator = response.body[Symbol.asyncIterator]();
      let count = 0;
      return {
        async next(): Promise<IteratorResult<Uint8Array>> {
          try {
            const result = await iterator.next();
            if (result.done) {
              if (expected !== undefined && count !== expected) throw new S3ServiceError("InvalidResponse", 502, "response content length mismatch");
            } else {
              count += result.value.length;
              if (count > maximum) throw new S3ServiceError("EntityTooLarge", 413, "response exceeds byte limit");
              if (expected !== undefined && count > expected) throw new S3ServiceError("InvalidResponse", 502, "response content length mismatch");
            }
            return result;
          } catch (error) { response.close(); throw error; }
        },
        async return(): Promise<IteratorResult<Uint8Array>> {
          response.close();
          await iterator.return?.();
          return { done: true, value: undefined };
        },
      };
    },
  };
}

export async function collect(response: WireResponse, maximum: number, expected?: number): Promise<Uint8Array> {
  const chunks: Uint8Array[] = [];
  let count = 0;
  try {
    for await (const chunk of limitedBody(response, maximum, expected)) { chunks.push(chunk); count += chunk.length; }
    return Buffer.concat(chunks, count);
  } finally { response.close(); }
}

import { createHash, createHmac } from "node:crypto";
import { S3ServiceError } from "../transport.js";
import type { S3HttpCredentials } from "./types.js";

export function invalid(message: string): never {
  throw new S3ServiceError("InvalidArgument", 400, message);
}

export function uriEncode(value: string, preserveSlash = false): string {
  if (typeof value !== "string") invalid("expected a UTF-8 string");
  try {
    const encoded = encodeURIComponent(value).replace(/[!'()*]/g, character => `%${character.charCodeAt(0).toString(16).toUpperCase()}`);
    return preserveSlash ? encoded.replace(/%2F/g, "/") : encoded;
  } catch {
    return invalid("invalid Unicode string");
  }
}

export function canonicalQuery(entries: readonly (readonly [string, string])[]): string {
  return entries.map(([name, value]) => [uriEncode(name), uriEncode(value)] as const)
    .sort(([leftName, leftValue], [rightName, rightValue]) =>
      leftName < rightName ? -1 : leftName > rightName ? 1 : leftValue < rightValue ? -1 : leftValue > rightValue ? 1 : 0)
    .map(([name, value]) => `${name}=${value}`).join("&");
}

export function sha256(bytes: Uint8Array | string): string {
  return createHash("sha256").update(bytes).digest("hex");
}

export function headerValue(value: string): string {
  if (typeof value !== "string" || /[^\x20-\x7e\t]/.test(value)) invalid("header values must be printable ASCII without line breaks");
  return value.trim().replace(/[ \t]+/g, " ");
}

export function signRequest(input: {
  readonly method: string;
  readonly path: string;
  readonly query: string;
  readonly headers: Readonly<Record<string, string>>;
  readonly body: Uint8Array;
  readonly region: string;
  readonly credentials: S3HttpCredentials;
  readonly date: Date;
}): { readonly headers: Record<string, string>; readonly canonicalRequest: string; readonly signature: string } {
  const credentials = input.credentials;
  if (!credentials || typeof credentials.accessKeyId !== "string" || !/^[A-Za-z0-9_-]+$/.test(credentials.accessKeyId)
    || typeof credentials.secretAccessKey !== "string" || credentials.secretAccessKey.length === 0
    || credentials.secretAccessKey.length > 4096) invalid("explicit signing credentials are required");
  if (!/^[a-z0-9-]{1,64}$/.test(input.region)) invalid("invalid signing region");
  if (!(input.date instanceof Date) || !Number.isFinite(input.date.getTime())
    || input.date.getUTCFullYear() < 1970 || input.date.getUTCFullYear() > 9999) invalid("invalid signing clock");
  const timestamp = input.date.toISOString().replace(/[:-]|\.\d{3}/g, "");
  const date = timestamp.slice(0, 8);
  const headers: Record<string, string> = Object.create(null) as Record<string, string>;
  for (const [name, value] of Object.entries(input.headers)) {
    const lower = name.toLowerCase();
    if (!/^[a-z0-9-]+$/.test(lower) || lower in headers) invalid("invalid or duplicate signing header");
    headers[lower] = headerValue(value);
  }
  if (!headers.host) invalid("host is required for signing");
  const payloadHash = sha256(input.body);
  headers["x-amz-date"] = timestamp;
  headers["x-amz-content-sha256"] = payloadHash;
  if (credentials.sessionToken !== undefined) {
    headers["x-amz-security-token"] = headerValue(credentials.sessionToken);
    if (!headers["x-amz-security-token"]) invalid("session token must not be empty");
  }
  const names = Object.keys(headers).sort();
  const signedHeaders = names.join(";");
  const canonicalRequest = [input.method, input.path, input.query,
    names.map(name => `${name}:${headers[name]}\n`).join(""), signedHeaders, payloadHash].join("\n");
  const scope = `${date}/${input.region}/s3/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", timestamp, scope, sha256(canonicalRequest)].join("\n");
  let key = createHmac("sha256", `AWS4${credentials.secretAccessKey}`).update(date).digest();
  for (const part of [input.region, "s3", "aws4_request"]) key = createHmac("sha256", key).update(part).digest();
  const signature = createHmac("sha256", key).update(stringToSign).digest("hex");
  headers.authorization = `AWS4-HMAC-SHA256 Credential=${credentials.accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  if (Object.entries(headers).reduce((size, [name, value]) => size + name.length + value.length + 4, 0) > 16 * 1024) invalid("request headers exceed 16 KiB");
  return { headers, canonicalRequest, signature };
}

import type { ClientRequest, IncomingMessage, RequestOptions } from "node:http";

export interface S3HttpCredentials {
  readonly accessKeyId: string;
  readonly secretAccessKey: string;
  readonly sessionToken?: string;
}

export type S3HttpCredentialProvider = (options: { readonly signal: AbortSignal }) => Promise<S3HttpCredentials>;

export type S3HttpRequestFactory = (
  options: RequestOptions,
  onResponse: (response: IncomingMessage) => void,
) => ClientRequest;

export interface S3HttpTransportOptions {
  readonly endpoint: string;
  readonly region: string;
  readonly credentials: S3HttpCredentials | S3HttpCredentialProvider;
  readonly addressingStyle?: "path" | "virtual-hosted";
  readonly listUrlEncoding?: "percent" | "form";
  readonly clock?: () => Date;
  readonly request?: S3HttpRequestFactory;
  readonly allowInsecureHttp?: boolean;
  readonly maxPutBytes?: number;
  readonly maxGetBytes?: number;
  readonly maxXmlBytes?: number;
  readonly requestTimeoutMs?: number;
  readonly enableCopy?: boolean;
  readonly verifiedConditionalOperations?: {
    readonly put?: boolean;
    readonly copy?: boolean;
    readonly delete?: boolean;
  };
}

import { S3ServiceError } from "../transport.js";

export interface XmlNode {
  readonly name: string;
  readonly children: XmlNode[];
  text: string;
}

export function malformed(message = "invalid S3 XML response"): never {
  throw new S3ServiceError("InvalidResponse", 502, message);
}

function validCharacter(code: number): boolean {
  return code === 9 || code === 10 || code === 13 || (code >= 32 && code <= 0xd7ff)
    || (code >= 0xe000 && code <= 0xfffd) || (code >= 0x10000 && code <= 0x10ffff);
}

function decodeEntities(text: string): string {
  let result = "";
  let position = 0;
  while (position < text.length) {
    const start = text.indexOf("&", position);
    if (start < 0) return result + text.slice(position);
    result += text.slice(position, start);
    const end = text.indexOf(";", start + 1);
    if (end < 0 || end - start > 12) malformed("invalid XML entity");
    const entity = text.slice(start + 1, end);
    const named: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };
    if (Object.hasOwn(named, entity)) result += named[entity];
    else {
      const hexadecimal = entity.startsWith("#x");
      const digits = entity.slice(hexadecimal ? 2 : 1);
      if (!entity.startsWith("#") || !(hexadecimal ? /^[0-9a-fA-F]+$/ : /^[0-9]+$/).test(digits)) malformed("unknown XML entity");
      const code = Number.parseInt(digits, hexadecimal ? 16 : 10);
      if (!validCharacter(code)) malformed("invalid XML code point");
      result += String.fromCodePoint(code);
    }
    position = end + 1;
  }
  return result;
}

export function parseXml(bytes: Uint8Array): XmlNode {
  let xml: string;
  try { xml = new TextDecoder("utf-8", { fatal: true }).decode(bytes); }
  catch { return malformed("XML is not UTF-8"); }
  for (const character of xml) if (!validCharacter(character.codePointAt(0)!)) malformed("invalid XML character");
  xml = xml.replace(/\r\n?/g, "\n");
  let position = 0;
  let nodes = 0;
  let root: XmlNode | undefined;
  const stack: XmlNode[] = [];
  const whitespace = (): void => { while (position < xml.length && /[ \t\r\n]/.test(xml[position]!)) position++; };
  const name = (): string => {
    const start = position;
    if (!/[A-Za-z_]/.test(xml[position] ?? "")) malformed("invalid XML name");
    while (position < xml.length && /[A-Za-z0-9_.:-]/.test(xml[position]!)) position++;
    const result = xml.slice(start, position);
    if (result.length > 256) malformed("XML name too long");
    return result;
  };
  while (position < xml.length) {
    if (xml[position] !== "<") {
      const end = xml.indexOf("<", position);
      const text = xml.slice(position, end < 0 ? xml.length : end);
      if (text.includes("]]>")) malformed();
      const current = stack.at(-1);
      if (current) current.text += decodeEntities(text);
      else if (text.trim()) malformed("text outside XML root");
      position = end < 0 ? xml.length : end;
      continue;
    }
    if (xml.startsWith("<?xml ", position) && !root && position === 0) {
      const end = xml.indexOf("?>", position);
      if (end < 0 || end > 256) malformed();
      const declaration = xml.slice(position, end);
      if (!/^<\?xml\s+version\s*=\s*(?:"1\.0"|'1\.0')(?:\s+encoding\s*=\s*(?:"[Uu][Tt][Ff]-8"|'[Uu][Tt][Ff]-8'))?(?:\s+standalone\s*=\s*(?:"(?:yes|no)"|'(?:yes|no)'))?\s*$/.test(declaration)) malformed("unsupported XML declaration");
      position = end + 2;
      continue;
    }
    if (xml.startsWith("<!--", position)) {
      const end = xml.indexOf("-->", position + 4);
      const comment = xml.slice(position + 4, end);
      if (end < 0 || comment.includes("--") || comment.endsWith("-")) malformed();
      position = end + 3;
      continue;
    }
    if (xml.startsWith("<![CDATA[", position)) {
      const end = xml.indexOf("]]>", position + 9);
      const current = stack.at(-1);
      if (end < 0 || !current) malformed();
      current.text += xml.slice(position + 9, end);
      position = end + 3;
      continue;
    }
    position++;
    const closing = xml[position] === "/";
    if (closing) position++;
    const tag = name();
    if (closing) {
      whitespace();
      if (xml[position++] !== ">" || stack.pop()?.name !== tag) malformed("mismatched XML close tag");
      continue;
    }
    const attributes = new Set<string>();
    while (true) {
      const previous = position;
      whitespace();
      if (xml[position] === ">" || xml[position] === "/") break;
      if (previous === position || attributes.size >= 32) malformed("invalid XML attributes");
      const attribute = name();
      if (attributes.has(attribute)) malformed("duplicate XML attribute");
      attributes.add(attribute);
      whitespace();
      if (xml[position++] !== "=") malformed();
      whitespace();
      const quote = xml[position++];
      if (quote !== '"' && quote !== "'") malformed();
      const end = xml.indexOf(quote, position);
      if (end < 0 || xml.slice(position, end).includes("<")) malformed();
      decodeEntities(xml.slice(position, end));
      position = end + 1;
    }
    const selfClosing = xml[position] === "/";
    if (selfClosing) position++;
    if (xml[position++] !== ">") malformed();
    if (++nodes > 32_768 || stack.length >= 32) malformed("XML structure limit exceeded");
    const node: XmlNode = { name: tag, text: "", children: [] };
    const parent = stack.at(-1);
    if (parent) parent.children.push(node);
    else if (root) malformed("multiple XML roots");
    else root = node;
    if (!selfClosing) stack.push(node);
  }
  if (!root || stack.length) malformed("incomplete XML");
  return root;
}

export function children(node: XmlNode, name: string): XmlNode[] {
  return node.children.filter(child => child.name === name);
}

export function text(node: XmlNode, name: string, required = false): string | undefined {
  const matches = children(node, name);
  if (matches.length > 1 || (required && matches.length !== 1)) malformed(`invalid ${name} count`);
  const child = matches[0];
  if (child?.children.length) malformed(`invalid ${name} value`);
  return child?.text;
}

export function integer(value: string): number {
  if (!/^[0-9]+$/.test(value) || !Number.isSafeInteger(Number(value))) malformed("invalid integer");
  return Number(value);
}

export function timestamp(value: string): Date {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) malformed("invalid timestamp");
  return date;
}

