  readonly metadata?: Omit<MetadataCommandsOptions, "replace">;
  readonly archive?: Omit<ArchiveCommandsOptions, "replace">;
  readonly tableText?: Omit<TableTextCommandsOptions, "replace">;
  readonly streamInspection?: Omit<StreamInspectionCommandsOptions, "replace">;
  readonly streamFormat?: Omit<StreamFormatCommandsOptions, "replace">;
  readonly split?: Omit<SplitCommandsOptions, "replace">;
  readonly timeEnv?: Omit<TimeEnvCommandsOptions, "replace">;
  readonly tree?: Omit<TreeCommandsOptions, "replace">;
  readonly file?: Omit<FileCommandsOptions, "replace">;
  readonly column?: Omit<ColumnCommandsOptions, "replace">;
}

function executor(lookup: (name: string) => CommandDefinition | undefined): CommandHandler {
  return async context => {
    const command = lookup(context.command);
    if (command) return command.execute(context);
    await diagnostic(context, new Error("command not found"));
    return { exitCode: 127 };
  };
}

export function createAgentCommands(options: AgentCommandsOptions = {}): readonly CommandDefinition[] {
  const commands: CommandDefinition[] = [];
  const exprLimits = options.expr?.limits;
  commands.push(
    ...createStandardCommands({ execute: options.execute ?? executor(name => commands.find(command => command.name === name)), ...(options.regex === undefined ? {} : { regex: options.regex }) }),
    ...createTextProgramCommands({ ...options.text }),
    ...createStructuredCommands({ ...options.structured }),
    ...createSearchCommands({ ...options.search }),
    ...createByteCommands(),
    ...createDiffPatchCommands({ ...options.diffPatch }),
    ...createMetadataCommands({ ...options.metadata }),
    ...createArchiveCommands({ ...options.archive }),
    ...createTableTextCommands({ ...options.tableText }),
    ...createStreamInspectionCommands({ ...options.streamInspection }),
    ...createStreamFormatCommands({ ...options.streamFormat }),
    ...createSplitCommands({ ...options.split }),
    ...createTimeEnvCommands({ ...options.timeEnv }),
    ...createTreeCommands({ ...options.tree }),
    ...createFileCommands({ ...options.file }),
    ...createGrepAliasCommands(options.regex === undefined ? {} : { regex: options.regex }),
    ...createColumnCommands({ ...options.column }),
    ...createHtmlToMarkdownCommands({ ...options.htmlToMarkdown }),
    ...createDuCommands({ ...options.du }),
    ...createExprCommands({ ...(exprLimits === undefined ? {} : { limits: exprLimits }), ...(options.regex === undefined ? {} : { regex: options.regex }) }),
  );
  return new CommandRegistry(commands).list();
}

export function agentCommands(options: AgentCommandsOptions = {}): VirtualShellPlugin {
  return {
    name: "agent-commands",
    setup(host) {
      const definitions = createAgentCommands({ ...options, execute: options.execute ?? executor(name => host.commands.get(name)) });
      if (!options.replace) for (const definition of definitions) {
        if (host.commands.has(definition.name)) throw new Error(`Command already registered: ${definition.name}`);
      }
      for (const definition of definitions) host.commands.register(definition, { replace: options.replace ?? false });
    },
  };
}

import type { InvocationCleanup } from "../contracts/command.js";

export const invocationScope = Symbol("invocation cleanup scope");

export class InvocationScope {
  readonly #children = new Set<InvocationScope>();
  readonly #callbacks: InvocationCleanup[] = [];
  readonly #controller = new AbortController();
  #closed = false;
  #drain: Promise<void> | undefined;

  constructor(
    readonly callerSignal?: AbortSignal,
    readonly failures: unknown[] = [],
    readonly parent?: InvocationScope,
  ) {}

  get signal(): AbortSignal { return this.#controller.signal; }

  assertOpen(): void {
    this.callerSignal?.throwIfAborted();
    if (this.#closed) throw this.signal.reason;
    this.parent?.assertOpen();
  }

  child(): InvocationScope {
    this.assertOpen();
    const child = new InvocationScope(this.callerSignal, this.failures, this);
    this.#children.add(child);
    return child;
  }

  register(cleanup: InvocationCleanup): void {
    this.assertOpen();
    if (typeof cleanup !== "function") throw new TypeError("Cleanup must be callable");
    this.#callbacks.push(cleanup);
  }

  #seal(): void {
    if (this.#closed) return;
    this.#closed = true;
    for (const child of this.#children) child.#seal();
    this.#controller.abort(new Error("Invocation is closed"));
  }

  close(): Promise<void> {
    if (!this.#drain) {
      this.#drain = Promise.resolve().then(async () => {
        await Promise.all([
          ...this.#callbacks.map(async (cleanup) => {
            try { await cleanup(); } catch (error) { this.failures.push(error); }
          }),
          ...[...this.#children].map((child) => child.close()),
        ]);
      });
      this.#seal();
    }
    return this.#drain;
  }
}

export function throwCleanupFailures(failures: readonly unknown[]): void {
  if (failures.length === 1) throw failures[0];
  if (failures.length) throw new AggregateError(failures, "Invocation cleanup failed");
}

import type { Command, Script, Word } from "./parser.js";

const spelling = (word: Word): string => word.spelling ?? word.plain ?? "''";

function scriptText(script: Script, indent: string): string {
  return script.lists.map(list => list.pipelines.map((pipeline, index) =>
    `${index ? `${list.operators[index - 1]} ` : ""}${pipeline.negate ? "! " : ""}${pipeline.commands.map(command => commandText(command, indent)).join(" | ")}`,
  ).join(" ")).join(`;\n${indent}`);
}

function commandText(command: Command, indent: string): string {
  const nested = `${indent}    `;
  let text: string;
  switch (command.kind) {
    case "simple": text = command.words.map(spelling).join(" "); break;
    case "arithmetic": text = `(( ${command.source} ))`; break;
    case "group": text = `{ \n${nested}${scriptText(command.body, nested)}\n${indent}}`; break;
    case "subshell": text = `( ${scriptText(command.body, indent)} )`; break;
    case "function": text = `${command.name} () \n${indent}${commandText(command.body, indent)}`; break;
    case "if":
      text = command.branches.map((branch, index) => `${index ? "elif" : "if"} ${scriptText(branch.condition, indent)}; then\n${nested}${scriptText(branch.body, nested)};`).join(`\n${indent}`);
      if (command.otherwise) text += `\n${indent}else\n${nested}${scriptText(command.otherwise, nested)};`;
      text += `\n${indent}fi`;
      break;
    case "while": case "until": text = `${command.kind} ${scriptText(command.condition, indent)}; do\n${nested}${scriptText(command.body, nested)};\n${indent}done`; break;
    case "for": text = `for ${command.name}${command.words ? ` in ${command.words.map(spelling).join(" ")}` : ""};\ndo\n${nested}${scriptText(command.body, nested)};\n${indent}done`; break;
    case "case": text = `case ${spelling(command.subject)} in\n${command.clauses.map(clause => `${nested}${clause.patterns.map(spelling).join(" | ")})\n${nested}    ${scriptText(clause.body, `${nested}    `)}\n${nested}${clause.terminator === "esac" ? "" : clause.terminator}`).join("\n")}\n${indent}esac`; break;
  }
  for (const redirect of command.redirects) {
    const defaultDescriptor = redirect.operator.startsWith("<") ? 0 : 1;
    text += ` ${redirect.descriptor === defaultDescriptor ? "" : redirect.descriptor}${redirect.operator} ${spelling(redirect.target)}${redirect.move ? "-" : ""}`;
    if (redirect.document) text += `\n${redirect.document.body}${redirect.document.delimiter}\n`;
  }
  return text;
}

export function functionDisplay(name: string, body: Command): string {
  return `${name} () \n${commandText(body, "")}\n`;
}

